window.WMA11_TOPICS = [{"slug":"01_Indices_Surds","name":"Indices & Surds","count":13},{"slug":"02_Quadratics","name":"Quadratics","count":16},{"slug":"03_Simultaneous","name":"Simultaneous Equations","count":3},{"slug":"04_Inequalities","name":"Inequalities","count":5},{"slug":"05_Polynomials","name":"Polynomials","count":4},{"slug":"06_GraphsOfFunctions","name":"Graphs of Functions","count":18},{"slug":"07_Transformations","name":"Transformations","count":7},{"slug":"08_StraightLine","name":"Straight Line","count":17},{"slug":"09_BasicTrig","name":"Basic Trigonometry","count":6},{"slug":"10_Radians","name":"Radians","count":18},{"slug":"11_TrigFunctions","name":"Trigonometric Functions","count":16},{"slug":"12_Differentiation","name":"Differentiation","count":24},{"slug":"13_Integration","name":"Integration","count":32}];
window.WMA11_QUESTIONS = [{"id":"WMA11-01_2020_Jan_Q02","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":2,"marks":5,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q02_M05_01_Indices_Surds.png","downloadName":"WMA11-01_Y2020_Jan_Q02_M05_01_Indices_Surds.png","finalAnswer":"$(a)\\ y^3.\\quad (b)\\ \\dfrac{9}{y}.\\quad (c)\\ y^6$.","steps":[{"title":"Use y = 3^x","body":"Since $y=3^x$, powers of $3^x$ can be replaced by powers of $y$."},{"title":"Part (a)","body":"$3^{3x}=\\left(3^x\\right)^3=y^3$."},{"title":"Part (b)","body":"$\\dfrac{1}{3^{x-2}}=3^{2-x}=\\dfrac{3^2}{3^x}=\\dfrac9y$."},{"title":"Part (c)","body":"$\\dfrac{81}{9^{2-3x}}=\\dfrac{3^4}{(3^2)^{2-3x}}=\\dfrac{3^4}{3^{4-6x}}=3^{6x}=\\left(3^x\\right)^6=y^6$."}]},{"id":"WMA11-01_2022_MayJune_Q03","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":3,"marks":5,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q03_M05_01_Indices_Surds.png","downloadName":"WMA11-01_Y2022_MayJune_Q03_M05_01_Indices_Surds.png","finalAnswer":"$(a)\\ 2.\\quad (b)\\ \\dfrac{25}{4}+\\dfrac{13}{4}\\sqrt5$.","steps":[{"title":"Simplify the square roots","body":"$\\sqrt{180}=6\\sqrt5$ and $\\sqrt{80}=4\\sqrt5$."},{"title":"Complete part (a)","body":"$\\dfrac{\\sqrt{180}-\\sqrt{80}}{\\sqrt5}=\\dfrac{6\\sqrt5-4\\sqrt5}{\\sqrt5}=2$."},{"title":"Rationalise part (b)","body":"$\\dfrac{4\\sqrt5-5}{7-3\\sqrt5}\\times\\dfrac{7+3\\sqrt5}{7+3\\sqrt5}=\\dfrac{(4\\sqrt5-5)(7+3\\sqrt5)}{49-45}$."},{"title":"Expand and simplify","body":"The numerator is $28\\sqrt5+60-35-15\\sqrt5=25+13\\sqrt5$, so the expression is $\\dfrac{25+13\\sqrt5}{4}$."}]},{"id":"WMA11-01_2022_Oct_Q04","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":4,"marks":6,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q04_M06_01_Indices_Surds.png","downloadName":"WMA11-01_Y2022_Oct_Q04_M06_01_Indices_Surds.png","finalAnswer":"$(a)\\ x=-3,\\ 0,\\ \\dfrac52.\\quad (b)\\ y=\\dfrac{5\\sqrt{10}}{4}$.","steps":[{"title":"Factor f(x)","body":"$f(x)=x^2(2x+1)-15x=x(2x^2+x-15)$."},{"title":"Factor the quadratic","body":"$2x^2+x-15=(2x-5)(x+3)$."},{"title":"Solve f(x) = 0","body":"$x(2x-5)(x+3)=0$, so $x=0$, $x=\\dfrac52$, or $x=-3$."},{"title":"Use the substitution for part (b)","body":"The equation is the same as $f(u)=0$ with $u=y^{2/3}$."},{"title":"Choose the valid root","body":"Since $y>0$, $u=y^{2/3}>0$. The valid root is $u=\\dfrac52$, so $y^{2/3}=\\dfrac52$."},{"title":"Write y in surd form","body":"$y=\\left(\\dfrac52\\right)^{3/2}=\\sqrt{\\dfrac{125}{8}}=\\dfrac{5\\sqrt{10}}{4}$."}]},{"id":"WMA11-01_2023_Jan_Q05","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":5,"marks":6,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q05_M06_05_Polynomials.png","downloadName":"WMA11-01_Y2023_Jan_Q05_M06_05_Polynomials.png","finalAnswer":"$x=-2$.","steps":[{"title":"Let p = 3^x","body":"Then $9^x=3^{2x}=p^2$, $3^{x+2}=9p$, and $3^{x-1}=\\dfrac{p}{3}$."},{"title":"Substitute into the equation","body":"$3p^2+9p=1+\\dfrac{p}{3}$."},{"title":"Clear the fraction","body":"Multiplying by 3 gives $9p^2+27p=3+p$, hence $9p^2+26p-3=0$."},{"title":"Solve for p","body":"$9p^2+26p-3=(9p-1)(p+3)=0$, so $p=\\dfrac19$ or $p=-3$."},{"title":"Reject the negative value","body":"Since $p=3^x>0$, we reject $p=-3$. Therefore $3^x=\\dfrac19=3^{-2}$."},{"title":"Find x","body":"$x=-2$."}]},{"id":"WMA11-01_2023_MayJune_Q06","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":6,"marks":7,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q06_M07_05_Polynomials.png","downloadName":"WMA11-01_Y2023_MayJune_Q06_M07_05_Polynomials.png","finalAnswer":"$(a)\\ r^2-2+\\dfrac1{r^2}.\\quad (b)\\ 3-2\\sqrt2.\\quad (c)$ The expression equals $2$.","steps":[{"title":"Expand the square","body":"$\\left(r-\\dfrac1r\\right)^2=r^2-2+\\dfrac1{r^2}$."},{"title":"Rationalise the denominator","body":"$\\dfrac1{3+2\\sqrt2}\\times\\dfrac{3-2\\sqrt2}{3-2\\sqrt2}=\\dfrac{3-2\\sqrt2}{9-8}=3-2\\sqrt2$."},{"title":"Let r be the square root","body":"Let $r=\\sqrt{3+2\\sqrt2}$. Then $r^2=3+2\\sqrt2$ and $\\dfrac1{r^2}=3-2\\sqrt2$."},{"title":"Use part (a)","body":"$\\left(r-\\dfrac1r\\right)^2=r^2-2+\\dfrac1{r^2}=(3+2\\sqrt2)-2+(3-2\\sqrt2)=4$."},{"title":"Take the positive square root","body":"Since $r>1$, $r-\\dfrac1r>0$, so $r-\\dfrac1r=2$."}]},{"id":"WMA11-01_2023_Oct_Q02","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":2,"marks":4,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q02_M04_01_Indices_Surds.png","downloadName":"WMA11-01_Y2023_Oct_Q02_M04_01_Indices_Surds.png","finalAnswer":"$(a)\\ \\dfrac18x.\\quad (b)\\ \\dfrac{1}{256}x^{3/2}.\\quad (c)\\ 16x^{-2}$.","steps":[{"title":"Square root a","body":"$a^{1/2}=\\left(\\dfrac{1}{64}x^2\\right)^{1/2}=\\dfrac18x$."},{"title":"Cube b","body":"$b=16x^{-1/2}$, so $b^3=4096x^{-3/2}$."},{"title":"Find 16 divided by b cubed","body":"$\\dfrac{16}{b^3}=\\dfrac{16}{4096x^{-3/2}}=\\dfrac{1}{256}x^{3/2}$."},{"title":"Simplify ab over 2","body":"$\\dfrac{ab}{2}=\\dfrac{1}{2}\\left(\\dfrac{1}{64}x^2\\right)\\left(16x^{-1/2}\\right)=\\dfrac18x^{3/2}$."},{"title":"Raise to the power -4 over 3","body":"$\\left(\\dfrac18x^{3/2}\\right)^{-4/3}=8^{4/3}x^{-2}=16x^{-2}$."}]},{"id":"WMA11-01_2023_Oct_Q03","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":3,"marks":6,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q03_M06_01_Indices_Surds.png","downloadName":"WMA11-01_Y2023_Oct_Q03_M06_01_Indices_Surds.png","finalAnswer":"$(a)\\ 3\\sqrt3-2\\sqrt5.\\quad (b)\\ x=15\\sqrt3-10\\sqrt5$.","steps":[{"title":"Rationalise the denominator","body":"$\\dfrac{8-\\sqrt{15}}{2\\sqrt3+\\sqrt5}\\times\\dfrac{2\\sqrt3-\\sqrt5}{2\\sqrt3-\\sqrt5}=\\dfrac{(8-\\sqrt{15})(2\\sqrt3-\\sqrt5)}{12-5}$."},{"title":"Simplify the numerator","body":"$(8-\\sqrt{15})(2\\sqrt3-\\sqrt5)=16\\sqrt3-8\\sqrt5-3\\sqrt5+5\\sqrt3=21\\sqrt3-14\\sqrt5$."},{"title":"Divide by 7","body":"$\\dfrac{21\\sqrt3-14\\sqrt5}{7}=3\\sqrt3-2\\sqrt5$."},{"title":"Rearrange the equation","body":"$(x+5\\sqrt3)\\sqrt5=40-2x\\sqrt3$ gives $x(\\sqrt5+2\\sqrt3)=40-5\\sqrt{15}$."},{"title":"Use the result from part (a)","body":"$x=\\dfrac{40-5\\sqrt{15}}{2\\sqrt3+\\sqrt5}=5\\left(3\\sqrt3-2\\sqrt5\\right)$."}]},{"id":"WMA11-01_2024_Jan_Q04","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":4,"marks":6,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q04_M06_05_Polynomials.png","downloadName":"WMA11-01_Y2024_Jan_Q04_M06_05_Polynomials.png","finalAnswer":"$x=3$ or $x=-2$.","steps":[{"title":"Substitute p equals 2 to the x","body":"If $p=2^x$, then $4^x=p^2$, $2^{x+3}=8p$, and $2^{x-1}=\\dfrac{p}{2}$."},{"title":"Rewrite the equation","body":"$2p^2-8p=17\\left(\\dfrac{p}{2}\\right)-4$."},{"title":"Clear the fraction","body":"Multiplying by 2 gives $4p^2-16p=17p-8$, so $4p^2-33p+8=0$."},{"title":"Solve the quadratic","body":"$4p^2-33p+8=(4p-1)(p-8)$, so $p=\\dfrac14$ or $p=8$."},{"title":"Return to x","body":"$2^x=\\dfrac14=2^{-2}$ gives $x=-2$, and $2^x=8=2^3$ gives $x=3$."}]},{"id":"WMA11-01_2024_MayJune_Q02","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":2,"marks":6,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q02_M06_01_Indices_Surds.png","downloadName":"WMA11-01_Y2024_MayJune_Q02_M06_01_Indices_Surds.png","finalAnswer":"$(i)(a)\\ 8m.\\quad (i)(b)\\ m^{12}.\\quad (ii)\\ x=3+2\\sqrt3$.","steps":[{"title":"Use m equals 2 to the n","body":"$2^{n+3}=2^n\\times2^3=8m$."},{"title":"Rewrite 16 as a power of 2","body":"$16^{3n}=(2^4)^{3n}=2^{12n}=(2^n)^{12}=m^{12}$."},{"title":"Collect the x terms","body":"$x\\sqrt3-3=x+\\sqrt3$ gives $x(\\sqrt3-1)=3+\\sqrt3$."},{"title":"Rationalise","body":"$x=\\dfrac{3+\\sqrt3}{\\sqrt3-1}\\times\\dfrac{\\sqrt3+1}{\\sqrt3+1}=\\dfrac{(3+\\sqrt3)(\\sqrt3+1)}{2}$."},{"title":"Simplify","body":"$x=\\dfrac{4\\sqrt3+6}{2}=3+2\\sqrt3$."}]},{"id":"WMA11-01_2024_Oct_Q02","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":2,"marks":7,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q02_M07_11_TrigFunctions.png","downloadName":"WMA11-01_Y2024_Oct_Q02_M07_11_TrigFunctions.png","finalAnswer":"$(i)\\ \\dfrac{6x^{10}}{y}.\\quad (ii)\\ a=-\\dfrac43\\sqrt3+\\dfrac83$.","steps":[{"title":"Simplify the power bracket","body":"$(2x^4)^3=8x^{12}$."},{"title":"Simplify the algebraic fraction","body":"$\\dfrac{3y^3(2x^4)^3}{4x^2y^4}=\\dfrac{3y^3(8x^{12})}{4x^2y^4}=\\dfrac{6x^{10}}{y}$."},{"title":"Rationalise the left side","body":"$\\dfrac{16}{\\sqrt3+1}\\times\\dfrac{\\sqrt3-1}{\\sqrt3-1}=8\\sqrt3-8$."},{"title":"Equate the surd parts","body":"$8\\sqrt3-8=a\\sqrt{27}+4=3a\\sqrt3+4$."},{"title":"Solve for a","body":"$3a\\sqrt3=8\\sqrt3-12$, so $a=\\dfrac{8\\sqrt3-12}{3\\sqrt3}=\\dfrac83-\\dfrac43\\sqrt3$."}]},{"id":"WMA11-01_2025_Jan_Q04","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":4,"marks":9,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q04_M09_01_Indices_Surds.png","downloadName":"WMA11-01_Y2025_Jan_Q04_M09_01_Indices_Surds.png","finalAnswer":"$(i)(a)\\ ay^3.\\quad (i)(b)\\ \\dfrac{45a^2}{y^2}.\\quad (ii)(b)\\ t=\\dfrac12$ or $t=-\\dfrac32$.","steps":[{"title":"Use y equals a to the x","body":"$a^{3x+1}=a(a^x)^3=ay^3$."},{"title":"Rewrite the denominator","body":"$\\dfrac{5}{(3a^{1-x})^{-2}}=5(3a^{1-x})^2=45a^{2-2x}$."},{"title":"Write in terms of y","body":"$45a^{2-2x}=\\dfrac{45a^2}{(a^x)^2}=\\dfrac{45a^2}{y^2}$."},{"title":"Use p equals 9 to the t","body":"$p=9^t=3^{2t}$, so $3^{4t+2}=9(3^{2t})^2=9p^2$."},{"title":"Rewrite the equation","body":"$3(3^{4t+2}+1)=82\\times9^t$ becomes $3(9p^2+1)=82p$."},{"title":"Obtain the quadratic","body":"$27p^2+3=82p$, so $27p^2-82p+3=0$."},{"title":"Solve for p","body":"$p=\\dfrac{82\\pm80}{54}$, so $p=3$ or $p=\\dfrac{1}{27}$."},{"title":"Return to t","body":"$9^t=3$ gives $3^{2t}=3^1$, so $t=\\dfrac12$. Also $9^t=\\dfrac1{27}=3^{-3}$ gives $2t=-3$, so $t=-\\dfrac32$."}]},{"id":"WMA11-01_2025_MayJune_Q01","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":1,"marks":5,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q01_M05_01_Indices_Surds.png","downloadName":"WMA11-01_Y2025_MayJune_Q01_M05_01_Indices_Surds.png","finalAnswer":"$(a)\\ \\dfrac14x^2.\\quad (b)\\ \\dfrac25x^{-1}.\\quad (c)\\ 100x^{-2}$.","steps":[{"title":"Simplify p","body":"$p=\\dfrac1{16}x^4$."},{"title":"Part (a)","body":"$p^{1/2}=\\left(\\dfrac1{16}x^4\\right)^{1/2}=\\dfrac14x^2$."},{"title":"Simplify pq","body":"$pq=\\dfrac1{16}x^4\\cdot\\dfrac{40}{x^3}=\\dfrac52x$."},{"title":"Part (b)","body":"$(pq)^{-1}=\\left(\\dfrac52x\\right)^{-1}=\\dfrac25x^{-1}$."},{"title":"Part (c)","body":"$pq^2=\\dfrac1{16}x^4\\left(\\dfrac{40}{x^3}\\right)^2=\\dfrac{1600}{16}x^{-2}=100x^{-2}$."}]},{"id":"WMA11-01_2025_Oct_Q04","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":4,"marks":7,"topic":"01_Indices_Surds","topicName":"Indices & Surds","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q04_M07_01_Indices_Surds.png","downloadName":"WMA11-01_Y2025_Oct_Q04_M07_01_Indices_Surds.png","finalAnswer":"$(i)\\ p=\\dfrac94.\\quad (ii)\\ x=\\pm2\\sqrt2$.","steps":[{"title":"Rewrite the right-hand side","body":"$\\dfrac19\\sqrt{27}=3^{-2}\\cdot3^{3/2}=3^{-1/2}$."},{"title":"Equate powers of 3","body":"$3^{2p-5}=3^{-1/2}$, so $2p-5=-\\dfrac12$."},{"title":"Solve for p","body":"$2p=\\dfrac92$, hence $p=\\dfrac94$."},{"title":"Clear the denominator","body":"$x^2+1=\\dfrac{36}{x^2-4}$ gives $(x^2+1)(x^2-4)=36$."},{"title":"Form a quadratic in x squared","body":"$x^4-3x^2-4=36$, so $x^4-3x^2-40=0$."},{"title":"Factor","body":"$(x^2-8)(x^2+5)=0$."},{"title":"Use real roots","body":"$x^2=8$, so $x=\\pm2\\sqrt2$. The equation $x^2=-5$ gives no real roots."}]},{"id":"WMA11-01_2019_Oct_Q08","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":8,"marks":5,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q08_M05_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2019_Oct_Q08_M05_06_GraphsOfFunctions.png","finalAnswer":"$x=14+6\\sqrt5$ or $x=14-6\\sqrt5$.","steps":[{"title":"Use a substitution","body":"Let $u=\\sqrt{x}$. Then $x=u^2$, so the equation becomes $u^2-6u+4=0$."},{"title":"Solve the quadratic","body":"$u=\\dfrac{6\\pm\\sqrt{36-16}}{2}=\\dfrac{6\\pm2\\sqrt5}{2}=3\\pm\\sqrt5$."},{"title":"Return to x","body":"Since $u=\\sqrt{x}$, $x=u^2=(3\\pm\\sqrt5)^2=9+5\\pm6\\sqrt5=14\\pm6\\sqrt5$."}]},{"id":"WMA11-01_2020_Jan_Q05","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":5,"marks":7,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q05_M07_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2020_Jan_Q05_M07_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ x=0,-\\dfrac12,3.\\quad (b)\\ y=-3,6$.","steps":[{"title":"Factorise the cubic","body":"$20x^3-50x^2-30x=10x(2x^2-5x-3)=10x(2x+1)(x-3)$."},{"title":"Solve part (a)","body":"$10x(2x+1)(x-3)=0$, so $x=0$, $x=-\\frac12$, or $x=3$."},{"title":"Use the same structure for part (b)","body":"Let $u=(y+3)^{1/2}$. Then the equation becomes $20u^3-50u^2-30u=0$, so $u=0$, $u=-\\frac12$, or $u=3$."},{"title":"Reject the invalid square-root value","body":"Since $u=\\sqrt{y+3}\\ge0$, reject $u=-\\frac12$. If $u=0$, then $y=-3$. If $u=3$, then $y+3=9$, so $y=6$."}]},{"id":"WMA11-01_2021_Jan_Q02","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":2,"marks":6,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q02_M06_02_Quadratics.png","downloadName":"WMA11-01_Y2021_Jan_Q02_M06_02_Quadratics.png","finalAnswer":"$(a)\\ p=0.364,\\ q=4.72.\\quad (b)\\ T=18.2$ years.","steps":[{"title":"Substitute the two given heights","body":"When $t=3$ and $H=2$, $2^3=9p+q$, so $8=9p+q$. When $t=5$ and $H=2.4$, $2.4^3=25p+q$, so $13.824=25p+q$."},{"title":"Solve for p and q","body":"Subtracting the two equations gives $16p=5.824$, so $p=0.364$. Then $8=9(0.364)+q$, giving $q=4.724$, so $q=4.72$ to 3 significant figures."},{"title":"Use H = 5","body":"For $H=5$, $125=0.364T^2+4.724$."},{"title":"Find T","body":"$T^2=\\dfrac{125-4.724}{0.364}=330.428\\ldots$, so $T=18.177\\ldots$. Therefore $T=18.2$ years to one decimal place."}]},{"id":"WMA11-01_2022_Jan_Q02","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":2,"marks":6,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q02_M06_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2022_Jan_Q02_M06_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ 13-2(x+1)^2.\\quad (b)\\ y\\text{-intercept }(0,11).\\quad (c)\\ x=-1$.","steps":[{"title":"Complete the square","body":"$f(x)=11-4x-2x^2=-2(x^2+2x)+11$."},{"title":"Write in vertex form","body":"$-2(x^2+2x)+11=-2\\big((x+1)^2-1\\big)+11=13-2(x+1)^2$."},{"title":"Identify the graph features","body":"The graph is a downward-opening parabola with maximum point $(-1,13)$. The y-intercept is $f(0)=11$, so it crosses the y-axis at $(0,11)$."},{"title":"State the line of symmetry","body":"From $13-2(x+1)^2$, the line of symmetry is $x=-1$."}]},{"id":"WMA11-01_2022_Jan_Q03","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":3,"marks":7,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q03_M07_02_Quadratics.png","downloadName":"WMA11-01_Y2022_Jan_Q03_M07_02_Quadratics.png","finalAnswer":"$(i)\\ f(x)=10x^2-58\\sqrt2x+202.\\quad (ii)\\ y=\\dfrac{57}{23}+\\dfrac{41}{23}\\sqrt3$.","steps":[{"title":"Expand the first square","body":"$(x+\\sqrt2)^2=x^2+2\\sqrt2x+2$."},{"title":"Expand the second square","body":"Since $\\sqrt8=2\\sqrt2$, $(3x-5\\sqrt8)^2=(3x-10\\sqrt2)^2=9x^2-60\\sqrt2x+200$."},{"title":"Collect terms","body":"$f(x)=x^2+2\\sqrt2x+2+9x^2-60\\sqrt2x+200=10x^2-58\\sqrt2x+202$."},{"title":"Expand the surd equation","body":"$\\sqrt3(4y-3\\sqrt3)=5y+\\sqrt3$ gives $4\\sqrt3y-9=5y+\\sqrt3$."},{"title":"Solve for y","body":"$y(4\\sqrt3-5)=9+\\sqrt3$, so $y=\\dfrac{9+\\sqrt3}{4\\sqrt3-5}$."},{"title":"Rationalise the denominator","body":"$y=\\dfrac{(9+\\sqrt3)(4\\sqrt3+5)}{(4\\sqrt3)^2-5^2}=\\dfrac{57+41\\sqrt3}{23}=\\dfrac{57}{23}+\\dfrac{41}{23}\\sqrt3$."}]},{"id":"WMA11-01_2022_MayJune_Q06","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":6,"marks":7,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q06_M07_01_Indices_Surds.png","downloadName":"WMA11-01_Y2022_MayJune_Q06_M07_01_Indices_Surds.png","finalAnswer":"$(x,y)=(\\sqrt{10},4\\sqrt{10})$ or $(-\\sqrt{10},-4\\sqrt{10})$.","steps":[{"title":"Rearrange the second equation","body":"From $y-x^3+6x=0$, we get $y=x^3-6x$."},{"title":"Substitute into the first equation","body":"$2x(x^3-6x)-3x^2=50$, so $2x^4-15x^2-50=0$."},{"title":"Solve the quadratic in x squared","body":"Let $u=x^2$. Then $2u^2-15u-50=0$, giving $u=10$ or $u=-\\dfrac52$."},{"title":"Reject the negative value","body":"Since $x^2$ cannot be negative, $x^2=10$, so $x=\\pm\\sqrt{10}$."},{"title":"Find y","body":"$y=x^3-6x=x(x^2-6)=x(10-6)=4x$. Therefore $y=4\\sqrt{10}$ when $x=\\sqrt{10}$ and $y=-4\\sqrt{10}$ when $x=-\\sqrt{10}$."}]},{"id":"WMA11-01_2023_Jan_Q04","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":4,"marks":4,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q04_M04_02_Quadratics.png","downloadName":"WMA11-01_Y2023_Jan_Q04_M04_02_Quadratics.png","finalAnswer":"$0<k<\\dfrac59$.","steps":[{"title":"Use the discriminant condition","body":"For no real roots, the discriminant must be negative: $b^2-4ac<0$."},{"title":"Substitute a, b, and c","body":"For $kx^2+6kx+5=0$, $a=k$, $b=6k$, and $c=5$."},{"title":"Form the inequality","body":"$(6k)^2-4(k)(5)<0$, so $36k^2-20k<0$."},{"title":"Solve the inequality","body":"$4k(9k-5)<0$, so the product is negative when $0<k<\\dfrac59$."}]},{"id":"WMA11-01_2023_Jan_Q08","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":8,"marks":8,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q08_M08_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2023_Jan_Q08_M08_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ y=3x-12.\\quad (b)\\ k=10.\\quad (c)\\ f(x)=2(x-4)(x-10).\\quad (d)\\ 0\\le x\\le4,\\ 3x-12\\le y\\le2x^2-28x+80$.","steps":[{"title":"Find the straight line","body":"The line cuts the y-axis at $-12$ and the x-axis at $4$, so its gradient is $\\dfrac{0-(-12)}{4-0}=3$. Hence $l$ is $y=3x-12$."},{"title":"Use symmetry of the quadratic","body":"The minimum point has x-coordinate 7. The roots are $4$ and $k$, so their midpoint is 7."},{"title":"Find k","body":"$\\dfrac{4+k}{2}=7$, so $k=10$."},{"title":"Build the quadratic","body":"Let $f(x)=a(x-4)(x-10)$. Since the minimum point is $(7,-18)$, $-18=a(3)(-3)=-9a$, so $a=2$."},{"title":"Write f(x)","body":"$f(x)=2(x-4)(x-10)=2x^2-28x+80$."},{"title":"Identify the shaded region","body":"The region lies between the y-axis and $x=4$, above the line and below the curve: $0\\le x\\le4$ and $3x-12\\le y\\le2x^2-28x+80$."}]},{"id":"WMA11-01_2023_MayJune_Q02","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":2,"marks":6,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q02_M06_02_Quadratics.png","downloadName":"WMA11-01_Y2023_MayJune_Q02_M06_02_Quadratics.png","finalAnswer":"$x=105,\\ y=70$.","steps":[{"title":"Use the perimeter","body":"$2x+2y=350$, so $x+y=175$."},{"title":"Use the area","body":"$xy=7350$."},{"title":"Form a quadratic","body":"Using $y=175-x$, $x(175-x)=7350$, so $x^2-175x+7350=0$."},{"title":"Solve","body":"$x=\\dfrac{175\\pm\\sqrt{175^2-4(7350)}}{2}=\\dfrac{175\\pm35}{2}$, giving $x=105$ or $70$."},{"title":"Use x > y","body":"Since $x>y$, $x=105$ and $y=70$."}]},{"id":"WMA11-01_2023_MayJune_Q03","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":3,"marks":6,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q03_M06_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2023_MayJune_Q03_M06_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ 3(x+2)^2+1.\\quad (b)$ y-intercept $(0,13)$ and turning point $(-2,1)$.","steps":[{"title":"Complete the square","body":"$3x^2+12x+13=3(x^2+4x)+13$."},{"title":"Use (x + 2)^2","body":"$x^2+4x=(x+2)^2-4$, so $3(x^2+4x)+13=3(x+2)^2-12+13$."},{"title":"Read the features","body":"$y=3(x+2)^2+1$ has turning point $(-2,1)$. The y-intercept is found from $x=0$, giving $y=13$."},{"title":"Sketch description","body":"The curve is an upward-opening parabola with minimum $(-2,1)$ and y-intercept $(0,13)$."}]},{"id":"WMA11-01_2023_Oct_Q06","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":6,"marks":6,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q06_M06_02_Quadratics.png","downloadName":"WMA11-01_Y2023_Oct_Q06_M06_02_Quadratics.png","finalAnswer":"$p<-\\dfrac23$ or $p>4$.","steps":[{"title":"Clear the denominator","body":"$4(p-2x)=\\dfrac{12+15p}{x+p}$ gives $4(p-2x)(x+p)=12+15p$."},{"title":"Form a quadratic in x","body":"Expanding gives $4p^2-4px-8x^2=12+15p$, so $8x^2+4px+12+15p-4p^2=0$."},{"title":"Use the discriminant condition","body":"For two distinct real roots, $b^2-4ac>0$."},{"title":"Simplify the inequality","body":"$(4p)^2-4(8)(12+15p-4p^2)>0$, so $144p^2-480p-384>0$."},{"title":"Divide and factorise","body":"Dividing by 48 gives $3p^2-10p-8>0$, and $3p^2-10p-8=(3p+2)(p-4)$."},{"title":"State the range","body":"The upward-opening quadratic is positive outside its roots, so $p<-\\dfrac23$ or $p>4$."}]},{"id":"WMA11-01_2023_Oct_Q11","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":11,"marks":10,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q11_M10_07_Transformations.png","downloadName":"WMA11-01_Y2023_Oct_Q11_M10_07_Transformations.png","finalAnswer":"$(a)\\ 2(x-3)^2-4.\\quad (b)\\ P=(3,-4).\\quad (c)\\ y=-8x+20.\\quad (d)\\ x\\ge0,\\ y\\ge0,\\ y\\le-8x+20,\\ y\\ge2x^2-12x+14$.","steps":[{"title":"Complete the square","body":"$2x^2-12x+14=2(x^2-6x)+14=2\\left((x-3)^2-9\\right)+14=2(x-3)^2-4$."},{"title":"State the minimum point","body":"The minimum of $2(x-3)^2-4$ is at $P=(3,-4)$."},{"title":"Find the gradient of l","body":"The line passes through $(-1,28)$ and $P(3,-4)$, so $m=\\dfrac{-4-28}{3-(-1)}=\\dfrac{-32}{4}=-8$."},{"title":"Find the equation of l","body":"Using $P(3,-4)$, $y+4=-8(x-3)$, so $y=-8x+20$."},{"title":"Use the axes as boundaries","body":"The region is to the right of the y-axis and above the x-axis, so $x\\ge0$ and $y\\ge0$."},{"title":"Use the line and curve as boundaries","body":"The region is below the line and above the curve, so $y\\le-8x+20$ and $y\\ge2x^2-12x+14$."}]},{"id":"WMA11-01_2024_Jan_Q09","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":9,"marks":10,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q09_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2024_Jan_Q09_M10_06_GraphsOfFunctions.png","finalAnswer":"$(a)$ downward parabola through $(0,0)$ and $(4,0)$ with maximum $(2,20)$. $(b)\\ f(x)=-5x(x-4)$. $(c)\\ P=(-8,-480)$.","steps":[{"title":"Use symmetry for the sketch","body":"The maximum is at $(2,20)$ and the curve passes through $(0,0)$. Since the axis of symmetry is $x=2$, the other x-intercept is $(4,0)$."},{"title":"Use completed-square form","body":"Let $f(x)=a(x-2)^2+20$."},{"title":"Use the origin","body":"$0=a(0-2)^2+20$, so $4a=-20$ and $a=-5$."},{"title":"Write f(x)","body":"$f(x)=-5(x-2)^2+20=-5x^2+20x=-5x(x-4)$."},{"title":"Equate the two curves","body":"$-5x^2+20x=x(x^2-4)=x^3-4x$."},{"title":"Factorise","body":"$x^3+5x^2-24x=0$, so $x(x^2+5x-24)=0$ and $x(x+8)(x-3)=0$."},{"title":"Use the negative x-coordinate","body":"The negative x-coordinate is $x=-8$."},{"title":"Find y","body":"$y=x(x^2-4)=(-8)(64-4)=-480$, so $P=(-8,-480)$."}]},{"id":"WMA11-01_2024_MayJune_Q04","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":4,"marks":6,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q04_M06_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2024_MayJune_Q04_M06_06_GraphsOfFunctions.png","finalAnswer":"$P=(1,-21)$.","steps":[{"title":"Equate the curves","body":"$x^2+kx-9=-3x^2-5x+k$ gives $4x^2+(k+5)x-(k+9)=0$."},{"title":"Use one intersection only","body":"For a single point of intersection, the discriminant is zero."},{"title":"Form the condition on k","body":"$(k+5)^2-4(4)(-(k+9))=0$, so $k^2+26k+169=0$."},{"title":"Find k","body":"$k^2+26k+169=(k+13)^2$, so $k=-13$."},{"title":"Find x","body":"Substituting $k=-13$ gives $4x^2-8x+4=0$, so $4(x-1)^2=0$ and $x=1$."},{"title":"Find y","body":"$y=x^2+kx-9=1-13-9=-21$, so $P=(1,-21)$."}]},{"id":"WMA11-01_2025_MayJune_Q10","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":10,"marks":7,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q10_M07_02_Quadratics.png","downloadName":"WMA11-01_Y2025_MayJune_Q10_M07_02_Quadratics.png","finalAnswer":"$(a)\\ x=-1,\\ -\\sqrt[3]{\\dfrac17}.\\quad (b)\\ k<0\\text{ or }k>5$.","steps":[{"title":"Substitute k equals 4.5","body":"The equation becomes $3.5x^6+4x^3+0.5=0$."},{"title":"Clear decimals","body":"Multiplying by $2$ gives $7x^6+8x^3+1=0$."},{"title":"Use a quadratic in x cubed","body":"$7x^6+8x^3+1=(x^3+1)(7x^3+1)=0$."},{"title":"Solve for x","body":"$x^3=-1$ or $x^3=-\\dfrac17$, so $x=-1$ or $x=-\\sqrt[3]{\\dfrac17}$."},{"title":"View the equation as a quadratic","body":"Let $u=x^3$. Then the equation is $(k-1)u^2+4u+(k-4)=0$."},{"title":"Use no real roots","body":"Since every real value of $u$ gives a real $x$, the original equation has no real roots exactly when this quadratic in $u$ has no real roots."},{"title":"Use the discriminant","body":"Require $b^2-4ac<0$: $16-4(k-1)(k-4)<0$."},{"title":"Simplify","body":"$16-4(k^2-5k+4)<0$ gives $20k-4k^2<0$, so $4k(5-k)<0$."},{"title":"Solve the inequality","body":"$4k(5-k)<0$ for $k<0$ or $k>5$."}]},{"id":"WMA11-01_2025_Oct_Q05","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":5,"marks":10,"topic":"02_Quadratics","topicName":"Quadratics","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q05_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2025_Oct_Q05_M10_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ 2(x-4)^2+18.\\quad (b)\\ x_P=\\dfrac{25}{4}.\\quad (c)\\ \\dfrac92x\\le y\\le2x^2-16x+50,\\ 0\\le x\\le4$.","steps":[{"title":"Complete the square","body":"$2x^2-16x+50=2(x^2-8x)+50=2[(x-4)^2-16]+50$."},{"title":"Simplify the completed square","body":"$2x^2-16x+50=2(x-4)^2+18$."},{"title":"Find M","body":"The minimum point is $M=(4,18)$."},{"title":"Find the line through O and M","body":"Since $l$ passes through $(0,0)$ and $(4,18)$, its gradient is $\\dfrac{18}{4}=\\dfrac92$, so $l:y=\\dfrac92x$."},{"title":"Find the second intersection","body":"Set $2x^2-16x+50=\\dfrac92x$."},{"title":"Form the quadratic","body":"Multiplying by $2$ gives $4x^2-32x+100=9x$, so $4x^2-41x+100=0$."},{"title":"Factor and select P","body":"$4x^2-41x+100=(x-4)(4x-25)=0$. The point $M$ has $x=4$, so $P$ has $x=\\dfrac{25}{4}$."},{"title":"Define the region","body":"The shaded region is above the line, below the curve, and between the y-axis and $M$."},{"title":"Write inequalities","body":"$\\dfrac92x\\le y\\le2x^2-16x+50$ with $0\\le x\\le4$."}]},{"id":"WMA11-01_2023_Oct_Q08","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":8,"marks":7,"topic":"03_Simultaneous","topicName":"Simultaneous Equations","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q08_M07_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2023_Oct_Q08_M07_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ 2x^4-7x^2-15=0.\\quad (b)\\ PQ=\\sqrt{65}$.","steps":[{"title":"Write C1 in terms of y","body":"$xy=\\dfrac{15}{2}-5x$, so $y=\\dfrac{15}{2x}-5$."},{"title":"Equate the two curves","body":"$\\dfrac{15}{2x}-5=x^3-\\dfrac72x-5$."},{"title":"Multiply by 2x","body":"$15=2x^4-7x^2$, hence $2x^4-7x^2-15=0$."},{"title":"Solve for x","body":"Let $u=x^2$. Then $2u^2-7u-15=0=(2u+3)(u-5)$, so $x^2=5$ and $x=\\pm\\sqrt5$."},{"title":"Find the y-coordinates","body":"Using $y=\\dfrac{15}{2x}-5$, the points are $\\left(\\sqrt5,\\dfrac{3\\sqrt5}{2}-5\\right)$ and $\\left(-\\sqrt5,-\\dfrac{3\\sqrt5}{2}-5\\right)$."},{"title":"Use the distance formula","body":"$\\Delta x=2\\sqrt5$ and $\\Delta y=3\\sqrt5$, so $PQ=\\sqrt{(2\\sqrt5)^2+(3\\sqrt5)^2}=\\sqrt{65}$."}]},{"id":"WMA11-01_2025_Jan_Q03","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":3,"marks":5,"topic":"03_Simultaneous","topicName":"Simultaneous Equations","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q03_M05_01_Indices_Surds.png","downloadName":"WMA11-01_Y2025_Jan_Q03_M05_01_Indices_Surds.png","finalAnswer":"$(a)\\ a=3241,\\ b=\\dfrac{123}{125}.\\quad (b)\\ T=15.9$ years.","steps":[{"title":"Use t equals 5","body":"The population is $58$ thousand, so $58^2=a+b(5^3)$, giving $3364=a+125b$."},{"title":"Use t equals 10","body":"The population is $65$ thousand, so $65^2=a+b(10^3)$, giving $4225=a+1000b$."},{"title":"Solve for b","body":"Subtracting gives $861=875b$, so $b=\\dfrac{861}{875}=\\dfrac{123}{125}$."},{"title":"Solve for a","body":"$a=3364-125\\left(\\dfrac{123}{125}\\right)=3241$."},{"title":"Use population 85 thousand","body":"$85^2=3241+\\dfrac{123}{125}T^3$."},{"title":"Find T","body":"$T^3=\\dfrac{125(7225-3241)}{123}$, so $T\\approx15.938$ and $T=15.9$ to one decimal place."}]},{"id":"WMA11-01_2026_Jan_Q02","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":2,"marks":6,"topic":"03_Simultaneous","topicName":"Simultaneous Equations","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q02_M06_03_Simultaneous.png","downloadName":"WMA11-01_Y2026_Jan_Q02_M06_03_Simultaneous.png","finalAnswer":"$(x,y)=(2+2\\sqrt3,\\ 6+2\\sqrt3)$ or $(2-2\\sqrt3,\\ 6-2\\sqrt3)$.","steps":[{"title":"Use the linear equation","body":"$y-x=4$, so $y=x+4$."},{"title":"Substitute into the second equation","body":"$2x^2-xy=8$ becomes $2x^2-x(x+4)=8$."},{"title":"Show the quadratic","body":"$2x^2-x^2-4x=8$, so $x^2-4x-8=0$."},{"title":"Complete the square","body":"$x^2-4x-8=0$ gives $(x-2)^2=12$."},{"title":"Find x","body":"$x=2\\pm\\sqrt{12}=2\\pm2\\sqrt3$."},{"title":"Find y","body":"Since $y=x+4$, $y=6\\pm2\\sqrt3$ with matching signs."},{"title":"State both solutions","body":"$(x,y)=(2+2\\sqrt3,6+2\\sqrt3)$ or $(2-2\\sqrt3,6-2\\sqrt3)$."}]},{"id":"WMA11-01_2020_Jan_Q08","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":8,"marks":6,"topic":"04_Inequalities","topicName":"Inequalities","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q08_M06_04_Inequalities.png","downloadName":"WMA11-01_Y2020_Jan_Q08_M06_04_Inequalities.png","finalAnswer":"$-2<k<5$.","steps":[{"title":"Equate the line and curve","body":"$k(2x-1)=x^2+2x+11$, so $x^2+(2-2k)x+(11+k)=0$."},{"title":"Use the no-intersection condition","body":"For the line not to cross or touch the curve, the quadratic in $x$ must have no real roots, so its discriminant is less than zero."},{"title":"Form the inequality in k","body":"$(2-2k)^2-4(1)(11+k)<0$. Dividing by $4$ gives $(1-k)^2-(11+k)<0$, so $k^2-3k-10<0$."},{"title":"Solve the quadratic inequality","body":"$(k-5)(k+2)<0$, so $k$ lies between the two roots: $-2<k<5$."}]},{"id":"WMA11-01_2023_MayJune_Q01","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":1,"marks":4,"topic":"04_Inequalities","topicName":"Inequalities","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q01_M04_04_Inequalities.png","downloadName":"WMA11-01_Y2023_MayJune_Q01_M04_04_Inequalities.png","finalAnswer":"$x\\le-\\dfrac14$ or $x\\ge2$.","steps":[{"title":"Move all terms to one side","body":"$4x^2-3x+7\\ge4x+9$ gives $4x^2-7x-2\\ge0$."},{"title":"Factorise","body":"$4x^2-7x-2=(4x+1)(x-2)$."},{"title":"Use the sign of the quadratic","body":"The roots are $x=-\\dfrac14$ and $x=2$. Since the quadratic opens upwards, it is non-negative outside the roots."}]},{"id":"WMA11-01_2023_MayJune_Q07","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":7,"marks":6,"topic":"04_Inequalities","topicName":"Inequalities","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q07_M06_04_Inequalities.png","downloadName":"WMA11-01_Y2023_MayJune_Q07_M06_04_Inequalities.png","finalAnswer":"$(a)\\ a=\\dfrac94,\\ k=\\dfrac89.\\quad (b)\\ x\\ge\\dfrac94,\\ y\\ge\\dfrac89x,\\ y\\le10-2x$.","steps":[{"title":"Find the area of R1","body":"The bottom horizontal length is 5, from $x=0$ to the intercept of $y=10-2x$ at $x=5$."},{"title":"Use the top length","body":"The top horizontal length is $4-a$, because $y=2$ meets $y=10-2x$ at $x=4$."},{"title":"Solve for a","body":"Area $R_1=\\dfrac12(5+4-a)(2)=9-a=\\dfrac{27}{4}$, so $a=\\dfrac94$."},{"title":"Find k","body":"The line $x=a$ passes through the intersection of $y=2$ and $y=kx$, so $2=ka$. Hence $k=\\dfrac{2}{9/4}=\\dfrac89$."},{"title":"Define R2","body":"Region $R_2$ is to the right of $x=a$, above $y=kx$, and below $y=10-2x$."}]},{"id":"WMA11-01_2024_MayJune_Q06","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":6,"marks":7,"topic":"04_Inequalities","topicName":"Inequalities","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q06_M07_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2024_MayJune_Q06_M07_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ P=(-6,45),\\ Q=(8,115).\\quad (b)\\ y\\ge0,\\ y\\le5x+75,\\ y\\le2x^2+x-21,\\ x\\le0$.","steps":[{"title":"Write the line as y equals","body":"$y-5x=75$, so $y=5x+75$."},{"title":"Equate line and curve","body":"$5x+75=2x^2+x-21$, so $2x^2-4x-96=0$."},{"title":"Solve the quadratic","body":"$x^2-2x-48=0=(x-8)(x+6)$, so $x=-6$ or $x=8$."},{"title":"Find the y-coordinates","body":"Using $y=5x+75$, $x=-6$ gives $y=45$ and $x=8$ gives $y=115$."},{"title":"State P and Q","body":"From the diagram, $P=(-6,45)$ and $Q=(8,115)$."},{"title":"Use the x-axis and left branch","body":"The shaded region is above the x-axis and on the left part of the diagram, so $y\\ge0$ and $x\\le0$."},{"title":"Use the line and curve as upper boundaries","body":"The region is below both the line and the curve, so $y\\le5x+75$ and $y\\le2x^2+x-21$."}]},{"id":"WMA11-01_2026_Jan_Q03","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":3,"marks":5,"topic":"04_Inequalities","topicName":"Inequalities","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q03_M05_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2026_Jan_Q03_M05_06_GraphsOfFunctions.png","finalAnswer":"$(i)\\ z<0\\text{ or }z>\\dfrac12.\\quad (ii)$ shade the region above $y=x+5$, below $y=x(x-3)$, with $x\\ge-2$.","steps":[{"title":"Solve the rational inequality","body":"$\\dfrac4z<8$ gives $\\dfrac4z-8<0$, so $\\dfrac{4-8z}{z}<0$."},{"title":"Use critical values","body":"The critical values are $z=0$ and $z=\\dfrac12$."},{"title":"State the range","body":"A sign check gives $z<0$ or $z>\\dfrac12$."},{"title":"Find where line and curve meet","body":"$x+5=x(x-3)$ gives $x^2-4x-5=0$, so $(x-5)(x+1)=0$."},{"title":"Combine with x greater than or equal to -2","body":"The inequality $x+5\\le y\\le x(x-3)$ is possible when $x\\le-1$ or $x\\ge5$. With $x\\ge-2$, the shaded x-ranges are $-2\\le x\\le-1$ and $x\\ge5$."},{"title":"Graphical representation","body":"Draw the vertical boundary $x=-2$ and shade the two regions between the line and the parabola: from $x=-2$ to $x=-1$, and to the right of $x=5$."}]},{"id":"WMA11-01_2021_MayJune_Q02","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":2,"marks":10,"topic":"05_Polynomials","topicName":"Polynomials","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q02_M10_05_Polynomials.png","downloadName":"WMA11-01_Y2021_MayJune_Q02_M10_05_Polynomials.png","finalAnswer":"$(a)(i)\\ a=3.\\quad (a)(ii)\\ x=-9,0,\\dfrac13.\\quad (b)(i)\\ y=-729,0,\\dfrac1{27}.\\quad (b)(ii)\\ z=-\\dfrac12$.","steps":[{"title":"Use f(-1) = 32","body":"$f(-1)=-a+(6a+8)+a^2=a^2+5a+8$. Since $f(-1)=32$, $a^2+5a-24=0$."},{"title":"Choose the positive value of a","body":"$a^2+5a-24=(a-3)(a+8)=0$. Since $a$ is positive, the only possible value is $a=3$."},{"title":"Solve f(x) = 0","body":"Using $a=3$, $f(x)=3x^3+26x^2-9x=x(3x^2+26x-9)=x(3x-1)(x+9)$."},{"title":"List the roots","body":"$x=0$, $x=\\dfrac13$, or $x=-9$."},{"title":"Solve the equation in y","body":"Let $u=y^{1/3}$. Then $y=u^3$ and $y^{2/3}=u^2$, so $3y+26y^{2/3}-9y^{1/3}=0$ becomes $3u^3+26u^2-9u=0$."},{"title":"Convert back to y","body":"From part (a), $u=-9,0,\\dfrac13$. Therefore $y=u^3$, giving $y=-729,0,\\dfrac1{27}$."},{"title":"Solve the exponential equation","body":"Let $u=9^z$. Then $3(9^{3z})+26(9^{2z})-9(9^z)=0$ becomes $3u^3+26u^2-9u=0$."},{"title":"Use positivity of 9^z","body":"Since $9^z>0$, the only valid root is $u=\\dfrac13$. Hence $9^z=\\dfrac13$, so $(3^2)^z=3^{-1}$ and $2z=-1$. Therefore $z=-\\dfrac12$."}]},{"id":"WMA11-01_2021_MayJune_Q08","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":8,"marks":9,"topic":"05_Polynomials","topicName":"Polynomials","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q08_M09_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2021_MayJune_Q08_M09_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ 3(x+1)^2+6.\\quad (b)\\ P=(-1,6).\\quad (c)\\ A=-\\dfrac12,\\ B=-\\dfrac32,\\ C=5,\\ D=12$.","steps":[{"title":"Complete the square","body":"$3x^2+6x+9=3(x^2+2x)+9=3\\big((x+1)^2-1\\big)+9=3(x+1)^2+6$."},{"title":"Deduce the minimum point","body":"The minimum occurs when $(x+1)^2=0$, so $x=-1$ and $y=6$. Therefore $P=(-1,6)$."},{"title":"Use the x-intercepts of C2","body":"Since $C_2$ intersects the x-axis at $-4,-2$ and $3$, it has form $y=k(x+4)(x+2)(x-3)$."},{"title":"Use point P to find k","body":"Substitute $P=(-1,6)$: $6=k(3)(1)(-4)=-12k$, so $k=-\\dfrac12$."},{"title":"Expand the cubic","body":"$(x+4)(x+2)(x-3)=(x^2+6x+8)(x-3)=x^3+3x^2-10x-24$."},{"title":"Read off A, B, C and D","body":"Thus $y=-\\dfrac12x^3-\\dfrac32x^2+5x+12$, so $A=-\\dfrac12$, $B=-\\dfrac32$, $C=5$ and $D=12$."}]},{"id":"WMA11-01_2024_Oct_Q04","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":4,"marks":10,"topic":"05_Polynomials","topicName":"Polynomials","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q04_M10_07_Transformations.png","downloadName":"WMA11-01_Y2024_Oct_Q04_M10_07_Transformations.png","finalAnswer":"$(a)\\ f(x)=\\dfrac65x(x-4).\\quad (b)\\ g(x)=\\dfrac3{10}x(x-4)^2.\\quad (c)\\ P=(8,\\dfrac{192}{5})$.","steps":[{"title":"Use the roots of C1","body":"Since $C_1$ cuts the x-axis at $0$ and $4$, let $f(x)=ax(x-4)$."},{"title":"Use the minimum point of C1","body":"At $x=2$, $f(2)=-4a=-4.8=-\\dfrac{24}{5}$, so $a=\\dfrac65$."},{"title":"Write f(x)","body":"$f(x)=\\dfrac65x(x-4)$."},{"title":"Use the roots of C2","body":"The cubic cuts the x-axis at the origin and meets the x-axis at $x=4$, so $x=4$ is a repeated root. Let $g(x)=bx(x-4)^2$."},{"title":"Use the point (6, 7.2)","body":"$7.2=b(6)(2^2)=24b$, so $b=0.3=\\dfrac3{10}$."},{"title":"Equate the curves","body":"$\\dfrac65x(x-4)=\\dfrac3{10}x(x-4)^2$."},{"title":"Find the first-quadrant intersection","body":"Ignoring the shared roots on the x-axis, divide by $x(x-4)$ to get $\\dfrac65=\\dfrac3{10}(x-4)$. Hence $x=8$."},{"title":"Find y","body":"$y=f(8)=\\dfrac65(8)(4)=\\dfrac{192}{5}$."}]},{"id":"WMA11-01_2026_Jan_Q06","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":6,"marks":9,"topic":"05_Polynomials","topicName":"Polynomials","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q06_M09_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2026_Jan_Q06_M09_06_GraphsOfFunctions.png","finalAnswer":"$(a)(i)\\ -6,15.\\quad (a)(ii)\\ 1,8.\\quad (b)\\ f(x)=\\dfrac15(x+2)(x-5)^2.\\quad (c)\\ x=-2,\\ 5\\pm5\\sqrt2$.","steps":[{"title":"Roots of f one third x","body":"The roots of $f(x)=0$ are $x=-2$ and $x=5$, with $x=5$ repeated. For $f\\left(\\dfrac13x\\right)=0$, set $\\dfrac13x=-2$ or $5$, giving $x=-6$ or $15$."},{"title":"Roots of f of x minus 3","body":"For $f(x-3)=0$, set $x-3=-2$ or $5$, giving $x=1$ or $8$."},{"title":"Use the roots and repeated root","body":"Since the curve cuts at $(-2,0)$ and touches at $(5,0)$, write $f(x)=k(x+2)(x-5)^2$."},{"title":"Use the y-intercept","body":"The curve passes through $(0,10)$, so $10=k(2)(25)=50k$."},{"title":"State f(x)","body":"$k=\\dfrac15$, hence $f(x)=\\dfrac15(x+2)(x-5)^2$."},{"title":"Set equal to the line","body":"$\\dfrac15(x+2)(x-5)^2=10(x+2)$."},{"title":"First solution","body":"The factor $x+2$ gives one solution $x=-2$."},{"title":"Find the other solutions","body":"For $x\\ne-2$, divide by $x+2$: $\\dfrac15(x-5)^2=10$, so $(x-5)^2=50$."},{"title":"State all intersections","body":"$x=5\\pm\\sqrt{50}=5\\pm5\\sqrt2$. Therefore the three x-coordinates are $-2$, $5-5\\sqrt2$ and $5+5\\sqrt2$."}]},{"id":"WMA11-01_2019_Oct_Q03","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":3,"marks":10,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q03_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2019_Oct_Q03_M10_06_GraphsOfFunctions.png","finalAnswer":"$M=\\left(\\frac52,\\frac{27}{4}\\right)$, $N=\\left(\\frac{26}{5},\\frac{351}{25}\\right)$, and $0\\le x\\le\\frac52$, $\\frac{27}{10}x\\le y\\le x^2-5x+13$.","steps":[{"title":"Complete the square to locate the minimum","body":"$y=x^2-5x+13=\\left(x-\\frac52\\right)^2+\\frac{27}{4}$. Therefore $M=\\left(\\frac52,\\frac{27}{4}\\right)$."},{"title":"Find the equation of the line through O and M","body":"The gradient of $OM$ is $\\dfrac{27/4}{5/2}=\\dfrac{27}{10}$, so $l$ has equation $y=\\frac{27}{10}x$."},{"title":"Find the second intersection","body":"Solve $x^2-5x+13=\\frac{27}{10}x$. This gives $x^2-\\frac{77}{10}x+13=0$. One root is $x=\\frac52$, so the other is $x=\\frac{26}{5}$. Then $y=\\frac{27}{10}\\cdot\\frac{26}{5}=\\frac{351}{25}$."},{"title":"Describe the shaded region","body":"The region is between the y-axis, the line, and the curve up to $M$: $0\\le x\\le\\frac52$ and $\\frac{27}{10}x\\le y\\le x^2-5x+13$."}]},{"id":"WMA11-01_2019_Oct_Q06","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":6,"marks":8,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q06_M08_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2019_Oct_Q06_M08_06_GraphsOfFunctions.png","finalAnswer":"Asymptote $y=k$, x-intercept $\\left(-\\frac4k,0\\right)$, and $k=10\\pm4\\sqrt2$.","steps":[{"title":"Read the graph features","body":"For $y=\\frac4x+k$, the horizontal asymptote is $y=k$. Setting $y=0$ gives $0=\\frac4x+k$, so the x-intercept is $x=-\\frac4k$."},{"title":"Set the tangent line equal to the curve","body":"A tangent touches once, so solve $10-2x=\\frac4x+k$. Multiplying by $x$ gives $2x^2+(k-10)x+4=0$."},{"title":"Use the discriminant condition","body":"For one repeated intersection, discriminant $=0$: $(k-10)^2-4(2)(4)=0$. Hence $(k-10)^2=32$."},{"title":"Find k","body":"$k-10=\\pm4\\sqrt2$, so $k=10\\pm4\\sqrt2$. Both are positive, so both satisfy the condition in the question."}]},{"id":"WMA11-01_2019_Oct_Q10","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":10,"marks":10,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q10_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2019_Oct_Q10_M10_06_GraphsOfFunctions.png","finalAnswer":"$f(x)\\le0$ for $x\\le-\\frac52$ or $x=3$; $f(x)=2x^3-7x^2-12x+45$; $P=(0,45)$; gradient $=-12$; $g(x)=(2x+1)(x-5)^2$; y-intercept $25$.","steps":[{"title":"Use the factorised form for the inequality","body":"$f(x)=(2x+5)(x-3)^2$. Since $(x-3)^2\\ge0$, the sign is controlled by $2x+5$, with an extra zero at $x=3$. Hence $f(x)\\le0$ for $x\\le-\\frac52$ or $x=3$."},{"title":"Expand the cubic","body":"$(x-3)^2=x^2-6x+9$, so $f(x)=(2x+5)(x^2-6x+9)=2x^3-7x^2-12x+45$."},{"title":"Find P and the gradient at P","body":"At the y-axis, $x=0$, so $P=(0,45)$. Also $f'(x)=6x^2-14x-12$, so the gradient at $P$ is $f'(0)=-12$."},{"title":"Translate the graph","body":"A translation 2 units in the positive x direction means $g(x)=f(x-2)$. Therefore $g(x)=(2(x-2)+5)((x-2)-3)^2=(2x+1)(x-5)^2$."},{"title":"Find the new y-intercept","body":"Set $x=0$: $g(0)=(1)(25)=25$, so the y-intercept is $25$."}]},{"id":"WMA11-01_2020_Jan_Q10","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":10,"marks":8,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q10_M08_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2020_Jan_Q10_M08_06_GraphsOfFunctions.png","finalAnswer":"Sketch: crosses at $\\left(\\frac34,0\\right)$, touches at $(5,0)$, crosses y-axis at $(0,-75)$. Also $x=3,20$, $p=75$, $g(x)=(4x+1)(x-4)^2$, y-intercept $16$.","steps":[{"title":"Use the factorised form for the sketch","body":"$f(x)=(4x-3)(x-5)^2$. The curve crosses the x-axis at $x=\\frac34$ and touches the x-axis at $x=5$. The y-intercept is $f(0)=(-3)(25)=-75$."},{"title":"Solve f(x/4)=0","body":"For $f\\left(\\frac14x\\right)=0$, either $4\\left(\\frac{x}{4}\\right)-3=0$ or $\\frac{x}{4}-5=0$. Therefore $x=3$ or $x=20$."},{"title":"Find p","body":"The curve $y=f(x)+p$ passes through the origin, so $0=f(0)+p=-75+p$. Hence $p=75$."},{"title":"Find g(x)","body":"$g(x)=f(x+1)=(4(x+1)-3)((x+1)-5)^2=(4x+1)(x-4)^2$."},{"title":"Find the y-intercept of C2","body":"At $x=0$, $g(0)=(1)(16)=16$. So the y-intercept is $16$."}]},{"id":"WMA11-01_2021_Jan_Q06","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":6,"marks":10,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q06_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2021_Jan_Q06_M10_06_GraphsOfFunctions.png","finalAnswer":"$(b)\\ (1,0),\\ y=k.\\quad (c)\\ 10-2\\sqrt{21}<k<10+2\\sqrt{21}$.","steps":[{"title":"Sketch y = -k/x","body":"Because $k>0$, $y=-\\dfrac{k}{x}$ has one branch in quadrant II and one branch in quadrant IV, with asymptotes $x=0$ and $y=0$."},{"title":"Translate the graph upward","body":"$y=-\\dfrac{k}{x}+k$ is $y=-\\dfrac{k}{x}$ translated up by $k$ units. The vertical asymptote is still $x=0$, and the horizontal asymptote is $y=k$."},{"title":"Find the x-intercept","body":"Set $y=0$: $0=-\\dfrac{k}{x}+k$. Since $k>0$, $\\dfrac{k}{x}=k$, so $x=1$. The x-intercept is $(1,0)$."},{"title":"Set up the intersection equation","body":"For intersections with $y=3x+4$, solve $-\\dfrac{k}{x}+k=3x+4$. Multiplying by $x$ gives $-k+kx=3x^2+4x$."},{"title":"Use the discriminant","body":"This rearranges to $3x^2+(4-k)x+k=0$. For no touch or intersection, the discriminant must be negative: $(4-k)^2-12k<0$."},{"title":"Solve the quadratic inequality in k","body":"$k^2-20k+16<0$. The roots are $k=10\\pm2\\sqrt{21}$, so the required range is $10-2\\sqrt{21}<k<10+2\\sqrt{21}$."}]},{"id":"WMA11-01_2021_Jan_Q08","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":8,"marks":9,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q08_M09_08_StraightLine.png","downloadName":"WMA11-01_Y2021_Jan_Q08_M09_08_StraightLine.png","finalAnswer":"$(a)\\ x>4.\\quad (b)\\ f(x)=9x^3-48x^2+52x-16.\\quad (c)\\ PQ=\\dfrac{4\\sqrt3}{3}$.","steps":[{"title":"Use the factorised form","body":"$f(x)=(3x-2)^2(x-4)$. The squared factor is never negative, and it is zero at $x=\\dfrac23$. Therefore the sign of $f(x)$ away from the repeated root is controlled by $x-4$."},{"title":"Find where f(x) is positive","body":"For $f(x)>0$, we need $x-4>0$, so $x>4$."},{"title":"Expand f(x)","body":"$(3x-2)^2=9x^2-12x+4$. Therefore $f(x)=(9x^2-12x+4)(x-4)=9x^3-48x^2+52x-16$."},{"title":"Find the line l","body":"The y-intercept of $C$ is $f(0)=-16$, so the horizontal line $l$ is $y=-16$."},{"title":"Find the other intersections with l","body":"Solve $f(x)=-16$: $9x^3-48x^2+52x-16=-16$, so $x(9x^2-48x+52)=0$. The root $x=0$ is the y-intercept, and the two other roots give $P$ and $Q$."},{"title":"Solve the quadratic","body":"$9x^2-48x+52=0$. Hence $x=\\dfrac{48\\pm\\sqrt{48^2-4(9)(52)}}{18}=\\dfrac{48\\pm12\\sqrt3}{18}=\\dfrac{8\\pm2\\sqrt3}{3}$."},{"title":"Find PQ","body":"Because $P$ and $Q$ lie on the same horizontal line, $PQ$ is the difference in their x-coordinates: $PQ=\\dfrac{8+2\\sqrt3}{3}-\\dfrac{8-2\\sqrt3}{3}=\\dfrac{4\\sqrt3}{3}$."}]},{"id":"WMA11-01_2021_MayJune_Q05","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":5,"marks":8,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q05_M08_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2021_MayJune_Q05_M08_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ 16.8\\text{ million pounds}.\\quad (b)\\ 53\\text{ million pounds}.\\quad (c)\\ 10-\\sqrt{58}<t\\le15.\\quad (d)\\ t=20\\text{ is outside the 15-year model}$.","steps":[{"title":"Evaluate both models at t = 0","body":"$P_A(0)=53-0.4(0-8)^2=53-25.6=27.4$. Also $P_B(0)=-1.6(0)+44.2=44.2$."},{"title":"Find the initial difference","body":"The difference is $44.2-27.4=16.8$, so the share values differ by $16.8$ million pounds."},{"title":"State the maximum of company A","body":"$P_A=53-0.4(t-8)^2$ has maximum value $53$, reached when $t=8$, which is within the 15-year period."},{"title":"Set up the inequality for company A greater than company B","body":"$53-0.4(t-8)^2>-1.6t+44.2$."},{"title":"Rearrange to a quadratic inequality","body":"Expanding gives $-0.4t^2+8t-16.8>0$. Multiplying by $-2.5$ reverses the inequality: $t^2-20t+42<0$."},{"title":"Find the crossing times","body":"$t=\\dfrac{20\\pm\\sqrt{400-168}}{2}=10\\pm\\sqrt{58}$. Therefore company A is greater between the two roots."},{"title":"Restrict to the 15-year period","body":"Since the model is monitored over $0\\le t\\le15$, the required times are $10-\\sqrt{58}<t\\le15$."},{"title":"Explain the limitation","body":"The model should not be used at $t=20$ because it was only built from a 15-year monitoring period; $20$ years is outside that range."}]},{"id":"WMA11-01_2021_Oct_Q06","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":6,"marks":10,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q06_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2021_Oct_Q06_M10_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ x\\text{-intercepts }(-1,0),(3,0),\\ y\\text{-intercept }(0,18).\\quad (b)\\ f(x)=2x^3-10x^2+6x+18.\\quad (c)\\ y=\\dfrac{512}{27}$.","steps":[{"title":"Use the factorised form for the sketch","body":"$f(x)=2(x+1)(x-3)^2$. The curve cuts the x-axis at $(-1,0)$ and meets the x-axis at $(3,0)$ because $x=3$ is a repeated root."},{"title":"Find the y-intercept","body":"$f(0)=2(1)(9)=18$, so the y-intercept is $(0,18)$."},{"title":"Describe the cubic shape","body":"The leading term is positive, so the cubic goes down to the left and up to the right. It crosses at $x=-1$ and touches at $x=3$."},{"title":"Expand f(x)","body":"$(x+1)(x-3)^2=(x+1)(x^2-6x+9)=x^3-5x^2+3x+9$, so $f(x)=2x^3-10x^2+6x+18$."},{"title":"Differentiate","body":"$f'(x)=6x^2-20x+6$."},{"title":"Find the gradient at x = 1/3","body":"$f'\\left(\\dfrac13\\right)=6\\left(\\dfrac19\\right)-20\\left(\\dfrac13\\right)+6=0$, so the tangent is horizontal."},{"title":"Find the y-coordinate","body":"$f\\left(\\dfrac13\\right)=2\\left(\\dfrac43\\right)\\left(-\\dfrac83\\right)^2=\\dfrac{512}{27}$."},{"title":"Write the tangent","body":"A horizontal tangent through this point has equation $y=\\dfrac{512}{27}$."}]},{"id":"WMA11-01_2022_Jan_Q04","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":4,"marks":7,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q04_M07_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2022_Jan_Q04_M07_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ P=(1,5),\\ Q=\\left(\\dfrac52,\\dfrac72\\right).\\quad (b)\\ y\\ge0,\\ y\\le6-x,\\ y\\ge6x-2x^2+1$.","steps":[{"title":"Set line equal to curve","body":"The line $x+y=6$ has equation $y=6-x$. Intersections satisfy $6-x=6x-2x^2+1$."},{"title":"Solve the quadratic","body":"Rearranging gives $2x^2-7x+5=0$, so $(2x-5)(x-1)=0$. Therefore $x=1$ or $x=\\dfrac52$."},{"title":"Find the coordinates","body":"Using $y=6-x$, the points are $P=(1,5)$ and $Q=\\left(\\dfrac52,\\dfrac72\\right)$."},{"title":"Read the bounded region","body":"Region $R$ is above the x-axis, below the line, and above the curve."},{"title":"Write the inequalities","body":"Thus $y\\ge0$, $y\\le6-x$, and $y\\ge6x-2x^2+1$."}]},{"id":"WMA11-01_2022_Jan_Q10","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":10,"marks":9,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q10_M09_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2022_Jan_Q10_M09_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ x\\text{-intercepts }\\left(-\\dfrac13,0\\right),\\left(\\dfrac13,0\\right);\\ \\text{asymptotes }x=0,\\ y=-9.\\quad (b)\\ -\\dfrac{81}{4}<k<0$.","steps":[{"title":"Find intercepts","body":"For x-intercepts, set $\\dfrac1{x^2}-9=0$. Then $x^2=\\dfrac19$, so $x=\\pm\\dfrac13$. There is no y-intercept because $x=0$ is not in the domain."},{"title":"State asymptotes","body":"The vertical asymptote is $x=0$. As $|x|$ becomes large, $\\dfrac1{x^2}\\to0$, so the horizontal asymptote is $y=-9$."},{"title":"Set up intersections with D","body":"For intersections with $y=kx^2$, solve $\\dfrac1{x^2}-9=kx^2$."},{"title":"Use u = x squared","body":"Let $u=x^2$, where $u>0$. Multiplying by $x^2$ gives $1-9u=ku^2$, so $ku^2+9u-1=0$."},{"title":"Require two positive u-values","body":"Four distinct x-values require two distinct positive values of $u$, since each positive $u$ gives $x=\\pm\\sqrt{u}$."},{"title":"Find the range of k","body":"For two positive roots, the product $-\\dfrac1k$ and sum $-\\dfrac9k$ must both be positive, so $k<0$. Also the discriminant must be positive: $81+4k>0$, so $k>-\\dfrac{81}{4}$. Therefore $-\\dfrac{81}{4}<k<0$."}]},{"id":"WMA11-01_2022_Oct_Q06","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":6,"marks":6,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q06_M06_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2022_Oct_Q06_M06_06_GraphsOfFunctions.png","finalAnswer":"The graphs intersect once, so the equation has one root.","steps":[{"title":"Key points for y = (2x-k)(x+4)^2","body":"The graph has x-intercepts $(-4,0)$ and $\\left(\\dfrac{k}{2},0\\right)$. The root at $x=-4$ is a repeated root, so the graph touches the x-axis there."},{"title":"Use 0 < k < 4","body":"Since $0<k<4$, the positive intercept $x=\\dfrac{k}{2}$ lies between 0 and 2. The y-intercept is $(0,-16k)$."},{"title":"Key features for y = k/x^2","body":"The graph is positive on both sides of the y-axis, with asymptotes $x=0$ and $y=0$. It has no intercepts with the coordinate axes."},{"title":"Compare the two graphs","body":"The equation $(2x-k)(x+4)^2=\\dfrac{k}{x^2}$ represents intersections between the two graphs."},{"title":"State the number of roots","body":"From the sketches, the positive branch of $\\dfrac{k}{x^2}$ meets the increasing positive branch of $(2x-k)(x+4)^2$ once only. Therefore there is one root."}]},{"id":"WMA11-01_2023_Oct_Q04","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":4,"marks":7,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q04_M07_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2023_Oct_Q04_M07_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ x=-2.\\quad (b)\\ x(x+2)^2.\\quad (c)$ roots at $(-2,0)$ and $(0,0)$. $x=-2$ is a repeated root. $(d)\\ 2$ real roots.","steps":[{"title":"Find the vertical asymptote","body":"For $y=\\dfrac{1}{x+2}$, the denominator is zero when $x=-2$, so the vertical asymptote is $x=-2$."},{"title":"Factorise the cubic","body":"$x^3+4x^2+4x=x(x^2+4x+4)=x(x+2)^2$."},{"title":"Use the factorised form for the sketch","body":"$x=0$ is a single root, so the curve crosses the x-axis at $(0,0)$. $x=-2$ is a repeated root, so the curve touches the x-axis at $(-2,0)$."},{"title":"Connect the equation to intersections","body":"$(x+2)(x^3+4x^2+4x)=1$ is equivalent to $x^3+4x^2+4x=\\dfrac{1}{x+2}$."},{"title":"Count the intersections","body":"The number of real solutions is the number of intersections of the cubic $y=x(x+2)^2$ and the reciprocal curve $y=\\dfrac{1}{x+2}$. The sketches show 2 intersections."}]},{"id":"WMA11-01_2024_Jan_Q07","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":7,"marks":9,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q07_M09_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2024_Jan_Q07_M09_06_GraphsOfFunctions.png","finalAnswer":"$(a)$ y-intercept $(0,-\\dfrac4k)$, no x-intercept, vertical asymptote $x=k$. $(b)\\ 5<k<13$.","steps":[{"title":"Identify the asymptote","body":"For $y=\\dfrac{4}{x-k}$, the vertical asymptote is where the denominator is zero, so $x=k$."},{"title":"Find axis intercepts","body":"At $x=0$, $y=-\\dfrac4k$, so the y-intercept is $(0,-\\dfrac4k)$. The graph has no x-intercept because the numerator is never zero."},{"title":"Set up intersection with the line","body":"If the line $y=9-x$ meets the curve, then $9-x=\\dfrac4{x-k}$."},{"title":"Form a quadratic","body":"$(9-x)(x-k)=4$, which simplifies to $x^2-(9+k)x+9k+4=0$."},{"title":"Use no real intersection","body":"For the line not to cross or touch the curve, the discriminant must be negative."},{"title":"Solve the inequality","body":"$(9+k)^2-4(9k+4)<0$, so $k^2-18k+65<0$. Since $k^2-18k+65=(k-5)(k-13)$, the range is $5<k<13$."}]},{"id":"WMA11-01_2024_MayJune_Q08","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":8,"marks":7,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q08_M07_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2024_MayJune_Q08_M07_06_GraphsOfFunctions.png","finalAnswer":"$(a)$ x-intercepts $(-2,0)$, $(0,0)$, $(2,0)$. $(b)\\ x^4-4x^2+A=0.\\quad (c)\\ 0<A<4$.","steps":[{"title":"Find the intercepts of C1","body":"$y=x(4-x^2)$, so $y=0$ when $x=0$ or $x=\\pm2$. The curve crosses the axes at $(-2,0)$, $(0,0)$ and $(2,0)$."},{"title":"Use the cubic shape","body":"$y=4x-x^3$ has negative leading cubic term, so the left tail rises and the right tail falls."},{"title":"Equate C1 and C2","body":"$x(4-x^2)=\\dfrac{A}{x}$."},{"title":"Multiply by x","body":"$x^2(4-x^2)=A$, so $4x^2-x^4=A$ and therefore $x^4-4x^2+A=0$."},{"title":"Let u equal x squared","body":"Let $u=x^2$. Then $u^2-4u+A=0$."},{"title":"Require two positive u-values","body":"For 4 distinct x-values, the quadratic in $u$ must have two distinct positive roots."},{"title":"Find the range of A","body":"The discriminant gives $16-4A>0$, so $A<4$. The product of the two roots is $A$, so $A>0$. Therefore $0<A<4$."}]},{"id":"WMA11-01_2024_Oct_Q06","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":6,"marks":9,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q06_M09_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2024_Oct_Q06_M09_06_GraphsOfFunctions.png","finalAnswer":"$(a)$ vertical asymptote $x=2$, y-intercept $(0,\\dfrac12)$. $(b)\\ k\\le1$ or $k\\ge4$.","steps":[{"title":"Identify the graph features","body":"$y=\\dfrac1{2-x}$ has vertical asymptote $x=2$ and horizontal asymptote $y=0$."},{"title":"Find the y-intercept","body":"At $x=0$, $y=\\dfrac12$, so the y-intercept is $(0,\\dfrac12)$."},{"title":"Set up the intersection with the line","body":"If $y=kx-4$ cuts $C$, then $kx-4=\\dfrac1{2-x}$."},{"title":"Form the quadratic","body":"$(kx-4)(2-x)=1$, so $kx^2-(2k+4)x+9=0$."},{"title":"Use the discriminant","body":"For at least one intersection, the discriminant is non-negative."},{"title":"Derive the given inequality","body":"$(2k+4)^2-4(k)(9)\\ge0$, so $4(k^2-5k+4)\\ge0$, hence $k^2-5k+4\\ge0$."},{"title":"Solve the inequality","body":"$k^2-5k+4=(k-1)(k-4)$, so $k\\le1$ or $k\\ge4$."}]},{"id":"WMA11-01_2025_Jan_Q07","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":7,"marks":8,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q07_M08_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2025_Jan_Q07_M08_06_GraphsOfFunctions.png","finalAnswer":"$(a)$ x-intercept $(\\dfrac2k,0)$, no y-intercept, horizontal asymptote $y=-k$. $(b)\\ 0<k<2$ or $k>18$.","steps":[{"title":"Identify the horizontal asymptote","body":"$y=\\dfrac2x-k$ has horizontal asymptote $y=-k$."},{"title":"Find axis intersections","body":"Setting $y=0$ gives $\\dfrac2x=k$, so $x=\\dfrac2k$. There is no y-intercept because $x=0$ is not in the domain."},{"title":"Set up line-curve intersections","body":"$\\dfrac2x-k=-kx-6$."},{"title":"Form a quadratic","body":"Multiplying by $x$ gives $2-kx=-kx^2-6x$, so $kx^2+(6-k)x+2=0$."},{"title":"Use two distinct intersections","body":"For two distinct points, the discriminant must be positive."},{"title":"Solve the inequality","body":"$(6-k)^2-8k>0$, so $k^2-20k+36>0$. Since $k^2-20k+36=(k-2)(k-18)$, $k<2$ or $k>18$."},{"title":"Use k positive","body":"As $k>0$, the range is $0<k<2$ or $k>18$."}]},{"id":"WMA11-01_2025_MayJune_Q07","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":7,"marks":10,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q07_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2025_MayJune_Q07_M10_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ f(x)=0.2x^2(x-4).\\quad (c)\\ (-8,-153.6),\\ (0,0),\\ (6,14.4)$.","steps":[{"title":"Use the repeated root at the origin","body":"Since the cubic touches the x-axis at the origin and cuts it at $x=4$, write $f(x)=\\lambda x^2(x-4)$."},{"title":"Use the point (10,120)","body":"$120=\\lambda(10)^2(10-4)=600\\lambda$, so $\\lambda=0.2$."},{"title":"State f(x)","body":"$f(x)=0.2x^2(x-4)$."},{"title":"Sketch C2","body":"$C_2:y=1.2x(8-x)$ is a downward-opening parabola through $x=0$ and $x=8$, with its maximum between them."},{"title":"Set intersections equal","body":"$1.2x(8-x)=0.2x^2(x-4)$."},{"title":"Clear decimals","body":"Divide by $0.2$ to get $6x(8-x)=x^2(x-4)$."},{"title":"Factor","body":"$48x-6x^2=x^3-4x^2$, so $x^3+2x^2-48x=0$ and $x(x^2+2x-48)=0$."},{"title":"Solve for x","body":"$x=0$, or $x^2+2x-48=0=(x+8)(x-6)$, so $x=-8$ or $x=6$."},{"title":"Find y-values","body":"Using $y=1.2x(8-x)$ gives $(-8,-153.6)$, $(0,0)$ and $(6,14.4)$."}]},{"id":"WMA11-01_2025_Oct_Q06","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":6,"marks":9,"topic":"06_GraphsOfFunctions","topicName":"Graphs of Functions","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q06_M09_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2025_Oct_Q06_M09_06_GraphsOfFunctions.png","finalAnswer":"$(a)$ y-intercept $(0,-2)$, vertical asymptote $x=2k$. $(b)\\ 0<k\\le\\dfrac12\\text{ or }k\\ge\\dfrac92$.","steps":[{"title":"Find coordinate-axis intersections","body":"$y=\\dfrac{4k}{x-2k}$ has no x-intercept because the numerator is non-zero. At $x=0$, $y=\\dfrac{4k}{-2k}=-2$, so the y-intercept is $(0,-2)$."},{"title":"Find the vertical asymptote","body":"The denominator is zero when $x=2k$, so the vertical asymptote is $x=2k$."},{"title":"Sketch shape","body":"The curve has one branch in quadrant I to the right of $x=2k$, and one branch passing through $(0,-2)$ and approaching the x-axis from below as $x\\to-\\infty$."},{"title":"Set line and curve equal","body":"$\\dfrac{4k}{x-2k}=6-2x$."},{"title":"Form a quadratic in x","body":"$4k=(6-2x)(x-2k)=6x-12k-2x^2+4kx$, so $2x^2-(4k+6)x+16k=0$."},{"title":"Use at least one intersection","body":"For at least one real intersection, the discriminant must satisfy $b^2-4ac\\ge0$."},{"title":"Find the discriminant","body":"$(4k+6)^2-4(2)(16k)\\ge0$, so $16k^2-80k+36\\ge0$."},{"title":"Solve in k","body":"$4k^2-20k+9\\ge0$, so $(2k-1)(2k-9)\\ge0$."},{"title":"Use k positive","body":"Therefore $k\\le\\dfrac12$ or $k\\ge\\dfrac92$. Since $k$ is positive, $0<k\\le\\dfrac12$ or $k\\ge\\dfrac92$."}]},{"id":"WMA11-01_2021_Oct_Q09","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":9,"marks":9,"topic":"07_Transformations","topicName":"Transformations","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q09_M09_07_Transformations.png","downloadName":"WMA11-01_Y2021_Oct_Q09_M09_07_Transformations.png","finalAnswer":"$(a)\\ P\\mapsto\\left(\\dfrac92,3\\right)\\text{ on }y=f(2x),\\ P\\mapsto(9,6)\\text{ on }y=f(x)+3.\\quad (c)\\ Q=(27+18\\sqrt2,\\ 6+3\\sqrt2)$.","steps":[{"title":"Transform P on y = f(2x)","body":"$y=f(2x)$ is a horizontal scale factor of $\\dfrac12$, so $P(9,3)$ maps to $\\left(\\dfrac92,3\\right)$."},{"title":"Transform P on y = f(x) + 3","body":"$y=f(x)+3$ is a translation 3 units upward, so $P(9,3)$ maps to $(9,6)$."},{"title":"Set up the intersection equation","body":"At $Q$, $f(2x)=f(x)+3$. Since $f(x)=\\sqrt{x}$, this gives $\\sqrt{2x}=\\sqrt{x}+3$."},{"title":"Show the required equation","body":"Let $s=\\sqrt{x}$. Then $\\sqrt{2x}=\\sqrt2\\,s$, so $\\sqrt2s=s+3$. Hence $(\\sqrt2-1)s=3$ and $s=\\dfrac3{\\sqrt2-1}=3(\\sqrt2+1)$."},{"title":"Find the x-coordinate","body":"$\\sqrt{x}=3(\\sqrt2+1)$, so $x=9(\\sqrt2+1)^2=9(3+2\\sqrt2)=27+18\\sqrt2$."},{"title":"Find the y-coordinate","body":"$y=\\sqrt{x}+3=3(\\sqrt2+1)+3=6+3\\sqrt2$. Therefore $Q=(27+18\\sqrt2,\\ 6+3\\sqrt2)$."}]},{"id":"WMA11-01_2022_MayJune_Q04","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":4,"marks":6,"topic":"07_Transformations","topicName":"Transformations","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q04_M06_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2022_MayJune_Q04_M06_06_GraphsOfFunctions.png","finalAnswer":"$(i)$ minimum $(-1,-2)$, maximum $(\\frac32,0)$, asymptote $y=-1$. $(ii)$ minimum $(1,0)$, maximum $(-\\frac32,2)$, asymptote $y=1$.","steps":[{"title":"Translate for y = f(x) - 2","body":"Subtracting 2 moves every point of the graph down by 2 units."},{"title":"State the new key features","body":"The minimum $P(-1,0)$ becomes $(-1,-2)$, the maximum $Q(\\frac32,2)$ becomes $(\\frac32,0)$, and the asymptote $y=1$ becomes $y=-1$."},{"title":"Reflect for y = f(-x)","body":"Replacing $x$ by $-x$ reflects the graph in the y-axis."},{"title":"State the reflected key features","body":"The minimum $P(-1,0)$ becomes $(1,0)$, the maximum $Q(\\frac32,2)$ becomes $(-\\frac32,2)$, and the horizontal asymptote remains $y=1$."}]},{"id":"WMA11-01_2022_Oct_Q07","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":7,"marks":8,"topic":"07_Transformations","topicName":"Transformations","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q07_M08_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2022_Oct_Q07_M08_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ x<-4,\\ -1<x<2,\\ x>3.\\quad (b)\\ \\dfrac32.\\quad (c)(ii)\\ -3\\le x\\le -2$.","steps":[{"title":"Read f(x) < 6 from the graph","body":"The curve is below the line $y=6$ for $x<-4$, for $-1<x<2$, and for $x>3$."},{"title":"Solve f(2x) = 6","body":"Since $f(u)=6$ at $u=-4,-1,2,3$, we set $2x=-4,-1,2,3$. The solutions are $x=-2,-\\dfrac12,1,\\dfrac32$."},{"title":"State the largest solution","body":"The largest solution is $x=\\dfrac32$."},{"title":"Reflect the points in the y-axis","body":"For $y=f(-x)$, each point $(x,y)$ becomes $(-x,y)$."},{"title":"List the transformed points","body":"$P(-4,6)\\to(4,6)$, $Q(-1,6)\\to(1,6)$, $R(2,6)\\to(-2,6)$, and $S(3,6)\\to(-3,6)$."},{"title":"Use the reflected graph","body":"For $x<0$, the part of the reflected graph on or above $y=6$ is from $x=-3$ to $x=-2$."}]},{"id":"WMA11-01_2023_Jan_Q07","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":7,"marks":10,"topic":"07_Transformations","topicName":"Transformations","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q07_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2023_Jan_Q07_M10_06_GraphsOfFunctions.png","finalAnswer":"$(b)$ Translation 2 units right. $(c)\\ k=2.\\quad (d)\\ Q=\\left(\\dfrac52,12\\right)$.","steps":[{"title":"Sketch y = 6/x","body":"The graph is a rectangular hyperbola with asymptotes $x=0$ and $y=0$, with branches in quadrants I and III."},{"title":"Describe the transformation","body":"$y=\\dfrac6{x-2}$ is obtained from $y=\\dfrac6x$ by a translation 2 units in the positive x-direction."},{"title":"Use P to find k","body":"At $x=-4$ on $y=\\dfrac6{x-2}$, $y=\\dfrac6{-6}=-1$."},{"title":"Substitute into the line","body":"Since $P$ lies on $y=kx+7$, $-1=-4k+7$, so $k=2$."},{"title":"Find the second intersection","body":"Solve $\\dfrac6{x-2}=2x+7$. Multiplying by $x-2$ gives $6=(2x+7)(x-2)$."},{"title":"Factor and choose Q","body":"$6=2x^2+3x-14$, so $2x^2+3x-20=0=(2x-5)(x+4)$. The root $x=-4$ is $P$, so $Q$ has $x=\\dfrac52$."},{"title":"Find y for Q","body":"$y=2\\left(\\dfrac52\\right)+7=12$, so $Q=\\left(\\dfrac52,12\\right)$."}]},{"id":"WMA11-01_2024_MayJune_Q03","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":3,"marks":6,"topic":"07_Transformations","topicName":"Transformations","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q03_M06_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2024_MayJune_Q03_M06_06_GraphsOfFunctions.png","finalAnswer":"$(a)$ intercepts $(-4,0)$ and $(0,0)$, with $(0,0)$ a touch point. $(b)$ intercepts $(-1,0)$, $(\\dfrac13,0)$ and $(0,2)$, with $(-1,0)$ a touch point.","steps":[{"title":"Read the original key points","body":"The original curve passes through $(-1,0)$ and $(0,2)$, and touches the x-axis at $(3,0)$."},{"title":"Transform y equals f of x plus 3","body":"$y=f(x+3)$ is a translation 3 units left. So $(-1,0)$ moves to $(-4,0)$, $(0,2)$ moves to $(-3,2)$, and $(3,0)$ moves to $(0,0)$."},{"title":"State the axis intercepts for part a","body":"The curve cuts the x-axis at $(-4,0)$ and touches it at $(0,0)$. The y-intercept is also $(0,0)$."},{"title":"Transform y equals f of negative 3x","body":"For $y=f(-3x)$, a point with original x-coordinate $X$ moves to $x=-\\dfrac{X}{3}$."},{"title":"State the axis intercepts for part b","body":"$(-1,0)$ moves to $(\\dfrac13,0)$, $(3,0)$ moves to $(-1,0)$, and $(0,2)$ stays at $(0,2)$."}]},{"id":"WMA11-01_2025_MayJune_Q09","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":9,"marks":10,"topic":"07_Transformations","topicName":"Transformations","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q09_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2025_MayJune_Q09_M10_06_GraphsOfFunctions.png","finalAnswer":"$(a)(i)$ stretch parallel to the x-axis scale factor $\\dfrac12$ (equivalently vertical stretch scale factor $\\sqrt2$). $(a)(ii)$ translation by $\\begin{pmatrix}0\\\\12\\end{pmatrix}$. $(b)\\ P=(144(3-2\\sqrt2),\\ 24-12\\sqrt2)$.","steps":[{"title":"Transform y equals root x to C1","body":"$C_1$ has equation $y=\\sqrt{2x}$. This is obtained from $y=\\sqrt{x}$ by a stretch parallel to the x-axis with scale factor $\\dfrac12$."},{"title":"Equivalent description","body":"Equivalently, $y=\\sqrt{2x}=\\sqrt2\\sqrt{x}$ is a stretch parallel to the y-axis with scale factor $\\sqrt2$. The mark scheme also accepts the horizontal stretch description."},{"title":"Transform y equals minus root x to C2","body":"$C_2$ has equation $y=12-\\sqrt{x}=-\\sqrt{x}+12$, so it is a translation of $y=-\\sqrt{x}$ by $\\begin{pmatrix}0\\\\12\\end{pmatrix}$."},{"title":"Set the curves equal","body":"At $P$, $\\sqrt{2x}=12-\\sqrt{x}$."},{"title":"Factor out root x","body":"$\\sqrt2\\sqrt{x}+\\sqrt{x}=12$, so $(\\sqrt2+1)\\sqrt{x}=12$."},{"title":"Rationalise","body":"$\\sqrt{x}=\\dfrac{12}{\\sqrt2+1}=\\dfrac{12(\\sqrt2-1)}{(\\sqrt2+1)(\\sqrt2-1)}=12(\\sqrt2-1)$."},{"title":"Find x","body":"$x=[12(\\sqrt2-1)]^2=144(3-2\\sqrt2)$."},{"title":"Find y","body":"$y=\\sqrt{2x}=\\sqrt2\\sqrt{x}=\\sqrt2\\cdot12(\\sqrt2-1)=24-12\\sqrt2$."}]},{"id":"WMA11-01_2025_Oct_Q09","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":9,"marks":6,"topic":"07_Transformations","topicName":"Transformations","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q09_M06_07_Transformations.png","downloadName":"WMA11-01_Y2025_Oct_Q09_M06_07_Transformations.png","finalAnswer":"$(a)\\ f(x)=-4\\sin x.\\quad (b)(i)\\ \\left(\\dfrac{5\\pi}{3},4\\right).\\quad (b)(ii)\\ \\left(\\dfrac{3\\pi}{2},-2\\right)$.","steps":[{"title":"Identify amplitude and direction","body":"The graph has amplitude $4$, crosses the origin, and initially moves downwards, so $f(x)=-4\\sin x$."},{"title":"Identify P","body":"The labelled maximum is at $P=\\left(\\dfrac{3\\pi}{2},4\\right)$."},{"title":"Transform y equals f of x minus pi over 6","body":"$y=f\\left(x-\\dfrac\\pi6\\right)$ translates the graph right by $\\dfrac\\pi6$."},{"title":"New coordinates for part b(i)","body":"$P$ becomes $\\left(\\dfrac{3\\pi}{2}+\\dfrac\\pi6,4\\right)=\\left(\\dfrac{5\\pi}{3},4\\right)$."},{"title":"Transform y equals negative half f(x)","body":"$y=-\\dfrac12f(x)$ leaves x-coordinates unchanged and multiplies y-coordinates by $-\\dfrac12$."},{"title":"New coordinates for part b(ii)","body":"$P$ becomes $\\left(\\dfrac{3\\pi}{2},-2\\right)$."}]},{"id":"WMA11-01_2019_Oct_Q02","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":2,"marks":5,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q02_M05_02_Quadratics.png","downloadName":"WMA11-01_Y2019_Oct_Q02_M05_02_Quadratics.png","finalAnswer":"$a=0.32,\\ b=1.21.\\quad$ Height when planted: $1.21\\text{ m}$.","steps":[{"title":"Form two equations","body":"Using $H=at+b$: when $t=2$, $2a+b=1.85$; when $t=7$, $7a+b=3.45$."},{"title":"Solve for the gradient of the model","body":"Subtract the first equation from the second: $5a=1.60$, so $a=0.32$."},{"title":"Find the starting height","body":"Substitute into $2a+b=1.85$: $0.64+b=1.85$, hence $b=1.21$. At planting, $t=0$, so $H=b=1.21\\text{ m}$."}]},{"id":"WMA11-01_2020_Jan_Q06","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":6,"marks":8,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q06_M08_08_StraightLine.png","downloadName":"WMA11-01_Y2020_Jan_Q06_M08_08_StraightLine.png","finalAnswer":"$(a)\\ 3x-4y-24=0.\\quad (b)\\ \\dfrac{220}{3}.\\quad (c)\\ S=\\left(\\dfrac43,-5\\right)$.","steps":[{"title":"Find the gradient of l1","body":"$3x-4y+20=0$ gives $y=\\frac34x+5$, so the gradient is $\\frac34$."},{"title":"Find l2 through R","body":"Line $l_2$ is parallel to $l_1$ and passes through $R(8,0)$, so $y=\\frac34(x-8)=\\frac34x-6$. Therefore $3x-4y-24=0$."},{"title":"Find P and Q","body":"For $l_1$, the x-intercept is $P\\left(-\\frac{20}{3},0\\right)$ and the y-intercept is $Q=(0,5)$."},{"title":"Find the area of PQRS","body":"Base $PR=8-\\left(-\\frac{20}{3}\\right)=\\frac{44}{3}$ and height $OQ=5$. Area $=\\frac{44}{3}\\cdot5=\\frac{220}{3}$."},{"title":"Find S using a vector","body":"In parallelogram $PQRS$, $\\vec{PS}=\\vec{QR}=(8,-5)$. Hence $S=P+(8,-5)=\\left(-\\frac{20}{3}+8,-5\\right)=\\left(\\frac43,-5\\right)$."}]},{"id":"WMA11-01_2021_Jan_Q04","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":4,"marks":8,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q04_M08_08_StraightLine.png","downloadName":"WMA11-01_Y2021_Jan_Q04_M08_08_StraightLine.png","finalAnswer":"$(a)\\ y=-3x+7.\\quad (b)\\ y=\\dfrac12(x-4)^2-5.\\quad (c)\\ y>-3x+7,\\ y<\\dfrac12(x-4)^2-5,\\ x<-2$.","steps":[{"title":"Find the line through P and Q","body":"The gradient is $\\dfrac{-5-13}{4-(-2)}=\\dfrac{-18}{6}=-3$. Using $P(-2,13)$, $y-13=-3(x+2)$, hence $y=-3x+7$."},{"title":"Use vertex form for the quadratic","body":"The minimum point is $Q(4,-5)$, so the curve has form $y=a(x-4)^2-5$."},{"title":"Substitute P to find a","body":"Since $P(-2,13)$ lies on the curve, $13=a(-6)^2-5$. Therefore $18=36a$ and $a=\\dfrac12$."},{"title":"Write the curve","body":"$C$ has equation $y=\\dfrac12(x-4)^2-5$."},{"title":"Define the shaded region","body":"In the shaded second-quadrant region, points are above the line, below the curve, and to the left of $P$. Therefore $y>-3x+7$, $y<\\dfrac12(x-4)^2-5$, and $x<-2$."}]},{"id":"WMA11-01_2021_Oct_Q03","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":3,"marks":6,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q03_M06_08_StraightLine.png","downloadName":"WMA11-01_Y2021_Oct_Q03_M06_08_StraightLine.png","finalAnswer":"$(i)\\ 0<x<\\dfrac34.\\quad (ii)\\ y>3x+15,\\ y<2x^2-50,\\ x<-5$.","steps":[{"title":"Solve the rational inequality","body":"$\\dfrac3x>4$ is equivalent to $\\dfrac{3-4x}{x}>0$."},{"title":"Use critical values","body":"The critical values are $x=0$ and $x=\\dfrac34$. A sign check gives the positive interval $0<x<\\dfrac34$."},{"title":"Find the equation of l","body":"The curve $C$ meets the negative x-axis when $2x^2-50=0$, so $x=-5$. Since $l$ has gradient $3$ and passes through $(-5,0)$, $y=3(x+5)=3x+15$."},{"title":"Define the shaded region","body":"The shaded region lies above the line, below the curve, and to the left of their negative x-axis intersection. Hence $y>3x+15$, $y<2x^2-50$, and $x<-5$."}]},{"id":"WMA11-01_2021_Oct_Q05","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":5,"marks":8,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q05_M08_08_StraightLine.png","downloadName":"WMA11-01_Y2021_Oct_Q05_M08_08_StraightLine.png","finalAnswer":"$(a)\\ P=(12,18).\\quad (b)\\ 351$ square units.","steps":[{"title":"Rewrite l1","body":"$3y-2x=30$ gives $y=\\dfrac23x+10$, so the gradient of $l_1$ is $\\dfrac23$."},{"title":"Find l2","body":"Since $l_2$ is perpendicular to $l_1$, its gradient is $-\\dfrac32$. Through $A(24,0)$, $y=-\\dfrac32(x-24)=-\\dfrac32x+36$."},{"title":"Solve for P","body":"At the intersection, $\\dfrac23x+10=-\\dfrac32x+36$. Multiplying by $6$ gives $4x+60=-9x+216$, so $13x=156$ and $x=12$."},{"title":"Find the y-coordinate","body":"$y=\\dfrac23(12)+10=18$, so $P=(12,18)$."},{"title":"Find B","body":"For the x-intercept of $l_1$, set $y=0$: $-2x=30$, so $x=-15$. Hence $B=(-15,0)$."},{"title":"Find the triangle area","body":"The base $BA$ has length $24-(-15)=39$, and the height from $P$ to the x-axis is $18$. Area $=\\dfrac12(39)(18)=351$."}]},{"id":"WMA11-01_2021_Oct_Q08","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":8,"marks":10,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q08_M10_08_StraightLine.png","downloadName":"WMA11-01_Y2021_Oct_Q08_M10_08_StraightLine.png","finalAnswer":"$(a)(i)\\ 16-3(x-2)^2.\\quad (a)(ii)\\ M=(2,16).\\quad (b)\\ y=8x+\\dfrac{16}{3}$.","steps":[{"title":"Complete the square","body":"$4+12x-3x^2=-3(x^2-4x)+4=-3\\big((x-2)^2-4\\big)+4=16-3(x-2)^2$."},{"title":"State the maximum point","body":"The maximum occurs when $(x-2)^2=0$, so $M=(2,16)$."},{"title":"Find the gradient of l1","body":"Line $l_1$ passes through $O(0,0)$ and $M(2,16)$, so its gradient is $\\dfrac{16}{2}=8$."},{"title":"Use the parallel tangent gradient","body":"Line $l_2$ is parallel to $l_1$, so its gradient is also $8$. For $y=4+12x-3x^2$, $\\dfrac{dy}{dx}=12-6x$."},{"title":"Find the point of contact","body":"Set $12-6x=8$, giving $x=\\dfrac23$. Then $y=4+12\\left(\\dfrac23\\right)-3\\left(\\dfrac49\\right)=\\dfrac{32}{3}$."},{"title":"Write l2","body":"Using gradient $8$ through $\\left(\\dfrac23,\\dfrac{32}{3}\\right)$, $y-\\dfrac{32}{3}=8\\left(x-\\dfrac23\\right)$. Hence $y=8x+\\dfrac{16}{3}$."}]},{"id":"WMA11-01_2022_Jan_Q08","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":8,"marks":9,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q08_M09_08_StraightLine.png","downloadName":"WMA11-01_Y2022_Jan_Q08_M09_08_StraightLine.png","finalAnswer":"$(a)\\ \\dfrac25.\\quad (b)\\ y=-\\dfrac52x+13.\\quad (c)\\ M=(4,3).\\quad (d)\\ C=(2,8)$.","steps":[{"title":"Find the gradient of l1","body":"$2x-5y+7=0$ gives $y=\\dfrac25x+\\dfrac75$, so the gradient is $\\dfrac25$."},{"title":"Find l2","body":"The gradient perpendicular to $\\dfrac25$ is $-\\dfrac52$. Through $A(6,-2)$, $y+2=-\\dfrac52(x-6)$, so $y=-\\dfrac52x+13$."},{"title":"Find M","body":"At the intersection, $\\dfrac25x+\\dfrac75=-\\dfrac52x+13$. Multiplying by $10$ gives $4x+14=-25x+130$, so $x=4$."},{"title":"Find the y-coordinate of M","body":"$y=\\dfrac25(4)+\\dfrac75=3$, so $M=(4,3)$."},{"title":"Use midpoint of the diagonal","body":"In a square, the diagonals bisect each other, so $M$ is the midpoint of $AC$. Thus $C=2M-A=(8,6)-(6,-2)=(2,8)$."}]},{"id":"WMA11-01_2022_MayJune_Q05","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":5,"marks":9,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q05_M09_08_StraightLine.png","downloadName":"WMA11-01_Y2022_MayJune_Q05_M09_08_StraightLine.png","finalAnswer":"$(a)\\ f(x)=-\\dfrac43(x+5)(x-1).\\quad (b)\\ y=-\\dfrac54x-\\dfrac{25}{4}.\\quad (c)\\ y\\le f(x),\\ y\\ge\\dfrac45x,\\ y\\ge-\\dfrac54x-\\dfrac{25}{4}$.","steps":[{"title":"Use symmetry of the quadratic","body":"The maximum is at $x=-2$, and one root is $x=-5$. The other root is the same distance to the right of $-2$, so it is $x=1$."},{"title":"Find the quadratic","body":"Let $f(x)=a(x+5)(x-1)$. Since the maximum point is $(-2,12)$, $12=a(3)(-3)=-9a$, so $a=-\\dfrac43$."},{"title":"Find the perpendicular gradient","body":"The gradient of $l_1$ is $\\dfrac45$, so the gradient of a perpendicular line is $-\\dfrac54$."},{"title":"Find l2","body":"Using the point $(-5,0)$, $y=-\\dfrac54x+c$. Then $0=\\dfrac{25}{4}+c$, so $c=-\\dfrac{25}{4}$ and $l_2$ is $y=-\\dfrac54x-\\dfrac{25}{4}$."},{"title":"Write the inequalities for R","body":"The region is below the curve and above both straight lines, so $y\\le f(x)$, $y\\ge\\dfrac45x$, and $y\\ge-\\dfrac54x-\\dfrac{25}{4}$."}]},{"id":"WMA11-01_2022_Oct_Q03","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":3,"marks":5,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q03_M05_02_Quadratics.png","downloadName":"WMA11-01_Y2022_Oct_Q03_M05_02_Quadratics.png","finalAnswer":"$(a)\\ p=0.3,\\ q=0.15.\\quad (b)\\ T=7.8$ years.","steps":[{"title":"Use the two data points","body":"The model $V=pt+q$ passes through $(3,1.05)$ and $(5,1.65)$."},{"title":"Find the gradient","body":"$p=\\dfrac{1.65-1.05}{5-3}=\\dfrac{0.60}{2}=0.30$."},{"title":"Find the intercept","body":"Using $1.05=0.30(3)+q$, we get $q=0.15$."},{"title":"Find T","body":"For $V=2.50$, $2.50=0.30T+0.15$, so $T=\\dfrac{2.35}{0.30}=7.833\\ldots$."},{"title":"Round correctly","body":"To one decimal place, $T=7.8$."}]},{"id":"WMA11-01_2023_Jan_Q02","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":2,"marks":5,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q02_M05_09_BasicTrig.png","downloadName":"WMA11-01_Y2023_Jan_Q02_M05_09_BasicTrig.png","finalAnswer":"$(a)$ Angle $PQR=90^\\circ$. $(b)\\ S=(0,-2)$.","steps":[{"title":"Find the gradient of PQ","body":"$m_{PQ}=\\dfrac{11-7}{9-(-3)}=\\dfrac4{12}=\\dfrac13$."},{"title":"Find the gradient of QR","body":"$m_{QR}=\\dfrac{2-11}{12-9}=\\dfrac{-9}{3}=-3$."},{"title":"Prove the right angle","body":"$m_{PQ}m_{QR}=\\dfrac13(-3)=-1$, so $PQ$ and $QR$ are perpendicular. Hence angle $PQR=90^\\circ$."},{"title":"Use the rectangle vector","body":"For rectangle $PQRS$, $\\overrightarrow{PS}=\\overrightarrow{QR}=(12-9,2-11)=(3,-9)$."},{"title":"Find S","body":"$S=P+\\overrightarrow{QR}=(-3,7)+(3,-9)=(0,-2)$."}]},{"id":"WMA11-01_2023_MayJune_Q10","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":10,"marks":10,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q10_M10_08_StraightLine.png","downloadName":"WMA11-01_Y2023_MayJune_Q10_M10_08_StraightLine.png","finalAnswer":"$(a)(i)\\ y=\\dfrac12x+1.\\quad (a)(ii)\\ P=\\left(b-2,\\dfrac b2\\right).\\quad (b)\\ y=-2x+2b.\\quad (d)\\ b=8$.","steps":[{"title":"Find l1","body":"Line $l_1$ has gradient $\\dfrac12$ and passes through the negative x-axis root $(-2,0)$, so $y=\\dfrac12(x+2)=\\dfrac12x+1$."},{"title":"Find P","body":"Set $-\\dfrac14(x+2)(x-b)=\\dfrac12(x+2)$."},{"title":"Solve the intersection","body":"Multiplying by $-4$ gives $(x+2)(x-b)=-2(x+2)$, so $(x+2)(x-b+2)=0$."},{"title":"Choose the second point","body":"The root $x=-2$ is the x-axis point, so $P$ has $x=b-2$. Then $y=\\dfrac12(b-2)+1=\\dfrac b2$."},{"title":"Find l2 from the positive root","body":"Since $l_2$ is perpendicular to $l_1$, its gradient is $-2$. It passes through the positive x-axis root $(b,0)$, so $y=-2(x-b)=-2x+2b$."},{"title":"Use P to write another l2","body":"Through $P\\left(b-2,\\dfrac b2\\right)$ with gradient $-2$: $y-\\dfrac b2=-2(x-(b-2))$, so $y=-2x+\\dfrac{5b}{2}-4$."},{"title":"Find b","body":"Both equations represent $l_2$, so $2b=\\dfrac{5b}{2}-4$. Hence $b=8$."}]},{"id":"WMA11-01_2024_Jan_Q05","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":5,"marks":10,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q05_M10_08_StraightLine.png","downloadName":"WMA11-01_Y2024_Jan_Q05_M10_08_StraightLine.png","finalAnswer":"$(a)\\ y=-\\dfrac14x+\\dfrac{17}{2}.\\quad (b)\\ R=(2,8).\\quad (c)\\ \\text{Area}=51$.","steps":[{"title":"Find the gradient of l1","body":"$m=\\dfrac{6-9}{10-(-2)}=-\\dfrac{3}{12}=-\\dfrac14$."},{"title":"Find the equation of l1","body":"Using $P(-2,9)$, $y=-\\dfrac14x+c$. Then $9=\\dfrac12+c$, so $c=\\dfrac{17}{2}$."},{"title":"Find the equation of l2","body":"A line perpendicular to gradient $-\\dfrac14$ has gradient $4$. Since $l_2$ passes through the origin, $l_2$ is $y=4x$."},{"title":"Find R","body":"At the intersection, $4x=-\\dfrac14x+\\dfrac{17}{2}$. Hence $\\dfrac{17}{4}x=\\dfrac{17}{2}$, so $x=2$ and $y=8$."},{"title":"Use coordinate area","body":"For $O(0,0)$, $P(-2,9)$ and $Q(10,6)$, the area is $\\dfrac12\\left|(-2)(6)-9(10)\\right|=51$."}]},{"id":"WMA11-01_2024_MayJune_Q09","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":9,"marks":9,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q09_M09_08_StraightLine.png","downloadName":"WMA11-01_Y2024_MayJune_Q09_M09_08_StraightLine.png","finalAnswer":"$(a)\\ 5x-11y+2=0.\\quad (b)\\ C=(5,2)$ or $(25,2).\\quad (c)\\ \\dfrac52$.","steps":[{"title":"Find the gradient of l1","body":"$m=\\dfrac{7-2}{15-4}=\\dfrac5{11}$."},{"title":"Use point A","body":"$y-2=\\dfrac5{11}(x-4)$."},{"title":"Rearrange","body":"$11y-22=5x-20$, so $5x-11y+2=0$."},{"title":"Use the horizontal line l2","body":"Since $l_2$ passes through $A(4,2)$ and is parallel to the x-axis, point $C$ has coordinates $(c,2)$."},{"title":"Use BC equals 5 root 5","body":"$(c-15)^2+(2-7)^2=(5\\sqrt5)^2$."},{"title":"Solve for c","body":"$(c-15)^2+25=125$, so $(c-15)^2=100$ and $c=5$ or $25$."},{"title":"Find the smaller area","body":"The height from $B$ to $y=2$ is $5$. For $C=(5,2)$, $AC=1$, so the minimum area is $\\dfrac12(1)(5)=\\dfrac52$."}]},{"id":"WMA11-01_2024_Oct_Q01","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":1,"marks":6,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q01_M06_08_StraightLine.png","downloadName":"WMA11-01_Y2024_Oct_Q01_M06_08_StraightLine.png","finalAnswer":"$(a)\\ y=-3x+5.\\quad (b)\\ x-3y+25=0$.","steps":[{"title":"Find the gradient of l1","body":"$m=\\dfrac{-4-20}{3-(-5)}=\\dfrac{-24}{8}=-3$."},{"title":"Find the equation of l1","body":"Using $B(3,-4)$, $y=-3x+c$. Then $-4=-9+c$, so $c=5$."},{"title":"Find the midpoint of AB","body":"$M=\\left(\\dfrac{-5+3}{2},\\dfrac{20+(-4)}{2}\\right)=(-1,8)$."},{"title":"Use perpendicular gradient","body":"Since $l_1$ has gradient $-3$, $l_2$ has gradient $\\dfrac13$."},{"title":"Find the equation of l2","body":"$y-8=\\dfrac13(x+1)$, so $3y-24=x+1$ and $x-3y+25=0$."}]},{"id":"WMA11-01_2025_Jan_Q02","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":2,"marks":5,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q02_M05_08_StraightLine.png","downloadName":"WMA11-01_Y2025_Jan_Q02_M05_08_StraightLine.png","finalAnswer":"$(a)\\ \\text{gradient}=\\dfrac19\\sqrt3.\\quad (b)\\ y=-3\\sqrt3x-13$.","steps":[{"title":"Find the gradient of l1","body":"$m=\\dfrac{8-5}{7\\sqrt3-(-2\\sqrt3)}=\\dfrac{3}{9\\sqrt3}=\\dfrac{1}{3\\sqrt3}=\\dfrac{\\sqrt3}{9}$."},{"title":"Find the perpendicular gradient","body":"The gradient of $l_2$ is the negative reciprocal of $\\dfrac{\\sqrt3}{9}$, so $m_2=-\\dfrac9{\\sqrt3}=-3\\sqrt3$."},{"title":"Use point A","body":"$l_2$ passes through $A(-2\\sqrt3,5)$, so $y-5=-3\\sqrt3(x+2\\sqrt3)$."},{"title":"Simplify","body":"$y-5=-3\\sqrt3x-18$, hence $y=-3\\sqrt3x-13$."}]},{"id":"WMA11-01_2025_MayJune_Q05","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":5,"marks":7,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q05_M07_08_StraightLine.png","downloadName":"WMA11-01_Y2025_MayJune_Q05_M07_08_StraightLine.png","finalAnswer":"$(a)\\ y=-2x.\\quad (b)\\ I=(-5,10).\\quad (c)\\ 5\\sqrt5$.","steps":[{"title":"Find the gradient of l1","body":"$l_1:x-2y+25=0$ gives $y=\\dfrac12x+\\dfrac{25}{2}$, so its gradient is $\\dfrac12$."},{"title":"Use perpendicular gradient","body":"A line perpendicular to $l_1$ has gradient $-2$."},{"title":"Use the origin","body":"Since $l_2$ passes through the origin, its equation is $y=-2x$."},{"title":"Find the intersection","body":"Substitute $y=-2x$ into $x-2y+25=0$ to get $x+4x+25=0$."},{"title":"Coordinates of I","body":"$5x+25=0$, so $x=-5$ and $y=10$. Hence $I=(-5,10)$."},{"title":"Shortest distance from I to origin","body":"The distance is $\\sqrt{(-5)^2+10^2}=\\sqrt{125}=5\\sqrt5$."}]},{"id":"WMA11-01_2026_Jan_Q04","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":4,"marks":9,"topic":"08_StraightLine","topicName":"Straight Line","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q04_M09_08_StraightLine.png","downloadName":"WMA11-01_Y2026_Jan_Q04_M09_08_StraightLine.png","finalAnswer":"$(a)\\ 3x+4y-29=0.\\quad (b)\\ C=(-7,0).\\quad (c)\\ 50$.","steps":[{"title":"Gradient of L1","body":"Using $A(-1,8)$ and $B(7,2)$, $m=\\dfrac{2-8}{7-(-1)}=-\\dfrac68=-\\dfrac34$."},{"title":"Equation of L1","body":"$y-2=-\\dfrac34(x-7)$."},{"title":"Rearrange","body":"$4y-8=-3x+21$, hence $3x+4y-29=0$."},{"title":"Gradient of L2","body":"Since $L_2$ is perpendicular to $L_1$, its gradient is $\\dfrac43$."},{"title":"Equation of L2","body":"$L_2$ passes through $A(-1,8)$, so $y-8=\\dfrac43(x+1)$."},{"title":"Find C","body":"At the x-axis, $y=0$, so $-8=\\dfrac43(x+1)$. Hence $x+1=-6$ and $x=-7$, giving $C=(-7,0)$."},{"title":"Find perpendicular side lengths","body":"$AB=\\sqrt{8^2+(-6)^2}=10$ and $AC=\\sqrt{(-6)^2+(-8)^2}=10$."},{"title":"Area of triangle ABC","body":"Since $AB\\perp AC$, $\\text{Area}=\\dfrac12(10)(10)=50$."}]},{"id":"WMA11-01_2019_Oct_Q04","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":4,"marks":5,"topic":"09_BasicTrig","topicName":"Basic Trigonometry","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q04_M05_09_BasicTrig.png","downloadName":"WMA11-01_Y2019_Oct_Q04_M05_09_BasicTrig.png","finalAnswer":"$(a)\\ \\angle DAB=138.19^\\circ.\\quad (b)\\ BD=15.0\\text{ cm}$.","steps":[{"title":"Use the area of a parallelogram","body":"Area $=ab\\sin\\theta$, so $40=10\\cdot6\\sin\\theta$. Hence $\\sin\\theta=\\frac23$."},{"title":"Choose the obtuse angle","body":"$\\theta=180^\\circ-\\sin^{-1}\\left(\\frac23\\right)=138.19^\\circ$ to 2 decimal places."},{"title":"Use the cosine rule for BD","body":"$BD^2=10^2+6^2-2(10)(6)\\cos(138.19^\\circ)$. Therefore $BD\\approx15.014\\ldots$, so $BD=15.0\\text{ cm}$ to 1 decimal place."}]},{"id":"WMA11-01_2021_MayJune_Q03","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":3,"marks":9,"topic":"09_BasicTrig","topicName":"Basic Trigonometry","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q03_M09_09_BasicTrig.png","downloadName":"WMA11-01_Y2021_MayJune_Q03_M09_09_BasicTrig.png","finalAnswer":"$(a)\\ p^2+q^2-pq=8.\\quad (b)\\ p=\\sqrt5-1,\\ q=\\sqrt5+1.\\quad (c)\\ \\sqrt3\\text{ m}^2$.","steps":[{"title":"Apply the cosine rule","body":"$BC^2=AB^2+AC^2-2(AB)(AC)\\cos60^\\circ$. Since $BC=2\\sqrt2$, $AB=p$ and $AC=q$, this gives $8=p^2+q^2-2pq\\left(\\dfrac12\\right)$."},{"title":"Show the required result","body":"Therefore $p^2+q^2-pq=8$."},{"title":"Use q = p + 2","body":"Side $AC$ is 2 metres longer than $AB$, so $q=p+2$. Substitute into $p^2+q^2-pq=8$."},{"title":"Solve for p","body":"$p^2+(p+2)^2-p(p+2)=8$, so $p^2+2p-4=0$. Hence $p=-1\\pm\\sqrt5$. Since $p>0$, $p=\\sqrt5-1$."},{"title":"Find q","body":"$q=p+2=\\sqrt5+1$."},{"title":"Find the exact area","body":"Area $=\\dfrac12pq\\sin60^\\circ$. Now $pq=(\\sqrt5-1)(\\sqrt5+1)=4$, so area $=\\dfrac12(4)\\left(\\dfrac{\\sqrt3}{2}\\right)=\\sqrt3\\text{ m}^2$."}]},{"id":"WMA11-01_2022_MayJune_Q02","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":2,"marks":5,"topic":"09_BasicTrig","topicName":"Basic Trigonometry","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q02_M05_09_BasicTrig.png","downloadName":"WMA11-01_Y2022_MayJune_Q02_M05_09_BasicTrig.png","finalAnswer":"$x=137^\\circ$ to 3 significant figures.","steps":[{"title":"Use the sine rule","body":"The side opposite $x$ is $AB=21$, and the side opposite $25^\\circ$ is $BC=13$, so $\\dfrac{\\sin x}{21}=\\dfrac{\\sin25^\\circ}{13}$."},{"title":"Find the sine value","body":"$\\sin x=\\dfrac{21\\sin25^\\circ}{13}=0.68269\\ldots$."},{"title":"Choose the correct angle","body":"The angle from the calculator is $43.05^\\circ$, but $AB$ is the longest side, so $x$ is obtuse. Hence $x=180^\\circ-43.05^\\circ=136.95^\\circ$."}]},{"id":"WMA11-01_2023_Oct_Q05","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":5,"marks":7,"topic":"09_BasicTrig","topicName":"Basic Trigonometry","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q05_M07_09_BasicTrig.png","downloadName":"WMA11-01_Y2023_Oct_Q05_M07_09_BasicTrig.png","finalAnswer":"$(a)\\ \\cos\\theta=\\dfrac{13+x}{5+5x}.\\quad (b)\\ \\text{Area}=32.2\\text{ m}^2$.","steps":[{"title":"Apply the cosine rule in triangle BCD","body":"$x^2=5^2+(1+x)^2-2(5)(1+x)\\cos\\theta$."},{"title":"Rearrange for cos theta","body":"$10(1+x)\\cos\\theta=25+(1+x)^2-x^2=26+2x$, so $\\cos\\theta=\\dfrac{26+2x}{10(1+x)}=\\dfrac{13+x}{5+5x}$."},{"title":"Substitute x equals 2 root 3","body":"$\\cos C=\\dfrac{13+2\\sqrt3}{5+10\\sqrt3}$, so $C\\approx42.47^\\circ$."},{"title":"Use angle sum","body":"$A=30^\\circ$, so $B=180^\\circ-30^\\circ-C\\approx107.53^\\circ$."},{"title":"Use the sine rule for the area","body":"Since $BC=5$ and $A=30^\\circ$, $\\dfrac{BC}{\\sin A}=10$. Hence $AB=10\\sin C$ and $AC=10\\sin B$."},{"title":"Calculate the area","body":"$\\text{Area}=\\dfrac12(AB)(AC)\\sin A=50\\sin C\\sin B\\approx32.2\\text{ m}^2$."}]},{"id":"WMA11-01_2024_Jan_Q02","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":2,"marks":5,"topic":"09_BasicTrig","topicName":"Basic Trigonometry","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q02_M05_09_BasicTrig.png","downloadName":"WMA11-01_Y2024_Jan_Q02_M05_09_BasicTrig.png","finalAnswer":"$(a)\\ \\sin\\theta=\\dfrac{8}{15}.\\quad (b)\\ BC=38.5\\text{ cm}$.","steps":[{"title":"Use the triangle area formula","body":"$100=\\dfrac12(15)(25)\\sin\\theta$."},{"title":"Find sine theta","body":"$\\sin\\theta=\\dfrac{200}{375}=\\dfrac{8}{15}$."},{"title":"Use theta greater than 90 degrees","body":"Since $\\theta>90^\\circ$, $\\cos\\theta$ is negative. So $\\cos\\theta=-\\sqrt{1-\\left(\\dfrac{8}{15}\\right)^2}=-\\dfrac{\\sqrt{161}}{15}$."},{"title":"Apply the cosine rule","body":"$BC^2=15^2+25^2-2(15)(25)\\cos\\theta=850+50\\sqrt{161}$."},{"title":"Round the length","body":"$BC=\\sqrt{850+50\\sqrt{161}}\\approx38.5\\text{ cm}$ to 3 significant figures."}]},{"id":"WMA11-01_2025_Oct_Q03","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":3,"marks":5,"topic":"09_BasicTrig","topicName":"Basic Trigonometry","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q03_M05_09_BasicTrig.png","downloadName":"WMA11-01_Y2025_Oct_Q03_M05_09_BasicTrig.png","finalAnswer":"$(a)\\ 108.2^\\circ.\\quad (b)\\ 12.1\\text{ cm}$.","steps":[{"title":"Use the side ratio","body":"Take the side lengths as $2x$, $4x$ and $5x$. The largest angle is opposite the side $5x$."},{"title":"Use the cosine rule","body":"$(5x)^2=(2x)^2+(4x)^2-2(2x)(4x)\\cos\\theta$."},{"title":"Find the angle","body":"$25=4+16-16\\cos\\theta$, so $\\cos\\theta=-\\dfrac5{16}$ and $\\theta=108.2^\\circ$ to one decimal place."},{"title":"Use the area formula","body":"$140=\\dfrac12(2x)(4x)\\sin108.2^\\circ=4x^2\\sin108.2^\\circ$."},{"title":"Find the scale factor","body":"$x^2=\\dfrac{140}{4\\sin108.2^\\circ}$, so $x\\approx6.070$."},{"title":"Shortest side","body":"The shortest side is $2x\\approx12.1\\text{ cm}$."}]},{"id":"WMA11-01_2019_Oct_Q01","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":1,"marks":5,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q01_M05_10_Radians.png","downloadName":"WMA11-01_Y2019_Oct_Q01_M05_10_Radians.png","finalAnswer":"$(a)\\ r=2\\sqrt6\\text{ cm}.\\quad (b)\\ \\dfrac{13\\sqrt6}{2}\\text{ cm}.$","steps":[{"title":"Use the sector area formula","body":"For a sector, $A=\\frac12 r^2\\theta$. Here $A=15$ and $\\theta=1.25=\\frac54$, so $15=\\frac12 r^2\\cdot\\frac54$."},{"title":"Find the exact radius","body":"$r^2=\\dfrac{30}{5/4}=24$, so $r=\\sqrt{24}=2\\sqrt6$ because the radius is positive."},{"title":"Find the perimeter","body":"Arc length is $s=r\\theta=(2\\sqrt6)\\left(\\frac54\\right)=\\frac{5\\sqrt6}{2}$. The perimeter is $2r+s=4\\sqrt6+\\frac{5\\sqrt6}{2}=\\frac{13\\sqrt6}{2}$."}]},{"id":"WMA11-01_2020_Jan_Q04","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":4,"marks":9,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q04_M09_10_Radians.png","downloadName":"WMA11-01_Y2020_Jan_Q04_M09_10_Radians.png","finalAnswer":"$(a)\\ \\angle AOD=1.231\\text{ rad}.\\quad (b)\\ 292.2\\text{ m}^2.\\quad (c)\\ 79.8\\text{ m}$.","steps":[{"title":"Find angle AOD","body":"Since $OC=12$ and $DC=AB=16$, $OD=4$. In right triangle $AOD$, $\\cos\\angle AOD=\\dfrac{OD}{OA}=\\dfrac4{12}=\\dfrac13$. Hence $\\angle AOD=\\cos^{-1}\\left(\\dfrac13\\right)=1.231$ radians to 3 d.p."},{"title":"Identify the major sector used for the lawn","body":"The shaded lawn uses the major sector from $A$ to $C$, so its angle is $\\pi+1.231$ radians."},{"title":"Subtract the unshaded triangle","body":"$AD=\\sqrt{12^2-4^2}=8\\sqrt2$. Area of major sector $=\\frac12(12)^2(\\pi+1.231)$. Area of triangle $AOD=\\frac12(4)(8\\sqrt2)$."},{"title":"Find the lawn area","body":"Area $=\\frac12(12)^2(\\pi+1.231)-\\frac12(4)(8\\sqrt2)=292.2\\text{ m}^2$ to 1 d.p."},{"title":"Find the lawn perimeter","body":"Perimeter $=\\text{major arc}+CD+AD=12(\\pi+1.231)+16+8\\sqrt2=79.8\\text{ m}$ to 1 d.p."}]},{"id":"WMA11-01_2021_Jan_Q05","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":5,"marks":9,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q05_M09_10_Radians.png","downloadName":"WMA11-01_Y2021_Jan_Q05_M09_10_Radians.png","finalAnswer":"$(a)\\ 1.805\\text{ rad}.\\quad (b)\\ 26.9\\text{ m}.\\quad (c)\\ 113.7\\text{ m}^2$.","steps":[{"title":"Use the sine rule in triangle AOD","body":"Since $O,C,D$ are in a straight line, $\\angle ADO=0.43$. By the sine rule, $\\dfrac{14}{\\sin\\angle AOD}=\\dfrac{6}{\\sin0.43}$, so $\\sin\\angle AOD=\\dfrac{14\\sin0.43}{6}$."},{"title":"Choose the obtuse angle","body":"The calculator gives the acute value $1.337\\ldots$, but $\\angle AOD$ is obtuse. Hence $\\angle AOD=\\pi-1.337\\ldots=1.805\\ldots$, so $\\angle AOD=1.805$ radians."},{"title":"Find the major-sector angle","body":"Arc $ABC$ is the major arc, so its angle is $2\\pi-1.805\\ldots=4.478\\ldots$ radians."},{"title":"Find the arc length","body":"$s=r\\theta=6(4.478\\ldots)=26.868\\ldots$, so the length of arc $ABC$ is $26.9$ m."},{"title":"Find the sector area","body":"The sector area is $\\dfrac12r^2\\theta=\\dfrac12(6)^2(4.478\\ldots)=80.607\\ldots$."},{"title":"Find the triangle area and total area","body":"$\\angle OAD=\\pi-0.43-1.805\\ldots=0.9066\\ldots$. The triangle area is $\\dfrac12(6)(14)\\sin(0.9066\\ldots)=33.093\\ldots$. Total area $=80.607\\ldots+33.093\\ldots=113.7\\text{ m}^2$."}]},{"id":"WMA11-01_2021_MayJune_Q07","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":7,"marks":10,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q07_M10_10_Radians.png","downloadName":"WMA11-01_Y2021_MayJune_Q07_M10_10_Radians.png","finalAnswer":"$(a)\\ 12.\\quad (b)\\ E_y=-\\dfrac{14}{3}.\\quad (c)\\ 30.\\quad (d)\\ \\dfrac{950}{3}$.","steps":[{"title":"Find C","body":"On the y-axis, $x=0$. From $4y+3x=48$, $4y=48$, so the y-coordinate of $C$ is $12$."},{"title":"Find the gradient of l1","body":"$4y+3x=48$ gives $y=-\\dfrac34x+12$, so the gradient of $l_1$ is $-\\dfrac34$."},{"title":"Use perpendicular gradients for l2","body":"Since $l_2$ is perpendicular to $l_1$, its gradient is $\\dfrac43$. Through $D(8,6)$, $y-6=\\dfrac43(x-8)$."},{"title":"Show the y-coordinate of E","body":"$y=\\dfrac43x-\\dfrac{32}{3}+6=\\dfrac43x-\\dfrac{14}{3}$. Therefore when $x=0$, $E_y=-\\dfrac{14}{3}$."},{"title":"Find the radius of the sector","body":"$C=(0,12)$ and $E=\\left(0,-\\dfrac{14}{3}\\right)$, so $CE=12+\\dfrac{14}{3}=\\dfrac{50}{3}$."},{"title":"Find arc BE","body":"For sector $BCE$, $r=\\dfrac{50}{3}$ and $\\theta=1.8=\\dfrac95$. Hence arc $BE=r\\theta=\\dfrac{50}{3}\\cdot\\dfrac95=30$."},{"title":"Find the sector area","body":"Sector area $=\\dfrac12r^2\\theta=\\dfrac12\\left(\\dfrac{50}{3}\\right)^2\\left(\\dfrac95\\right)=250$."},{"title":"Find the triangle area and total area","body":"Triangle $CDE$ has vertical base $CE=\\dfrac{50}{3}$ and horizontal height $8$, so its area is $\\dfrac12\\cdot\\dfrac{50}{3}\\cdot8=\\dfrac{200}{3}$. Total area $=250+\\dfrac{200}{3}=\\dfrac{950}{3}$."}]},{"id":"WMA11-01_2021_Oct_Q07","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":7,"marks":10,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q07_M10_10_Radians.png","downloadName":"WMA11-01_Y2021_Oct_Q07_M10_10_Radians.png","finalAnswer":"$(a)\\ \\theta=1.64\\text{ rad}.\\quad (b)\\ 5.6\\text{ m}.\\quad (c)\\ 1.6\\text{ m}^2$.","steps":[{"title":"Work in triangle OAB","body":"In triangle $OAB$, $OA=0.6$, $AB=1.4$, and $\\angle OAB=2$ radians."},{"title":"Find OB","body":"By the cosine rule, $OB^2=0.6^2+1.4^2-2(0.6)(1.4)\\cos2$, so $OB=1.73756\\ldots$."},{"title":"Find half of theta","body":"Using the cosine rule again, $\\cos\\angle AOB=\\dfrac{0.6^2+OB^2-1.4^2}{2(0.6)(OB)}$, giving $\\angle AOB=0.822199\\ldots$ radians."},{"title":"Use symmetry of the kite","body":"The kite is symmetric, so $\\theta=2\\angle AOB=1.644398\\ldots$, hence $\\theta=1.64$ radians to 3 significant figures."},{"title":"Find the outside arc length","body":"The sector $OCXA$ uses the major angle $2\\pi-\\theta$. Its arc length is $0.6(2\\pi-1.644398\\ldots)=2.78327\\ldots$."},{"title":"Find the perimeter","body":"Perimeter $=AB+CB+\\text{major arc}=1.4+1.4+2.78327\\ldots=5.58327\\ldots$, so the perimeter is $5.6$ m."},{"title":"Find the kite area","body":"The kite consists of two congruent triangles like $OAB$, so area of kite $=2\\left(\\dfrac12(0.6)(1.4)\\sin2\\right)=0.76381\\ldots$."},{"title":"Find the sector area and total area","body":"Major sector area $=\\dfrac12(0.6)^2(2\\pi-1.644398\\ldots)=0.83498\\ldots$. Total area $=0.76381\\ldots+0.83498\\ldots=1.59879\\ldots$, so the area is $1.6\\text{ m}^2$."}]},{"id":"WMA11-01_2022_Jan_Q05","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":5,"marks":7,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q05_M07_10_Radians.png","downloadName":"WMA11-01_Y2022_Jan_Q05_M07_10_Radians.png","finalAnswer":"$(a)\\ \\angle BOD=1.742\\text{ rad}.\\quad (b)\\ 3.4\\text{ m}^2.\\quad (c)\\ 9.8\\text{ m}$.","steps":[{"title":"Find angle BOD","body":"Since $BD$ is parallel to the diameter $AE$, the two side angles at the centre are both $0.7$ radians. Therefore $\\angle BOD=\\pi-0.7-0.7=\\pi-1.4=1.74159\\ldots$, so $1.742$ radians to 4 significant figures."},{"title":"Find the sector area","body":"With $r=3$ and $\\theta=1.74159\\ldots$, sector area $=\\dfrac12r^2\\theta=\\dfrac12(3)^2(1.74159\\ldots)=7.837\\ldots$."},{"title":"Subtract triangle BOD","body":"Triangle area $=\\dfrac12(3)(3)\\sin(1.74159\\ldots)=4.434\\ldots$. The segment area is $7.837\\ldots-4.434\\ldots=3.403\\ldots$, so $3.4\\text{ m}^2$."},{"title":"Find the arc length","body":"Arc $BCD=r\\theta=3(1.74159\\ldots)=5.225\\ldots$."},{"title":"Find the chord and perimeter","body":"$BD=2r\\sin\\dfrac{\\theta}{2}=6\\sin(0.87079\\ldots)=4.590\\ldots$. Perimeter $=5.225\\ldots+4.590\\ldots=9.8\\text{ m}$."}]},{"id":"WMA11-01_2022_MayJune_Q08","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":8,"marks":10,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q08_M10_10_Radians.png","downloadName":"WMA11-01_Y2022_MayJune_Q08_M10_10_Radians.png","finalAnswer":"$(a)\\ CD=35.9\\text{ cm}.\\quad (b)\\ 603\\text{ cm}.\\quad (c)\\ 4.73\\times10^3\\text{ cm}^2$.","steps":[{"title":"Find the small sector angle","body":"For arc $AB$, $s=r\\theta$, so $15=9\\theta$ and $\\theta=\\dfrac53$ radians."},{"title":"Find the outer arc angle","body":"Each identical section has total angle $\\dfrac{2\\pi}{3}$, so the angle for arc $CD$ is $\\dfrac{2\\pi}{3}-\\dfrac53=\\dfrac{2\\pi-5}{3}$."},{"title":"Find CD","body":"$CD=84\\left(\\dfrac{2\\pi-5}{3}\\right)=28(2\\pi-5)=35.9\\text{ cm}$ to 3 significant figures."},{"title":"Find the perimeter","body":"There are 3 inner arcs, 3 outer arcs, and 6 straight radial edges of length $84-9=75$. Thus $P=3(15)+3(35.929\\ldots)+6(75)=602.8\\ldots\\text{ cm}$."},{"title":"Find the area of one section","body":"One section has area $\\dfrac12(9^2)\\left(\\dfrac53\\right)+\\dfrac12(84^2)\\left(\\dfrac{2\\pi-5}{3}\\right)=1576.525\\ldots\\text{ cm}^2$."},{"title":"Find the total area","body":"The total area is $3(1576.525\\ldots)=4729.57\\ldots\\text{ cm}^2=4.73\\times10^3\\text{ cm}^2$ to 3 significant figures."}]},{"id":"WMA11-01_2022_Oct_Q08","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":8,"marks":14,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q08_M14_10_Radians.png","downloadName":"WMA11-01_Y2022_Oct_Q08_M14_10_Radians.png","finalAnswer":"$(a)(i)\\ 6\\pi\\text{ m}^2,\\ (ii)\\ 4\\pi+6\\text{ m}.\\quad (b)\\ \\dfrac{9\\sqrt3}{4}\\text{ m}^2.\\quad (c)\\ AB=3\\sqrt3\\text{ m}.\\quad (d)\\ 43\\text{ m}^2$.","steps":[{"title":"Find the angle of the sector AOBX","body":"The sector AOBX is the major sector, so its angle is $2\\pi-\\dfrac{2\\pi}{3}=\\dfrac{4\\pi}{3}$."},{"title":"Find the sector area","body":"$\\text{Area}=\\dfrac12r^2\\theta=\\dfrac12(3^2)\\left(\\dfrac{4\\pi}{3}\\right)=6\\pi\\text{ m}^2$."},{"title":"Find the sector perimeter","body":"The arc length is $r\\theta=3\\left(\\dfrac{4\\pi}{3}\\right)=4\\pi$. Adding the two radii gives $4\\pi+6\\text{ m}$."},{"title":"Find the area of triangle AOB","body":"$\\text{Area}=\\dfrac12(3)(3)\\sin\\left(\\dfrac{2\\pi}{3}\\right)=\\dfrac92\\cdot\\dfrac{\\sqrt3}{2}=\\dfrac{9\\sqrt3}{4}\\text{ m}^2$."},{"title":"Show AB","body":"By the cosine rule, $AB^2=3^2+3^2-2(3)(3)\\cos\\left(\\dfrac{2\\pi}{3}\\right)=18+9=27$, so $AB=3\\sqrt3$."},{"title":"Find AC","body":"In triangle ABC, $AB^2=AC^2+8^2-2(AC)(8)\\cos\\left(\\dfrac{\\pi}{6}\\right)$, so $27=AC^2-8\\sqrt3\\,AC+64$."},{"title":"Choose the correct length","body":"Solving gives $AC=4\\sqrt3\\pm\\sqrt{11}$. From the diagram, $AC$ is the longer value, so $AC=4\\sqrt3+\\sqrt{11}$."},{"title":"Find the total area","body":"Area of triangle ABC is $\\dfrac12(8)(AC)\\sin\\left(\\dfrac\\pi6\\right)=2AC=8\\sqrt3+2\\sqrt{11}$. Total area is $6\\pi+\\dfrac{9\\sqrt3}{4}+8\\sqrt3+2\\sqrt{11}=43.236\\ldots$, so $43\\text{ m}^2$ to 2 significant figures."}]},{"id":"WMA11-01_2023_Jan_Q06","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":6,"marks":10,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q06_M10_10_Radians.png","downloadName":"WMA11-01_Y2023_Jan_Q06_M10_10_Radians.png","finalAnswer":"$(a)\\ r=5.77\\text{ m}.\\quad (b)\\ 0.37\\text{ rad}.\\quad (c)\\ 53.1\\text{ m}^2.\\quad (d)\\ 30.9\\text{ m}$.","steps":[{"title":"Find the radius","body":"Area of sector $BOC$ is $\\dfrac12r^2\\theta$. So $40=\\dfrac12r^2(2.4)=1.2r^2$, giving $r=\\sqrt{\\dfrac{40}{1.2}}=5.77$ m."},{"title":"Find angle AOB","body":"The triangles $OAB$ and $ODC$ are congruent, so $\\angle AOB=\\angle COD$. Since $AOD$ is a straight line, $2\\angle AOB+2.4=\\pi$."},{"title":"Calculate the angle","body":"$\\angle AOB=\\dfrac{\\pi-2.4}{2}=0.3708\\ldots$, so $0.37$ rad."},{"title":"Find the total area","body":"The two congruent triangle areas together are $2\\left(\\dfrac12(6.25)(5.7735\\ldots)\\sin0.3708\\ldots\\right)=13.075\\ldots$."},{"title":"Add the sector area","body":"Total area $=40+13.075\\ldots=53.1\\text{ m}^2$ to one decimal place."},{"title":"Find AB","body":"Using the cosine rule, $AB^2=6.25^2+r^2-2(6.25)(r)\\cos0.3708\\ldots$, giving $AB=2.265\\ldots$ m."},{"title":"Find the perimeter","body":"Perimeter $=AD+AB+CD+\\text{arc }BC=12.5+2(2.265\\ldots)+5.7735\\ldots(2.4)=30.9$ m."}]},{"id":"WMA11-01_2023_MayJune_Q05","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":5,"marks":10,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q05_M10_10_Radians.png","downloadName":"WMA11-01_Y2023_MayJune_Q05_M10_10_Radians.png","finalAnswer":"$(a)\\ \\angle AOB=1.186\\text{ rad}.\\quad (b)\\ 18.5\\text{ m}.\\quad (c)\\ 15.7\\text{ m}^2$.","steps":[{"title":"Find the angle AOB","body":"Since $OB=4$ and the height of $B$ is $1.5$, $\\cos\\angle AOB=\\dfrac{1.5}{4}=0.375$."},{"title":"Calculate the angle","body":"$\\angle AOB=\\cos^{-1}(0.375)=1.186\\ldots$ rad, which is $1.186$ rad to 4 significant figures."},{"title":"Find BC","body":"The horizontal coordinate of $B$ is $4\\sin(1.186\\ldots)=3.708\\ldots$, so $BC=6-3.708\\ldots=2.2919\\ldots$ m."},{"title":"Find the arc length","body":"Arc $AB=r\\theta=4(1.186\\ldots)=4.7456\\ldots$ m."},{"title":"Find the perimeter","body":"Perimeter $=OA+\\text{arc }AB+BC+CD+OD=4+4.7456\\ldots+2.2919\\ldots+1.5+6=18.537\\ldots$ m."},{"title":"Find the area","body":"Area of sector $AOB=\\dfrac12(4^2)(1.186\\ldots)=9.491\\ldots$."},{"title":"Add the quadrilateral area","body":"Area of $OBCD$ is the trapezium area $\\dfrac12(6+2.2919\\ldots)(1.5)=6.2189\\ldots$. Total area $=15.710\\ldots=15.7\\text{ m}^2$."}]},{"id":"WMA11-01_2023_Oct_Q09","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":9,"marks":7,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q09_M07_10_Radians.png","downloadName":"WMA11-01_Y2023_Oct_Q09_M07_10_Radians.png","finalAnswer":"$(a)\\ OP=1.2\\text{ m}.\\quad (b)\\ 5x^2+12x-1500=0.\\quad (c)\\ 43\\text{ m}$.","steps":[{"title":"Use arc length","body":"$s=r\\theta$, so $0.72=OP\\times0.6$. Hence $OP=1.2\\text{ m}$."},{"title":"Set up the target area","body":"The outer sector has radius $x+1.2$ and the inner sector has radius $1.2$, with angle $0.6$ radians."},{"title":"Use sector area","body":"$\\dfrac12(x+1.2)^2(0.6)-\\dfrac12(1.2)^2(0.6)=90$."},{"title":"Simplify to the given quadratic","body":"$0.3\\left((x+1.2)^2-1.44\\right)=90$, so $0.3x^2+0.72x-90=0$. Multiplying by $\\dfrac{50}{3}$ gives $5x^2+12x-1500=0$."},{"title":"Find the positive value of x","body":"$x=\\dfrac{-12+\\sqrt{12^2+4(5)(1500)}}{10}=\\dfrac{-6+4\\sqrt{471}}{5}\\approx16.16$."},{"title":"Find the perimeter","body":"$\\text{Perimeter}=PQ+SR+\\text{arc }QR+\\text{arc }PS=x+x+0.6(x+1.2)+0.72\\approx43.46\\text{ m}$."},{"title":"Round to the nearest metre","body":"The total perimeter is $43\\text{ m}$ to the nearest metre."}]},{"id":"WMA11-01_2024_Jan_Q08","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":8,"marks":9,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q08_M09_10_Radians.png","downloadName":"WMA11-01_Y2024_Jan_Q08_M09_10_Radians.png","finalAnswer":"$(a)\\ AO=7.03\\text{ m}.\\quad (b)\\ 56.0\\text{ m}.\\quad (c)\\ 186\\text{ m}^2$.","steps":[{"title":"Find the outer radius","body":"For sector $DOC$, arc length $CD=9$ and angle $0.8$ radians, so $OD=\\dfrac9{0.8}=11.25\\text{ m}$."},{"title":"Use the ratio DA to AO","body":"$DA:AO=3:5$, so $OD=DA+AO$ represents $8$ parts. Hence $AO=\\dfrac58(11.25)=7.03125\\text{ m}\\approx7.03\\text{ m}$."},{"title":"Find the straight side lengths","body":"$DA=CB=OD-AO=11.25-7.03125=4.21875\\text{ m}$."},{"title":"Find the major arc","body":"The major sector $AOBEA$ has angle $2\\pi-0.8$, so arc $AEB=7.03125(2\\pi-0.8)$."},{"title":"Calculate the perimeter","body":"$\\text{Perimeter}=9+2(4.21875)+7.03125(2\\pi-0.8)\\approx56.0\\text{ m}$."},{"title":"Calculate the total area","body":"$\\text{Area}=\\dfrac12(11.25)^2(0.8)+\\dfrac12(7.03125)^2(2\\pi-0.8)\\approx186\\text{ m}^2$ to the nearest whole number."}]},{"id":"WMA11-01_2024_MayJune_Q05","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":5,"marks":7,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q05_M07_10_Radians.png","downloadName":"WMA11-01_Y2024_MayJune_Q05_M07_10_Radians.png","finalAnswer":"$(a)\\ 23.4\\text{ m}^2.\\quad (b)\\ 1.54\\text{ radians}.\\quad (c)\\ 60.9\\text{ m}^2$.","steps":[{"title":"Find the sector area","body":"$\\text{Area of sector }BDE=\\dfrac12(6^2)(1.3)=23.4\\text{ m}^2$."},{"title":"Use the cosine rule in triangle ABE","body":"$12.2^2=10.8^2+6^2-2(10.8)(6)\\cos\\angle ABE$."},{"title":"Find angle ABE","body":"$\\cos\\angle ABE=\\dfrac{10.8^2+6^2-12.2^2}{2(10.8)(6)}$, so $\\angle ABE\\approx1.54$ radians."},{"title":"Find the area of triangle ABE","body":"$\\text{Area }ABE=\\dfrac12(10.8)(6)\\sin(1.54147...)\\approx32.386$."},{"title":"Find angle DBC","body":"$\\angle DBC=\\pi-1.3-\\angle ABE\\approx0.30012$ radians."},{"title":"Find the area of triangle BCD","body":"$\\text{Area }BCD=\\dfrac12(6\\cos\\angle DBC)(6\\sin\\angle DBC)\\approx5.084$."},{"title":"Add the three areas","body":"$23.4+32.386+5.084\\approx60.9\\text{ m}^2$ to 3 significant figures."}]},{"id":"WMA11-01_2024_Oct_Q05","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":5,"marks":9,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q05_M09_10_Radians.png","downloadName":"WMA11-01_Y2024_Oct_Q05_M09_10_Radians.png","finalAnswer":"$(a)\\ 16\\text{ km}.\\quad (b)\\ 3.75\\text{ km}^2.\\quad (c)\\ AP=4.7\\text{ km}$.","steps":[{"title":"Find the arc length","body":"$\\text{arc }AB=r\\theta=5(1.2)=6\\text{ km}$."},{"title":"Find the perimeter","body":"$OA+OB+\\text{arc }AB=5+5+6=16\\text{ km}$."},{"title":"Find the total sector area","body":"$\\text{Area of }OAB=\\dfrac12(5^2)(1.2)=15\\text{ km}^2$."},{"title":"Use the area ratio","body":"Since $\\text{area }R_1=3\\times\\text{area }R_2$, the total area is $4\\times\\text{area }R_2$."},{"title":"Find area R2","body":"$\\text{area }R_2=\\dfrac{15}{4}=3.75\\text{ km}^2$."},{"title":"Find OP from triangle OAP","body":"$\\dfrac12(5)(OP)\\sin1.2=3.75$, so $OP\\approx1.609$ km."},{"title":"Use the cosine rule","body":"$AP^2=5^2+OP^2-2(5)(OP)\\cos1.2$, so $AP\\approx4.665$ km."},{"title":"Round to the nearest 100 m","body":"$AP=4.7\\text{ km}$ to the nearest $0.1$ km."}]},{"id":"WMA11-01_2025_Jan_Q08","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":8,"marks":13,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q08_M13_10_Radians.png","downloadName":"WMA11-01_Y2025_Jan_Q08_M13_10_Radians.png","finalAnswer":"$(a)\\ \\angle OAB=2.034\\text{ radians}.\\quad (b)\\ 1.78\\text{ cm}^2.\\quad (c)\\ \\angle BOC=0.462\\text{ radians}.\\quad (d)\\ 9\\text{ cm}$.","steps":[{"title":"Use the sine rule","body":"In triangle $OAB$, $AB=1.9$, $OB=3.4$ and $\\angle AOB=\\dfrac\\pi6$."},{"title":"Find sine of angle OAB","body":"$\\dfrac{\\sin\\angle OAB}{3.4}=\\dfrac{\\sin(\\pi/6)}{1.9}$, so $\\sin\\angle OAB=\\dfrac{17}{19}$."},{"title":"Choose the obtuse angle","body":"Since $\\angle OAB>\\dfrac\\pi2$, $\\angle OAB=\\pi-\\sin^{-1}\\left(\\dfrac{17}{19}\\right)\\approx2.034$ radians."},{"title":"Find OA","body":"Using the sine rule again, $OA\\approx2.096$ cm."},{"title":"Find the triangle area","body":"$\\text{Area }OAB=\\dfrac12(OA)(OB)\\sin(\\pi/6)\\approx1.78\\text{ cm}^2$."},{"title":"Use the area ratio","body":"$\\text{Area sector }OBC:\\text{Area triangle }OAB=3:2$, so sector area $=\\dfrac32(1.78156...)$."},{"title":"Find angle BOC","body":"$\\dfrac12(3.4)^2\\theta=\\dfrac32(1.78156...)$, so $\\theta\\approx0.462$ radians."},{"title":"Find the perimeter","body":"The perimeter is $OA+AB+OC+\\text{arc }BC=2.096+1.9+3.4+3.4(0.46234...)\\approx8.968$ cm."},{"title":"Round","body":"The perimeter is $9$ cm to the nearest integer."}]},{"id":"WMA11-01_2025_MayJune_Q06","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":6,"marks":9,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q06_M09_10_Radians.png","downloadName":"WMA11-01_Y2025_MayJune_Q06_M09_10_Radians.png","finalAnswer":"$(a)\\ \\angle COA=1.847\\text{ rad}.\\quad (b)\\ 622\\text{ m}^2.\\quad (c)\\ 94.1\\text{ m}$.","steps":[{"title":"Set up triangle AOC","body":"$AO=15$, $OC=OB+BC=17$, and $\\angle ACO=0.6$."},{"title":"Use the sine rule","body":"$\\dfrac{\\sin\\angle CAO}{17}=\\dfrac{\\sin0.6}{15}$, so $\\angle CAO\\approx0.6944$ radians."},{"title":"Show angle COA","body":"$\\angle COA=\\pi-0.6-0.6944...=1.847...$, so $\\angle COA=1.847$ radians to 3 decimal places."},{"title":"Major sector angle","body":"The shaded sector is the major sector $AOB$, so its angle is $2\\pi-1.847...$."},{"title":"Sector area","body":"$\\text{Sector area}=\\dfrac12(15)^2(2\\pi-1.847...)=499.15...$."},{"title":"Triangle area","body":"$\\text{Area }AOC=\\dfrac12(15)(17)\\sin(1.847...)=122.73...$."},{"title":"Total area","body":"$499.15...+122.73...=621.88...$, so the total area is $622\\text{ m}^2$ to 3 significant figures."},{"title":"Find AC","body":"By the cosine rule, $AC^2=15^2+17^2-2(15)(17)\\cos(1.847...)$, so $AC\\approx27.57$ m."},{"title":"Major arc length","body":"$\\text{arc }AB=15(2\\pi-1.847...)=66.54...$ m."},{"title":"Perimeter","body":"$66.54...+27.57...=94.11...$, so the perimeter is $94.1\\text{ m}$."}]},{"id":"WMA11-01_2025_Oct_Q07","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":7,"marks":9,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q07_M09_10_Radians.png","downloadName":"WMA11-01_Y2025_Oct_Q07_M09_10_Radians.png","finalAnswer":"$(a)\\ OQ=8.83\\text{ m}.\\quad (b)\\ 211\\text{ m}^2.\\quad (c)\\ 56\\text{ m}$.","steps":[{"title":"Find OP from the small sector","body":"Let $OP=r$. The area of sector $POS$ is $30$, so $\\dfrac12r^2(1.65)=30$."},{"title":"Calculate OP","body":"$r^2=\\dfrac{60}{1.65}$, so $r=6.030...$ m."},{"title":"Show OQ","body":"$OQ=OP+PQ=6.030...+2.8=8.830...$, so $OQ=8.83$ m to 3 significant figures."},{"title":"Major sector angle","body":"The major sector $QORTQ$ has angle $2\\pi-1.65$ radians."},{"title":"Total area","body":"$\\text{Area}=30+\\dfrac12(8.830...)^2(2\\pi-1.65)=210.6...$."},{"title":"Round area","body":"The total surface area is $211\\text{ m}^2$ to the nearest integer."},{"title":"Arc lengths","body":"The inner arc $PS$ has length $6.030...(1.65)=9.95...$, and the outer major arc has length $8.830...(2\\pi-1.65)=40.91...$."},{"title":"Add straight sides","body":"The straight sides $PQ$ and $SR$ each have length $2.8$ m."},{"title":"Perimeter","body":"$9.95...+40.91...+2.8+2.8=56.46...$, so the perimeter is $56\\text{ m}$ to 2 significant figures."}]},{"id":"WMA11-01_2026_Jan_Q05","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":5,"marks":9,"topic":"10_Radians","topicName":"Radians","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q05_M09_10_Radians.png","downloadName":"WMA11-01_Y2026_Jan_Q05_M09_10_Radians.png","finalAnswer":"$(a)\\ \\angle ODA=0.415\\text{ rad}.\\quad (b)\\ 21.9\\text{ cm}^2.\\quad (c)\\ 21.7\\text{ cm}$.","steps":[{"title":"Use triangle AOD","body":"In triangle $AOD$, $OD=3$, $AD=8$ and $\\angle AOD=2.5$ radians."},{"title":"Use the sine rule","body":"$\\dfrac{\\sin\\angle OAD}{3}=\\dfrac{\\sin2.5}{8}$, so $\\angle OAD=\\sin^{-1}\\left(\\dfrac{3\\sin2.5}{8}\\right)=0.2263...$."},{"title":"Show angle ODA","body":"$\\angle ODA=\\pi-2.5-0.2263...=0.4152...$, so $\\angle ODA=0.415$ radians to 3 significant figures."},{"title":"Area of the major sector","body":"The sector has radius $3$ and angle $2\\pi-2.5$, so its area is $\\dfrac12(3)^2(2\\pi-2.5)=17.02...$."},{"title":"Area of triangle AOD","body":"$\\text{Area of triangle }AOD=\\dfrac12(3)(8)\\sin0.4152...=4.84...$."},{"title":"Total area","body":"$17.02...+4.84...=21.86...$, so the area is $21.9\\text{ cm}^2$ to one decimal place."},{"title":"Find AO","body":"By the cosine rule, $AO^2=3^2+8^2-2(3)(8)\\cos0.4152...$, so $AO\\approx5.39$ cm."},{"title":"Find AB","body":"Since $A$, $B$, $O$ are collinear and $OB=3$, $AB=AO-OB\\approx5.39-3=2.39$ cm."},{"title":"Perimeter","body":"$AB+\\text{major arc }BD+AD=2.39...+3(2\\pi-2.5)+8=21.7\\text{ cm}$ to one decimal place."}]},{"id":"WMA11-01_2019_Oct_Q09","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":9,"marks":4,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q09_M04_10_Radians.png","downloadName":"WMA11-01_Y2019_Oct_Q09_M04_10_Radians.png","finalAnswer":"$(a)\\ 24\\pi.\\quad (b)\\ (18\\pi,-1).\\quad (c)(i)\\ -12\\pi-\\alpha.\\quad (ii)\\ 6\\pi-\\alpha$.","steps":[{"title":"Use the scale factor inside the sine","body":"For $y=\\sin\\left(\\frac{x}{12}\\right)$, one full sine cycle needs $\\frac{x}{12}$ to increase by $2\\pi$, so the period is $24\\pi$."},{"title":"Locate the minimum point","body":"The sine function is $-1$ when its angle is $\\frac{3\\pi}{2}$. Therefore $\\frac{x}{12}=\\frac{3\\pi}{2}$, so $x=18\\pi$ and $M=(18\\pi,-1)$."},{"title":"Use sine symmetry","body":"If the smallest positive solution of $\\sin\\left(\\frac{x}{12}\\right)=k$ is $\\alpha$, then the closest negative solution is one half-period before the opposite sine position: $-12\\pi-\\alpha$."},{"title":"Convert to cosine","body":"Since $\\cos\\theta=\\sin\\left(\\frac\\pi2-\\theta\\right)$, the corresponding smallest positive cosine solution is $6\\pi-\\alpha$."}]},{"id":"WMA11-01_2020_Jan_Q07","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":7,"marks":5,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q07_M05_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2020_Jan_Q07_M05_06_GraphsOfFunctions.png","finalAnswer":"$(a)(i)\\ P=(90^\\circ,3).\\quad (a)(ii)\\ Q=(540^\\circ,0).\\quad (b)\\ R=(270^\\circ,4)$.","steps":[{"title":"Read P from y = 3 sin x","body":"The first maximum of $y=3\\sin x$ occurs at $x=90^\\circ$, with $y=3$. So $P=(90^\\circ,3)$."},{"title":"Read Q from the next shown zero","body":"After the second maximum, the curve returns to the x-axis at $x=540^\\circ$. So $Q=(540^\\circ,0)$."},{"title":"Find the vertical shift","body":"For $C_2$, $y=3\\sin x+k$. Its maximum is $3+k=10$, so $k=7$."},{"title":"Find the minimum point R","body":"The minimum value is $-3+7=4$. The smallest positive x-coordinate for a sine minimum is $270^\\circ$, so $R=(270^\\circ,4)$."}]},{"id":"WMA11-01_2021_Jan_Q03","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":3,"marks":5,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q03_M05_11_TrigFunctions.png","downloadName":"WMA11-01_Y2021_Jan_Q03_M05_11_TrigFunctions.png","finalAnswer":"$(a)(i)\\ P=(-180,-4).\\quad (a)(ii)\\ Q=(450,0).\\quad (b)\\ R=(360,7)$.","steps":[{"title":"Read the key points of y = 4 cos x","body":"For $y=4\\cos x^\\circ$, the maximum value is $4$ and the minimum value is $-4$. The minimum immediately to the left of the y-axis is at $x=-180^\\circ$, so $P=(-180,-4)$."},{"title":"Find Q from the cosine zero","body":"The x-intercepts of $4\\cos x^\\circ$ occur at $x=90^\\circ,270^\\circ,450^\\circ,\\ldots$. The point shown to the right of the next maximum is $Q=(450,0)$."},{"title":"Use the shifted curve C2","body":"For $C_2$, $y=4\\cos x^\\circ+k$. Its minimum is $-4+k$. Since the minimum value is $-1$, $-4+k=-1$, so $k=3$."},{"title":"Find R","body":"The maximum value of $C_2$ is $4+3=7$. The maximum point with the smallest positive x-coordinate occurs at $x=360^\\circ$, so $R=(360,7)$."}]},{"id":"WMA11-01_2021_MayJune_Q09","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":9,"marks":7,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q09_M07_11_TrigFunctions.png","downloadName":"WMA11-01_Y2021_MayJune_Q09_M07_11_TrigFunctions.png","finalAnswer":"$(a)\\ x=\\dfrac{3\\pi}{2}.\\quad (b)(i)\\ y=1\\text{ is the horizontal asymptote}.\\quad (b)(ii)\\ 5.\\quad (c)(i)\\ 40.\\quad (c)(ii)\\ 14$.","steps":[{"title":"State the shown tangent asymptote","body":"The shown dashed asymptote is the right-hand positive asymptote before $2\\pi$, so $l$ has equation $x=\\dfrac{3\\pi}{2}$."},{"title":"Describe the reciprocal graph","body":"For $y=\\dfrac1x+1$, the vertical asymptote is $x=0$ and the horizontal asymptote is $y=1$. The right branch lies above $y=1$ and the left branch lies below $y=1$."},{"title":"Count intersections on -2pi to 2pi","body":"The number of solutions of $\\tan x=\\dfrac1x+1$ is the number of intersections of the two graphs. From the sketch on $-2\\pi\\le x\\le2\\pi$, there are $5$ intersections."},{"title":"Count solutions for 0 <= x < 40pi","body":"From the repeated tangent branches and the reciprocal curve, there is one intersection in each positive interval between consecutive tangent asymptotes. From $0$ to $40\\pi$, this gives $40$ solutions."},{"title":"Count solutions for -10pi <= x <= 5pi/2","body":"Extending the same intersection pattern across the stated interval gives $14$ intersections, so there are $14$ solutions."}]},{"id":"WMA11-01_2021_Oct_Q04","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":4,"marks":5,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q04_M05_11_TrigFunctions.png","downloadName":"WMA11-01_Y2021_Oct_Q04_M05_11_TrigFunctions.png","finalAnswer":"$(a)(i)\\ Q=(90,-1).\\quad (a)(ii)\\ k=225.\\quad (b)\\ -1<p<0\\text{ or }p=1$.","steps":[{"title":"Find Q","body":"For $f(x)=\\cos 2x^\\circ$, the first minimum occurs when $2x=180^\\circ$, so $x=90^\\circ$ and $y=-1$. Therefore $Q=(90,-1)$."},{"title":"Find k","body":"The point $R(k,0)$ is the x-intercept after the next maximum. This occurs when $2x=450^\\circ$, so $x=225^\\circ$. Hence $k=225$."},{"title":"Count horizontal intersections","body":"A horizontal line $y=p$ gives exactly two intersections on $0\\le x\\le225$ when it cuts the two negative branches only, so $-1<p<0$."},{"title":"Include the maximum case","body":"There are also exactly two solutions when $p=1$, at $x=0$ and $x=180$. Therefore $-1<p<0$ or $p=1$."}]},{"id":"WMA11-01_2022_Jan_Q09","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":9,"marks":4,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q09_M04_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2022_Jan_Q09_M04_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ A=-3.\\quad (b)\\ Q=(930,3)$.","steps":[{"title":"Use the minimum point","body":"At $P(30,-3)$, $x-30=0$, so $\\cos0^\\circ=1$. Therefore $A=-3$."},{"title":"Find maximum points","body":"Since $A=-3$, maximum points occur when $\\cos(x-30)^\\circ=-1$."},{"title":"Use the shown maximum Q","body":"$x-30=180+360n$, so $x=210+360n$. The maximum shown at $Q$ is two full periods after the first maximum, so $x=210+720=930$."},{"title":"Write Q","body":"The maximum y-value is $3$, hence $Q=(930,3)$."}]},{"id":"WMA11-01_2022_MayJune_Q09","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":9,"marks":8,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q09_M08_11_TrigFunctions.png","downloadName":"WMA11-01_Y2022_MayJune_Q09_M08_11_TrigFunctions.png","finalAnswer":"$(a)(i)\\ 2p,\\ (ii)\\ -p,\\ (iii)\\ 3-p.\\quad (c)\\ x=\\dfrac{\\alpha}{2},\\ 90^\\circ-\\dfrac{\\alpha}{2}$.","steps":[{"title":"Use sine symmetry","body":"$\\sin(180^\\circ-\\alpha)=\\sin\\alpha=p$, so $2\\sin(180^\\circ-\\alpha)=2p$."},{"title":"Use odd symmetry","body":"$\\sin(\\alpha-180^\\circ)=-\\sin(180^\\circ-\\alpha)=-p$."},{"title":"Use the third quadrant identity","body":"$\\sin(180^\\circ+\\alpha)=-\\sin\\alpha=-p$, so $3+\\sin(180^\\circ+\\alpha)=3-p$."},{"title":"Sketch y = sin 2x","body":"The graph has amplitude 1 and period $180^\\circ$. It crosses the x-axis at $0^\\circ,90^\\circ,180^\\circ$, has a maximum at $45^\\circ$, and a minimum at $135^\\circ$."},{"title":"Solve sin 2x = p","body":"Since $\\sin\\alpha=p$ and $0<2x<360^\\circ$, the possible values are $2x=\\alpha$ or $2x=180^\\circ-\\alpha$."},{"title":"Find x","body":"Therefore $x=\\dfrac{\\alpha}{2}$ or $x=90^\\circ-\\dfrac{\\alpha}{2}$."}]},{"id":"WMA11-01_2023_Jan_Q09","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":9,"marks":4,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q09_M04_11_TrigFunctions.png","downloadName":"WMA11-01_Y2023_Jan_Q09_M04_11_TrigFunctions.png","finalAnswer":"$(a)\\ \\pi.\\quad (b)(i)\\ 3,\\ (ii)\\ 5,\\ (iii)\\ 201$.","steps":[{"title":"State the period","body":"The period of $\\tan x$ is $\\pi$."},{"title":"Count roots for the steeper line","body":"In $-\\pi<x<\\pi$, the line $y=(\\pi+2)x$ meets $y=\\tan x$ once at the origin and once on each side of the origin, giving 3 roots."},{"title":"Extend to -2pi < x < 2pi","body":"For $y=\\pi x$, the interval $-2\\pi<x<2\\pi$ has the 3 central roots plus one further root on each neighbouring branch, giving 5 roots."},{"title":"Extend to -100pi < x < 100pi","body":"There are 99 positive outer roots, 99 negative outer roots, and 3 central roots, so the total is $99+99+3=201$."}]},{"id":"WMA11-01_2023_MayJune_Q09","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":9,"marks":9,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q09_M09_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2023_MayJune_Q09_M09_06_GraphsOfFunctions.png","finalAnswer":"$(i)(a)\\ f(x)=3\\cos x.\\quad (i)(b)$ x-intercepts $-\\dfrac{7\\pi}{4},-\\dfrac{3\\pi}{4},\\dfrac\\pi4,\\dfrac{5\\pi}{4}$ and y-intercept $\\dfrac{3\\sqrt2}{2}$. $(ii)(a)\\ g(x)=\\sin2x.\\quad (ii)(b)$ y-intercept $(0,-2)$.","steps":[{"title":"Identify f(x)","body":"The first graph has amplitude 3, period $2\\pi$, and maximum at $x=0$, so $f(x)=3\\cos x$."},{"title":"Transform f","body":"$y=f\\left(x+\\dfrac\\pi4\\right)=3\\cos\\left(x+\\dfrac\\pi4\\right)$, a shift left by $\\dfrac\\pi4$."},{"title":"Find the x-intercepts","body":"$\\cos\\left(x+\\dfrac\\pi4\\right)=0$ gives $x=\\dfrac\\pi4+n\\pi$. In $-2\\pi<x<2\\pi$, these are $-\\dfrac{7\\pi}{4}$, $-\\dfrac{3\\pi}{4}$, $\\dfrac\\pi4$, and $\\dfrac{5\\pi}{4}$."},{"title":"Find the y-intercept","body":"At $x=0$, $y=3\\cos\\dfrac\\pi4=\\dfrac{3\\sqrt2}{2}$."},{"title":"Identify g(x)","body":"The second graph has amplitude 1, period $\\pi$, and passes through the origin with positive gradient, so $g(x)=\\sin2x$."},{"title":"Transform g","body":"$y=g(x)-2=\\sin2x-2$, so the graph is shifted down by 2. Its y-intercept is $(0,-2)$."}]},{"id":"WMA11-01_2023_Oct_Q10","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":10,"marks":6,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q10_M06_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2023_Oct_Q10_M06_06_GraphsOfFunctions.png","finalAnswer":"$(a)(i)\\ n=3.\\quad (a)(ii)\\ 1080^\\circ.\\quad (b)\\ Q=(1620,-3).\\quad (c)\\ k=\\dfrac{9}{10}$.","steps":[{"title":"Use the first positive x-intercept","body":"For $y=3\\cos\\left(\\dfrac{x}{n}\\right)^\\circ$, the first positive zero occurs when $\\dfrac{x}{n}=90^\\circ$."},{"title":"Find n","body":"Since $P=(270,0)$, $\\dfrac{270}{n}=90$, so $n=3$."},{"title":"Find the period","body":"The period is $360n=360(3)=1080^\\circ$."},{"title":"Read the shown minimum point","body":"A minimum occurs when $\\dfrac{x}{3}=180^\\circ+360^\\circ k$. The point $Q$ shown is the next displayed minimum after one full period, so $x=1620$ and $y=-3$."},{"title":"Use the two points on C2","body":"For $y=2\\sin x^\\circ+k$, the points give $2\\sin a+k=\\dfrac{12}{5}$ and $-2\\sin a+k=-\\dfrac35$."},{"title":"Add the equations","body":"Adding gives $2k=\\dfrac{12}{5}-\\dfrac35=\\dfrac95$, so $k=\\dfrac{9}{10}$."}]},{"id":"WMA11-01_2024_Jan_Q06","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":6,"marks":6,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q06_M06_11_TrigFunctions.png","downloadName":"WMA11-01_Y2024_Jan_Q06_M06_11_TrigFunctions.png","finalAnswer":"$(a)\\ P=(540^\\circ,-5).\\quad (b)(i)\\ Q=(360^\\circ,3).\\quad (b)(ii)\\ Q=(180^\\circ,5)$.","steps":[{"title":"Use the cosine graph","body":"For $y=5\\cos x$, the minimum value is $-5$ and it occurs at $x=180^\\circ+360^\\circ n$."},{"title":"Read P from the displayed minimum","body":"The plotted point $P$ is the displayed minimum at $x=540^\\circ$, so $P=(540^\\circ,-5)$."},{"title":"Translate the graph down","body":"For $y=5\\cos x-2$, the maximum value is $5-2=3$. The smallest positive x-coordinate for a maximum shown is $x=360^\\circ$, so $Q=(360^\\circ,3)$."},{"title":"Reflect in the x-axis","body":"For $y=-5\\cos x$, a maximum occurs where $\\cos x=-1$, first at $x=180^\\circ$. The maximum value is $5$, so $Q=(180^\\circ,5)$."}]},{"id":"WMA11-01_2024_MayJune_Q11","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":11,"marks":6,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q11_M06_10_Radians.png","downloadName":"WMA11-01_Y2024_MayJune_Q11_M06_10_Radians.png","finalAnswer":"$(a)\\ P=(\\dfrac{5\\pi}{2},12).\\quad (b)\\ (\\dfrac{3\\pi}{2},-21).\\quad (c)(i)\\ A=-12.\\quad (c)(ii)\\ B=\\dfrac{5\\pi}{4}$.","steps":[{"title":"Use maxima of sine","body":"For $y=12\\sin x$, maxima occur when $x=\\dfrac{\\pi}{2}+2\\pi n$, with value $12$."},{"title":"Read point P","body":"The maximum point $P$ shown is the second positive maximum, so $P=(\\dfrac{5\\pi}{2},12)$."},{"title":"Find k for C2","body":"For $y=12\\sin x+k$, the maximum value is $12+k$. Given the maximum is $3$, $k=-9$."},{"title":"Find the smallest positive minimum on C2","body":"The minimum value is $-12-9=-21$, and it first occurs at $x=\\dfrac{3\\pi}{2}$. So the point is $(\\dfrac{3\\pi}{2},-21)$."},{"title":"Find A for C3","body":"For $y=12\\sin(x+B)$, any minimum has value $-12$, so $A=-12$."},{"title":"Find the smallest positive B","body":"At the minimum $x=\\dfrac{\\pi}{4}$, so $\\dfrac{\\pi}{4}+B=\\dfrac{3\\pi}{2}$. Hence $B=\\dfrac{5\\pi}{4}$."}]},{"id":"WMA11-01_2024_Oct_Q07","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":7,"marks":8,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q07_M08_10_Radians.png","downloadName":"WMA11-01_Y2024_Oct_Q07_M08_10_Radians.png","finalAnswer":"$(a)(i)\\ P=(-2\\pi,-4).\\quad (a)(ii)\\ Q=(\\dfrac{3\\pi}{2},0).\\quad (b)(i)\\ k=7.\\quad (b)(ii)\\ (2\\pi,3).\\quad (c)\\ 1\\text{ solution}$.","steps":[{"title":"Use y equals negative 4 cos x","body":"For $y=-4\\cos x$, minimum points occur at $x=2\\pi n$ with value $-4$."},{"title":"Read P","body":"The displayed minimum to the left of the y-axis is $P=(-2\\pi,-4)$."},{"title":"Read Q","body":"The point $Q$ is the positive x-intercept after the maximum at $x=\\pi$, so $Q=(\\dfrac{3\\pi}{2},0)$."},{"title":"Find k for C2","body":"For $y=-4\\cos x+k$, the maximum value is $4+k$. Given the maximum is $11$, $k=7$."},{"title":"Find the smallest positive minimum on C2","body":"The minimum value is $-4+7=3$. The first positive minimum is at $x=2\\pi$, so the point is $(2\\pi,3)$."},{"title":"Interpret the equation graphically","body":"$-4\\cos x=5-\\dfrac{10}{\\pi}x$ is the intersection of the cosine curve with the straight line $y=5-\\dfrac{10}{\\pi}x$."},{"title":"Count intersections","body":"The line passes through $(0,5)$ and meets the displayed curve once, at the x-axis point, so there is 1 solution."}]},{"id":"WMA11-01_2025_Jan_Q09","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":9,"marks":13,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q09_M13_10_Radians.png","downloadName":"WMA11-01_Y2025_Jan_Q09_M13_10_Radians.png","finalAnswer":"$(a)\\ \\dfrac94-(x-3)^2.\\quad (b)\\ P=(3,\\dfrac94).\\quad (c)(i)\\ x_B=\\dfrac92.\\quad (c)(ii)\\ k=\\dfrac\\pi3.\\quad (c)(iii)\\ 6.\\quad (d)\\ \\dfrac32\\le x\\le\\dfrac92,\\ y\\ge\\cos(\\dfrac\\pi3x),\\ y\\le\\dfrac94-(x-3)^2,\\ y\\le-\\dfrac32x+\\dfrac{27}{4}$.","steps":[{"title":"Complete the square","body":"$6x-\\dfrac{27}{4}-x^2=-(x^2-6x)-\\dfrac{27}{4}=-(x-3)^2+9-\\dfrac{27}{4}$."},{"title":"State the completed-square form","body":"$6x-\\dfrac{27}{4}-x^2=\\dfrac94-(x-3)^2$."},{"title":"Find the maximum point","body":"The maximum point is $P=(3,\\dfrac94)$."},{"title":"Find the x-intercepts of C1","body":"$\\dfrac94-(x-3)^2=0$ gives $x=3\\pm\\dfrac32$. Hence $A$ has $x=\\dfrac32$ and $B$ has $x=\\dfrac92$."},{"title":"Use consecutive zeros of cosine","body":"The distance between consecutive zeros of $\\cos(kx)$ is $\\dfrac\\pi{k}$."},{"title":"Find k and the period","body":"Since $x_B-x_A=\\dfrac92-\\dfrac32=3$, $\\dfrac\\pi{k}=3$, so $k=\\dfrac\\pi3$. The period is $\\dfrac{2\\pi}{k}=6$."},{"title":"Find the line through P and B","body":"The line through $P(3,\\dfrac94)$ and $B(\\dfrac92,0)$ has gradient $-\\dfrac32$, so $L$ is $y=-\\dfrac32x+\\dfrac{27}{4}$."},{"title":"Define the x-range","body":"The region lies between $A$ and $B$, so $\\dfrac32\\le x\\le\\dfrac92$."},{"title":"Define the lower boundary","body":"The lower boundary is $C_2$, so $y\\ge\\cos\\left(\\dfrac\\pi3x\\right)$."},{"title":"Define the upper boundaries","body":"The region is below both $C_1$ and the line segment $L$, so $y\\le\\dfrac94-(x-3)^2$ and $y\\le-\\dfrac32x+\\dfrac{27}{4}$."}]},{"id":"WMA11-01_2025_MayJune_Q04","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":4,"marks":6,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q04_M06_11_TrigFunctions.png","downloadName":"WMA11-01_Y2025_MayJune_Q04_M06_11_TrigFunctions.png","finalAnswer":"$(a)\\ P=(270^\\circ,0).\\quad (b)\\ Q=(-180^\\circ,-4).\\quad (c)(i)\\ 100,\\ (ii)\\ 4,\\ (iii)\\ 7$.","steps":[{"title":"Point P","body":"For $y=4\\cos x$, the x-intercepts occur at $x=90^\\circ+180^\\circ n$. The labelled point $P$ is the right-hand intercept after $180^\\circ$, so $P=(270^\\circ,0)$."},{"title":"Point Q","body":"The minimum value is $-4$, reached at $x=180^\\circ+360^\\circ n$. The labelled point on the left is $Q=(-180^\\circ,-4)$."},{"title":"Part c(i)","body":"$4\\cos x=3$ has two solutions every $360^\\circ$. The interval $0<x\\le18000^\\circ$ contains $50$ full periods, so there are $100$ solutions."},{"title":"Part c(ii)","body":"$5+4\\cos x=1$ gives $\\cos x=-1$. This occurs once every $360^\\circ$. In $-720^\\circ<x\\le720^\\circ$, the solutions are $-540^\\circ,-180^\\circ,180^\\circ,540^\\circ$, so there are $4$."},{"title":"Part c(iii)","body":"$4\\cos x-3=1$ gives $\\cos x=1$. In $-1080^\\circ\\le x\\le1080^\\circ$, the multiples of $360^\\circ$ are $-1080,-720,-360,0,360,720,1080$, so there are $7$."}]},{"id":"WMA11-01_2026_Jan_Q09","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":9,"marks":9,"topic":"11_TrigFunctions","topicName":"Trigonometric Functions","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q09_M09_11_TrigFunctions.png","downloadName":"WMA11-01_Y2026_Jan_Q09_M09_11_TrigFunctions.png","finalAnswer":"$(a)\\ f(x)=-10\\cos x.\\quad (b)(ii)\\ 2.\\quad (c)(ii)\\ 200$.","steps":[{"title":"Identify f(x)","body":"The graph has amplitude $10$, period $2\\pi$, and value $-10$ at $x=0$, so $f(x)=-10\\cos x$."},{"title":"Sketch y equals 10 minus x squared","body":"The graph $y=10-x^2$ is a downward-opening parabola with vertex $(0,10)$ and x-intercepts at $x=\\pm\\sqrt{10}$."},{"title":"Count intersections with the parabola","body":"On the given sketch, the parabola meets $f(x)$ twice. Outside the central part the parabola is below the range of $f(x)$, so there are $2$ solutions in $-100\\pi\\le x\\le100\\pi$."},{"title":"Sketch y equals tan x","body":"The graph $y=\\tan x$ has zeros at integer multiples of $\\pi$ and vertical asymptotes at $x=\\dfrac\\pi2+n\\pi$."},{"title":"Count in the reference interval","body":"In $-2\\pi\\le x\\le2\\pi$, the graph $y=\\tan x$ intersects $f(x)$ four times."},{"title":"Scale to the required interval","body":"The interval $-100\\pi\\le x\\le100\\pi$ is $50$ times as long as $-2\\pi\\le x\\le2\\pi$, so the number of solutions is $50\\times4=200$."}]},{"id":"WMA11-01_2019_Oct_Q05","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":5,"marks":7,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q05_M07_12_Differentiation.png","downloadName":"WMA11-01_Y2019_Oct_Q05_M07_12_Differentiation.png","finalAnswer":"$\\dfrac{dy}{dx}=\\dfrac{x^2}{2}+\\dfrac{2}{\\sqrt{x}}$, and the normal is $x+9y-37=0$.","steps":[{"title":"Rewrite before differentiating","body":"$y=\\frac{x^3}{6}+4x^{1/2}-15$."},{"title":"Differentiate term by term","body":"$\\dfrac{dy}{dx}=\\frac{3x^2}{6}+4\\cdot\\frac12x^{-1/2}=\\frac{x^2}{2}+\\frac{2}{\\sqrt{x}}$."},{"title":"Find the tangent and normal gradients at P","body":"At $x=4$, $\\dfrac{dy}{dx}=\\frac{16}{2}+\\frac{2}{2}=9$. The normal gradient is therefore $-\\frac19$."},{"title":"Build the normal equation","body":"Using $P\\left(4,\\frac{11}{3}\\right)$: $y-\\frac{11}{3}=-\\frac19(x-4)$. Multiplying out gives $x+9y-37=0$."}]},{"id":"WMA11-01_2019_Oct_Q07","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":7,"marks":6,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q07_M06_12_Differentiation.png","downloadName":"WMA11-01_Y2019_Oct_Q07_M06_12_Differentiation.png","finalAnswer":"$(a)\\ 8.\\quad (b)\\ 8+2h.\\quad (c)\\ As\\ h\\to0,\\ 8+2h\\to8$.","steps":[{"title":"Differentiate for the tangent gradient","body":"For $y=2x^2+5$, $\\dfrac{dy}{dx}=4x$. At $P$, $x=2$, so the tangent gradient is $8$."},{"title":"Find the coordinates of Q","body":"If $x_Q=2+h$, then $y_Q=2(2+h)^2+5=13+8h+2h^2$."},{"title":"Find the gradient of PQ","body":"$\\text{gradient }PQ=\\dfrac{(13+8h+2h^2)-13}{(2+h)-2}=\\dfrac{8h+2h^2}{h}=8+2h$."},{"title":"Explain the link","body":"As $h$ gets closer to $0$, point $Q$ gets closer to $P$, and the chord gradient $8+2h$ tends to the tangent gradient $8$."}]},{"id":"WMA11-01_2020_Jan_Q03","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":3,"marks":6,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q03_M06_12_Differentiation.png","downloadName":"WMA11-01_Y2020_Jan_Q03_M06_12_Differentiation.png","finalAnswer":"$(a)\\ 9.\\quad (b)\\ 9+h.\\quad (c)\\ As\\ h\\to0,\\ 9+h\\to9$.","steps":[{"title":"Differentiate for the tangent gradient","body":"For $y=x^2+3x-2$, $\\dfrac{dy}{dx}=2x+3$. At $x=3$, the gradient is $2(3)+3=9$."},{"title":"Find the y-coordinate of Q","body":"For $x_Q=3+h$, $y_Q=(3+h)^2+3(3+h)-2=16+9h+h^2$."},{"title":"Calculate the gradient of PQ","body":"$\\text{gradient }PQ=\\dfrac{(16+9h+h^2)-16}{(3+h)-3}=\\dfrac{9h+h^2}{h}=9+h$."},{"title":"Explain the relationship","body":"As $h\\to0$, point $Q$ approaches $P$, and the chord gradient $9+h$ approaches the tangent gradient $9$."}]},{"id":"WMA11-01_2020_Jan_Q09","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":9,"marks":6,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q09_M06_12_Differentiation.png","downloadName":"WMA11-01_Y2020_Jan_Q09_M06_12_Differentiation.png","finalAnswer":"$x=\\dfrac{\\sqrt3}{2}$.","steps":[{"title":"Rewrite the function","body":"$y=\\dfrac{4x^2+9}{2\\sqrt{x}}=2x^{3/2}+\\dfrac92x^{-1/2}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=3x^{1/2}-\\dfrac94x^{-3/2}$."},{"title":"Set the derivative equal to zero","body":"$3x^{1/2}-\\dfrac94x^{-3/2}=0$, so $3\\sqrt{x}=\\dfrac{9}{4x^{3/2}}$."},{"title":"Solve for x","body":"Multiply by $4x^{3/2}$: $12x^2=9$. Hence $x^2=\\frac34$. Since $x>0$, $x=\\frac{\\sqrt3}{2}$."}]},{"id":"WMA11-01_2021_Jan_Q01","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":1,"marks":8,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q01_M08_12_Differentiation.png","downloadName":"WMA11-01_Y2021_Jan_Q01_M08_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=6x^2-10x+\\dfrac{3}{2x^2}.\\quad (b)\\ 2x+5y-16=0$.","steps":[{"title":"Rewrite the negative power term","body":"$y=2x^3-5x^2-\\dfrac{3}{2x}+7=2x^3-5x^2-\\dfrac32x^{-1}+7$."},{"title":"Differentiate term by term","body":"$\\dfrac{dy}{dx}=6x^2-10x+\\dfrac32x^{-2}=6x^2-10x+\\dfrac{3}{2x^2}$."},{"title":"Find the point P","body":"At $x=\\dfrac12$, $y=2\\left(\\dfrac18\\right)-5\\left(\\dfrac14\\right)-\\dfrac{3}{1}+7=3$, so $P=\\left(\\dfrac12,3\\right)$."},{"title":"Find the normal gradient","body":"At $x=\\dfrac12$, $\\dfrac{dy}{dx}=6\\left(\\dfrac14\\right)-10\\left(\\dfrac12\\right)+\\dfrac{3}{2(1/4)}=\\dfrac52$. The normal gradient is therefore $-\\dfrac25$."},{"title":"Write the normal in integer form","body":"$y-3=-\\dfrac25\\left(x-\\dfrac12\\right)$. Multiplying by $5$ gives $5y-15=-2x+1$, hence $2x+5y-16=0$."}]},{"id":"WMA11-01_2021_Jan_Q07","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":7,"marks":9,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q07_M09_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2021_Jan_Q07_M09_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ x=\\dfrac{49}{4}.\\quad (b)\\ x=\\dfrac14$.","steps":[{"title":"Solve f(x) = 9 without calculator methods","body":"$2x-3\\sqrt{x}-5=9$, so $2x-3\\sqrt{x}-14=0$."},{"title":"Use u = sqrt(x)","body":"Let $u=\\sqrt{x}$, where $u>0$. Then $x=u^2$, so $2u^2-3u-14=0$."},{"title":"Factorise and reject the invalid root","body":"$2u^2-3u-14=(2u-7)(u+2)$. Since $u>0$, $u=\\dfrac72$, so $x=u^2=\\dfrac{49}{4}$."},{"title":"Differentiate twice","body":"$f(x)=2x-3x^{1/2}-5$, so $f'(x)=2-\\dfrac32x^{-1/2}$ and $f''(x)=\\dfrac34x^{-3/2}$."},{"title":"Solve f''(x) = 6","body":"$\\dfrac34x^{-3/2}=6$, so $x^{-3/2}=8$. Therefore $x^{3/2}=\\dfrac18$."},{"title":"Find x","body":"Since $x^{3/2}=(\\sqrt{x})^3$, we get $\\sqrt{x}=\\dfrac12$, hence $x=\\dfrac14$."}]},{"id":"WMA11-01_2021_MayJune_Q01","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":1,"marks":8,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q01_M08_12_Differentiation.png","downloadName":"WMA11-01_Y2021_MayJune_Q01_M08_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=\\dfrac{2x}{3}-\\dfrac{2}{x\\sqrt{x}}-\\dfrac{8}{3x^2}.\\quad (b)\\ 4x+9y-43=0$.","steps":[{"title":"Rewrite using powers","body":"$y=\\dfrac{x^2}{3}+4x^{-1/2}+\\dfrac83x^{-1}-5$."},{"title":"Differentiate term by term","body":"$\\dfrac{dy}{dx}=\\dfrac{2x}{3}-2x^{-3/2}-\\dfrac83x^{-2}=\\dfrac{2x}{3}-\\dfrac{2}{x\\sqrt{x}}-\\dfrac{8}{3x^2}$."},{"title":"Find the tangent gradient at P","body":"At $x=4$, $\\dfrac{dy}{dx}=\\dfrac83-\\dfrac14-\\dfrac16=\\dfrac94$."},{"title":"Find the normal gradient","body":"The normal gradient is the negative reciprocal of $\\dfrac94$, so $m_n=-\\dfrac49$."},{"title":"Write the normal equation","body":"Using $P(4,3)$, $y-3=-\\dfrac49(x-4)$. Multiplying by $9$ gives $9y-27=-4x+16$, hence $4x+9y-43=0$."}]},{"id":"WMA11-01_2021_Oct_Q02","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":2,"marks":5,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q02_M05_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2021_Oct_Q02_M05_06_GraphsOfFunctions.png","finalAnswer":"$x=\\pm\\dfrac{\\sqrt5}{5}$.","steps":[{"title":"Differentiate the curve","body":"For $y=3x^5+4x^3-x+5$, $\\dfrac{dy}{dx}=15x^4+12x^2-1$."},{"title":"Set the gradient equal to 2","body":"$15x^4+12x^2-1=2$, so $15x^4+12x^2-3=0$."},{"title":"Reduce to a quadratic in x squared","body":"Dividing by $3$ gives $5x^4+4x^2-1=0$. Let $u=x^2$, giving $5u^2+4u-1=0$."},{"title":"Solve and reject the impossible value","body":"$5u^2+4u-1=(5u-1)(u+1)=0$. Since $u=x^2\\ge0$, $u=\\dfrac15$."},{"title":"Find x","body":"$x^2=\\dfrac15$, so $x=\\pm\\dfrac1{\\sqrt5}=\\pm\\dfrac{\\sqrt5}{5}$."}]},{"id":"WMA11-01_2022_Jan_Q07","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":7,"marks":11,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q07_M11_13_Integration.png","downloadName":"WMA11-01_Y2022_Jan_Q07_M11_13_Integration.png","finalAnswer":"$(a)\\ p=22.\\quad (b)\\ q=-4,2,\\dfrac92.\\quad (c)\\ f'(x)=6x^2-10x-34.\\quad (d)\\ -1<x<\\dfrac83$.","steps":[{"title":"Find p from the translated curve","body":"$f(0)=(4)(-2)(-9)=72$. Since $y=f(x)-p$ passes through $(0,50)$, $72-p=50$, so $p=22$."},{"title":"Use roots for f(x + q)","body":"If $y=f(x+q)$ passes through the origin, then $f(q)=0$. From $f(x)=(x+4)(x-2)(2x-9)$, the possible values are $q=-4,2,\\dfrac92$."},{"title":"Expand f(x)","body":"$(x+4)(x-2)(2x-9)=2x^3-5x^2-34x+72$."},{"title":"Differentiate","body":"$f'(x)=6x^2-10x-34$."},{"title":"Set the gradient less than -18","body":"$6x^2-10x-34<-18$, so $6x^2-10x-16<0$, or $3x^2-5x-8<0$."},{"title":"Solve the inequality","body":"$3x^2-5x-8=(3x-8)(x+1)$. Since the quadratic opens upward, it is negative between the roots: $-1<x<\\dfrac83$."}]},{"id":"WMA11-01_2022_MayJune_Q10","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":10,"marks":12,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q10_M12_12_Differentiation.png","downloadName":"WMA11-01_Y2022_MayJune_Q10_M12_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=\\dfrac67x^2+\\dfrac27x-\\dfrac52.\\quad (c)\\ x_B=\\dfrac32.\\quad (d)\\ k=\\dfrac54$.","steps":[{"title":"Differentiate the curve","body":"For $y=\\dfrac27x^3+\\dfrac17x^2-\\dfrac52x+k$, $\\dfrac{dy}{dx}=\\dfrac67x^2+\\dfrac27x-\\dfrac52$."},{"title":"Find the tangent gradient at A","body":"At $x=-\\dfrac72$, $\\dfrac{dy}{dx}=\\dfrac67\\left(\\dfrac{49}{4}\\right)+\\dfrac27\\left(-\\dfrac72\\right)-\\dfrac52=\\dfrac{21}{2}-1-\\dfrac52=7$."},{"title":"Find the gradient of l","body":"Since $l$ is the normal at $A$, its gradient is the negative reciprocal of 7, so $m_l=-\\dfrac17$."},{"title":"Use that l is tangent at B","body":"At $B$, the tangent gradient is also $-\\dfrac17$, so $\\dfrac67x^2+\\dfrac27x-\\dfrac52=-\\dfrac17$."},{"title":"Reach the given quadratic","body":"Multiplying by 14 gives $12x^2+4x-35=-2$, hence $12x^2+4x-33=0$."},{"title":"Solve for the x-coordinate of B","body":"$12x^2+4x-33=0$ gives $x=\\dfrac{-4\\pm40}{24}$, so $x=\\dfrac32$ or $x=-\\dfrac{11}{6}$. From the diagram, $B$ is the point to the right of the y-axis, so $x_B=\\dfrac32$."},{"title":"Use the y-intercept of l","body":"Since the y-intercept is $-1$ and the gradient is $-\\dfrac17$, the line is $y=-\\dfrac17x-1$."},{"title":"Find the y-coordinate of A","body":"At $x=-\\dfrac72$ on the line, $y=-\\dfrac17\\left(-\\dfrac72\\right)-1=\\dfrac12-1=-\\dfrac12$."},{"title":"Substitute A into the curve","body":"$-\\dfrac12=\\dfrac27\\left(-\\dfrac72\\right)^3+\\dfrac17\\left(-\\dfrac72\\right)^2-\\dfrac52\\left(-\\dfrac72\\right)+k=-\\dfrac74+k$."},{"title":"Find k","body":"Therefore $k=\\dfrac54$."}]},{"id":"WMA11-01_2022_Oct_Q01","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":1,"marks":6,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q01_M06_12_Differentiation.png","downloadName":"WMA11-01_Y2022_Oct_Q01_M06_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=\\dfrac34x^2-2x-\\dfrac{17}{x^2}.\\quad (b)\\ 21x+4y-68=0$.","steps":[{"title":"Rewrite the curve","body":"$y=\\dfrac{x^3}{4}-x^2+\\dfrac{17}{x}=\\dfrac14x^3-x^2+17x^{-1}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=\\dfrac34x^2-2x-17x^{-2}=\\dfrac34x^2-2x-\\dfrac{17}{x^2}$."},{"title":"Find the gradient at R","body":"At $x=2$, the tangent gradient is $\\dfrac34(4)-2(2)-\\dfrac{17}{4}=3-4-\\dfrac{17}{4}=-\\dfrac{21}{4}$."},{"title":"Use the point R","body":"The point is $R\\left(2,\\dfrac{13}{2}\\right)$, so $y-\\dfrac{13}{2}=-\\dfrac{21}{4}(x-2)$."},{"title":"Write in integer form","body":"Multiplying by 4 gives $4y-26=-21x+42$, hence $21x+4y-68=0$."}]},{"id":"WMA11-01_2022_Oct_Q09","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":9,"marks":14,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q09_M14_08_StraightLine.png","downloadName":"WMA11-01_Y2022_Oct_Q09_M14_08_StraightLine.png","finalAnswer":"$(a)\\ \\dfrac12(x-10)^2-28.\\quad (b)\\ M(10,-28).\\quad (c)\\ P(18,4),\\ k=\\dfrac{25}{4}.\\quad (d)\\ 10\\le x\\le18,\\ \\dfrac12x^2-10x+22\\le y\\le\\dfrac{25}{4}-\\dfrac{x}{8}$.","steps":[{"title":"Complete the square","body":"$\\dfrac12x^2-10x+22=\\dfrac12(x^2-20x)+22=\\dfrac12\\big((x-10)^2-100\\big)+22$."},{"title":"Simplify the completed square form","body":"$\\dfrac12\\big((x-10)^2-100\\big)+22=\\dfrac12(x-10)^2-28$."},{"title":"Read the minimum point","body":"The minimum point is $M(10,-28)$."},{"title":"Use the normal gradient","body":"The line $l$ has gradient $-\\dfrac18$, so the tangent gradient at $P$ is $8$."},{"title":"Differentiate the curve","body":"$\\dfrac{dy}{dx}=x-10$. At $P$, $x-10=8$, so $x=18$."},{"title":"Find P","body":"When $x=18$, $y=\\dfrac12(18)^2-10(18)+22=4$, so $P=(18,4)$."},{"title":"Find k","body":"Since $P$ lies on $y=k-\\dfrac18x$, $4=k-\\dfrac18(18)=k-\\dfrac94$, so $k=\\dfrac{25}{4}$."},{"title":"Write the upper boundary","body":"The line is $y=\\dfrac{25}{4}-\\dfrac{x}{8}$."},{"title":"Write the lower boundary","body":"The curve is $y=\\dfrac12x^2-10x+22$."},{"title":"Identify the region","body":"The region lies to the right of the vertical line through $M$ and between the curve and the normal line: $10\\le x\\le18$ and $\\dfrac12x^2-10x+22\\le y\\le\\dfrac{25}{4}-\\dfrac{x}{8}$."}]},{"id":"WMA11-01_2023_Jan_Q01","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":1,"marks":5,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q01_M05_12_Differentiation.png","downloadName":"WMA11-01_Y2023_Jan_Q01_M05_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=\\dfrac{5}{\\sqrt{x}}-3\\sqrt{x}.\\quad (b)\\ -\\dfrac{\\sqrt2}{2}$.","steps":[{"title":"Differentiate term by term","body":"$y=2+10x^{1/2}-2x^{3/2}$, so $\\dfrac{dy}{dx}=5x^{-1/2}-3x^{1/2}$."},{"title":"Write in simplest form","body":"$\\dfrac{dy}{dx}=\\dfrac{5}{\\sqrt{x}}-3\\sqrt{x}$."},{"title":"Substitute x = 2","body":"At $x=2$, the gradient is $\\dfrac5{\\sqrt2}-3\\sqrt2=\\dfrac5{\\sqrt2}-\\dfrac6{\\sqrt2}=-\\dfrac1{\\sqrt2}$."},{"title":"Rationalise","body":"$-\\dfrac1{\\sqrt2}=-\\dfrac{\\sqrt2}{2}$."}]},{"id":"WMA11-01_2023_Jan_Q10","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":10,"marks":10,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q10_M10_06_GraphsOfFunctions.png","downloadName":"WMA11-01_Y2023_Jan_Q10_M10_06_GraphsOfFunctions.png","finalAnswer":"$(a)\\ -\\dfrac{20}{3}<x<-6\\text{ or }x>\\dfrac32.\\quad (b)\\ 6x^3+67x^2+126x-360.\\quad (c)\\ x_P=-\\dfrac{67}{6}$.","steps":[{"title":"Use the roots","body":"$f(x)=(3x+20)(x+6)(2x-3)$ has roots $x=-\\dfrac{20}{3}$, $x=-6$, and $x=\\dfrac32$."},{"title":"State where f(x) is positive","body":"Since the cubic has positive leading coefficient, $f(x)>0$ for $-\\dfrac{20}{3}<x<-6$ and for $x>\\dfrac32$."},{"title":"Expand the first two brackets","body":"$(3x+20)(x+6)=3x^2+38x+120$."},{"title":"Complete the expansion","body":"$(3x^2+38x+120)(2x-3)=6x^3+67x^2+126x-360$."},{"title":"Find the tangent at the y-axis","body":"$f'(x)=18x^2+134x+126$, so at $x=0$ the tangent gradient is $126$. Also $f(0)=-360$."},{"title":"Write the tangent equation","body":"The tangent line is $y=126x-360$."},{"title":"Find the other intersection","body":"Set $6x^3+67x^2+126x-360=126x-360$. This gives $6x^3+67x^2=0$, so $x^2(6x+67)=0$."},{"title":"Choose point P","body":"$x=0$ is the tangent point on the y-axis, so the other intersection $P$ has $x=-\\dfrac{67}{6}$."}]},{"id":"WMA11-01_2023_MayJune_Q04","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":4,"marks":7,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q04_M07_12_Differentiation.png","downloadName":"WMA11-01_Y2023_MayJune_Q04_M07_12_Differentiation.png","finalAnswer":"$(a)\\ y=\\dfrac52x^{5/3}+\\dfrac12x^{7/6}.\\quad (b)\\ \\dfrac{dy}{dx}=\\dfrac{25}{6}x^{2/3}+\\dfrac{7}{12}x^{1/6}$.","steps":[{"title":"Rewrite the denominator","body":"$\\sqrt[3]{8x}=2x^{1/3}$."},{"title":"Rewrite the numerator","body":"$\\sqrt{x^3}=x^{3/2}$."},{"title":"Divide each term","body":"$y=\\dfrac{5x^2}{2x^{1/3}}+\\dfrac{x^{3/2}}{2x^{1/3}}=\\dfrac52x^{5/3}+\\dfrac12x^{7/6}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=\\dfrac52\\cdot\\dfrac53x^{2/3}+\\dfrac12\\cdot\\dfrac76x^{1/6}$."},{"title":"Simplify coefficients","body":"$\\dfrac{dy}{dx}=\\dfrac{25}{6}x^{2/3}+\\dfrac{7}{12}x^{1/6}$."}]},{"id":"WMA11-01_2023_Oct_Q01","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":1,"marks":5,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q01_M05_12_Differentiation.png","downloadName":"WMA11-01_Y2023_Oct_Q01_M05_12_Differentiation.png","finalAnswer":"$\\dfrac{dy}{dx}=15x^2-\\dfrac{6}{x^3}-7$, and $\\dfrac{d^2y}{dx^2}=30x+\\dfrac{18}{x^4}$.","steps":[{"title":"Rewrite the powers","body":"$y=5x^3+3x^{-2}-7x$."},{"title":"Differentiate once","body":"$\\dfrac{dy}{dx}=15x^2-6x^{-3}-7=15x^2-\\dfrac{6}{x^3}-7$."},{"title":"Differentiate again","body":"$\\dfrac{d^2y}{dx^2}=30x+18x^{-4}=30x+\\dfrac{18}{x^4}$."}]},{"id":"WMA11-01_2024_Jan_Q03","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":3,"marks":7,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q03_M07_12_Differentiation.png","downloadName":"WMA11-01_Y2024_Jan_Q03_M07_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=\\dfrac52+\\dfrac{8}{x^3}.\\quad (b)\\ 7x-2y-6=0$.","steps":[{"title":"Rewrite y","body":"$y=\\dfrac{5x^3-8}{2x^2}=\\dfrac52x-4x^{-2}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=\\dfrac52+8x^{-3}=\\dfrac52+\\dfrac{8}{x^3}$."},{"title":"Find the gradient at P","body":"At $x=2$, $\\dfrac{dy}{dx}=\\dfrac52+\\dfrac{8}{8}=\\dfrac72$."},{"title":"Use point-gradient form","body":"The tangent through $P(2,4)$ is $y-4=\\dfrac72(x-2)$."},{"title":"Rearrange","body":"$2y-8=7x-14$, so $7x-2y-6=0$."}]},{"id":"WMA11-01_2024_MayJune_Q07","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":7,"marks":8,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q07_M08_12_Differentiation.png","downloadName":"WMA11-01_Y2024_MayJune_Q07_M08_12_Differentiation.png","finalAnswer":"$(a)(i)\\ f'(x)=6x^2-2kx+14.\\quad (a)(ii)\\ f''(x)=12x-2k.\\quad (b)\\ k=13.\\quad (c)\\ B=(\\dfrac43,-10)$.","steps":[{"title":"Differentiate once","body":"$f'(x)=6x^2-2kx+14$."},{"title":"Differentiate again","body":"$f''(x)=12x-2k$."},{"title":"Use the intersection at A","body":"At an intersection of $y=f'(x)$ and $y=f''(x)$, $f'(x)=f''(x)$. Given $x_A=5$, substitute $x=5$."},{"title":"Find k","body":"$6(5)^2-2k(5)+14=12(5)-2k$, so $164-10k=60-2k$ and $k=13$."},{"title":"Find the other x-coordinate","body":"With $k=13$, $6x^2-26x+14=12x-26$, so $6x^2-38x+40=0$. Hence $(3x-4)(x-5)=0$."},{"title":"Use the point B","body":"The other point has $x=\\dfrac43$. Then $y=f''(\\dfrac43)=12(\\dfrac43)-26=-10$."}]},{"id":"WMA11-01_2024_Oct_Q09","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":9,"marks":10,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q09_M10_13_Integration.png","downloadName":"WMA11-01_Y2024_Oct_Q09_M10_13_Integration.png","finalAnswer":"$(a)\\ x\\ge-5.\\quad (b)\\ f'(x)=9x^2+22x.\\quad (c)\\ x_P=\\dfrac{14}{9}.\\quad (d)(i)\\ (-1,84).\\quad (d)(ii)\\ (-4,336)$.","steps":[{"title":"Use the positive quadratic factor","body":"$3x^2-4x+20$ has discriminant $(-4)^2-4(3)(20)<0$ and positive leading coefficient, so it is always positive."},{"title":"Deduce the sign of f(x)","body":"The sign of $f(x)=(x+5)(3x^2-4x+20)$ is therefore the sign of $x+5$. Hence $f(x)\\ge0$ for $x\\ge-5$."},{"title":"Expand f(x)","body":"$f(x)=3x^3+11x^2+100$."},{"title":"Differentiate","body":"$f'(x)=9x^2+22x$."},{"title":"Find the gradient at R","body":"At $R(-4,84)$, $f'(-4)=9(16)+22(-4)=56$."},{"title":"Use parallel tangents","body":"For the tangent at $P$ to be parallel, $f'(x)=56$."},{"title":"Solve for x","body":"$9x^2+22x-56=0$, so $x=\\dfrac{-22\\pm50}{18}$. The roots are $x=-4$ and $x=\\dfrac{14}{9}$."},{"title":"Choose the point P","body":"$x=-4$ is the point $R$, so $x_P=\\dfrac{14}{9}$."},{"title":"Transform R under y equals f of x minus 3","body":"$y=f(x-3)$ translates the curve 3 units to the right, so $(-4,84)$ maps to $(-1,84)$."},{"title":"Transform R under y equals 4f(x)","body":"$y=4f(x)$ stretches vertically by scale factor 4, so $(-4,84)$ maps to $(-4,336)$."}]},{"id":"WMA11-01_2025_Jan_Q05","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":5,"marks":8,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q05_M08_12_Differentiation.png","downloadName":"WMA11-01_Y2025_Jan_Q05_M08_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=12x^2-\\dfrac{2}{x^2}.\\quad (c)\\ k=16$.","steps":[{"title":"Differentiate","body":"$y=4x^3+2x^{-1}+9$, so $\\dfrac{dy}{dx}=12x^2-2x^{-2}=12x^2-\\dfrac2{x^2}$."},{"title":"Use the tangent gradient","body":"The tangent line $y=k-5x$ has gradient $-5$, so at $P$, $12x^2-\\dfrac2{x^2}=-5$."},{"title":"Clear the denominator","body":"Multiplying by $x^2$ gives $12x^4-2=-5x^2$, hence $12x^4+5x^2-2=0$."},{"title":"Solve for x squared","body":"Let $u=x^2$. Then $12u^2+5u-2=(3u+2)(4u-1)=0$."},{"title":"Use x greater than zero","body":"$x^2=\\dfrac14$, so $x=\\dfrac12$."},{"title":"Find the y-coordinate of P","body":"$y=4\\left(\\dfrac12\\right)^3+\\dfrac{2}{1/2}+9=\\dfrac12+4+9=\\dfrac{27}{2}$."},{"title":"Find k","body":"Since $P$ lies on $y=k-5x$, $\\dfrac{27}{2}=k-\\dfrac52$, so $k=16$."}]},{"id":"WMA11-01_2025_MayJune_Q02","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":2,"marks":5,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q02_M05_12_Differentiation.png","downloadName":"WMA11-01_Y2025_MayJune_Q02_M05_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=5x^{3/2}-4.\\quad (b)\\ k=\\dfrac43$.","steps":[{"title":"Differentiate","body":"$y=2x^{5/2}-4x+3$, so $\\dfrac{dy}{dx}=2\\cdot\\dfrac52x^{3/2}-4=5x^{3/2}-4$."},{"title":"Use the gradient at P","body":"At $P$, the gradient is $16$, so $5x^{3/2}-4=16$."},{"title":"Find x","body":"$5x^{3/2}=20$, hence $x^{3/2}=4$."},{"title":"Use x equals 2 to the k","body":"Since the x-coordinate of $P$ is $2^k$, we have $(2^k)^{3/2}=4=2^2$."},{"title":"Solve for k","body":"$2^{3k/2}=2^2$, so $\\dfrac{3k}{2}=2$ and $k=\\dfrac43$."}]},{"id":"WMA11-01_2025_Oct_Q01","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":1,"marks":6,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q01_M06_12_Differentiation.png","downloadName":"WMA11-01_Y2025_Oct_Q01_M06_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=12x+\\dfrac{3}{2\\sqrt{x}}.\\quad (b)\\ y=6x+1$.","steps":[{"title":"Rewrite the curve","body":"$y=6x^2+3x^{1/2}+\\dfrac58$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=12x+\\dfrac32x^{-1/2}=12x+\\dfrac{3}{2\\sqrt{x}}$."},{"title":"Find the tangent gradient","body":"At $x=\\dfrac14$, $\\dfrac{dy}{dx}=12\\left(\\dfrac14\\right)+\\dfrac32\\left(\\dfrac14\\right)^{-1/2}=3+3=6$."},{"title":"Use point P","body":"The tangent passes through $P\\left(\\dfrac14,\\dfrac52\\right)$, so $y-\\dfrac52=6\\left(x-\\dfrac14\\right)$."},{"title":"Simplify","body":"$y-\\dfrac52=6x-\\dfrac32$, hence $y=6x+1$."}]},{"id":"WMA11-01_2025_Oct_Q10","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":10,"marks":10,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q10_M10_08_StraightLine.png","downloadName":"WMA11-01_Y2025_Oct_Q10_M10_08_StraightLine.png","finalAnswer":"$(a)\\ x_Q=-\\dfrac54.\\quad (b)\\ x_T=\\dfrac{-1+\\sqrt{61}}{12}$.","steps":[{"title":"Differentiate C","body":"$y=2x^3+\\dfrac12x^2-2x+5$, so $\\dfrac{dy}{dx}=6x^2+x-2$."},{"title":"Find the tangent gradient at P","body":"At $P$, $x=0$, so the tangent gradient is $-2$."},{"title":"Equation of the normal","body":"The normal gradient is $\\dfrac12$ and $P=(0,5)$, so $l:y=\\dfrac12x+5$."},{"title":"Find intersections with the normal","body":"Set $2x^3+\\dfrac12x^2-2x+5=\\dfrac12x+5$."},{"title":"Form and factor the cubic","body":"$2x^3+\\dfrac12x^2-\\dfrac52x=0$. Multiplying by $2$ gives $4x^3+x^2-5x=0=x(4x^2+x-5)$."},{"title":"Solve for x","body":"$x(4x+5)(x-1)=0$, so the intersections have x-coordinates $0$, $-\\dfrac54$ and $1$."},{"title":"Select point Q","body":"The point $Q$ is the left-hand intersection, so $x_Q=-\\dfrac54$."},{"title":"Parallel tangent condition","body":"The tangent at $T$ is parallel to $l$, so its gradient is $\\dfrac12$."},{"title":"Set derivative equal to one half","body":"$6x^2+x-2=\\dfrac12$, so $12x^2+2x-5=0$."},{"title":"Use the positive solution","body":"$x=\\dfrac{-2\\pm\\sqrt{4+240}}{24}=\\dfrac{-1\\pm\\sqrt{61}}{12}$. Since $x_T$ is positive, $x_T=\\dfrac{-1+\\sqrt{61}}{12}$."}]},{"id":"WMA11-01_2026_Jan_Q07","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":7,"marks":10,"topic":"12_Differentiation","topicName":"Differentiation","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q07_M10_12_Differentiation.png","downloadName":"WMA11-01_Y2026_Jan_Q07_M10_12_Differentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=2(x-4)^2+11.\\quad (b)\\ \\min\\dfrac{dy}{dx}=11\\text{ at }x=4.\\quad (c)\\ y=11x+36$.","steps":[{"title":"Differentiate","body":"$y=\\dfrac23x^3-8x^2+43x-\\dfrac{20}{3}$ gives $\\dfrac{dy}{dx}=2x^2-16x+43$."},{"title":"Complete the square","body":"$2x^2-16x+43=2(x^2-8x)+43=2[(x-4)^2-16]+43$."},{"title":"Simplify","body":"$\\dfrac{dy}{dx}=2(x-4)^2+11$."},{"title":"Minimum gradient","body":"Since $2(x-4)^2\\ge0$, the minimum value of $\\dfrac{dy}{dx}$ is $11$."},{"title":"Where it occurs","body":"The minimum occurs when $x-4=0$, so $x=4$."},{"title":"Find the point S","body":"At $x=4$, $y=\\dfrac23(4)^3-8(4)^2+43(4)-\\dfrac{20}{3}=80$."},{"title":"Tangent equation","body":"The gradient at $S$ is $11$, so $y-80=11(x-4)$."},{"title":"Simplify","body":"$y=11x+36$."}]},{"id":"WMA11-01_2019_Oct_Q11","year":2019,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2019","qNo":11,"marks":10,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2019_Oct_Q11_M10_13_Integration.png","downloadName":"WMA11-01_Y2019_Oct_Q11_M10_13_Integration.png","finalAnswer":"$(a)\\ y=5x-\\frac{28}{3}.\\quad (b)\\ f(x)=\\frac{16}{3}x^{3/2}-\\frac32x^2+x-12$.","steps":[{"title":"Use the given gradient for the tangent","body":"At $P\\left(4,\\frac{32}{3}\\right)$, $f'(4)=5$, so the tangent has gradient $5$."},{"title":"Find the tangent equation","body":"$y-\\frac{32}{3}=5(x-4)$. Hence $y=5x-\\frac{28}{3}$."},{"title":"Integrate f'' to find f'","body":"$f''(x)=4x^{-1/2}-3$, so $f'(x)=8x^{1/2}-3x+C$."},{"title":"Use f'(4)=5","body":"$5=8(2)-12+C=4+C$, so $C=1$. Therefore $f'(x)=8\\sqrt{x}-3x+1$."},{"title":"Integrate again","body":"$f(x)=\\frac{16}{3}x^{3/2}-\\frac32x^2+x+D$."},{"title":"Use the point on the curve","body":"Substitute $x=4$, $f(4)=\\frac{32}{3}$: $\\frac{32}{3}=\\frac{16}{3}(8)-\\frac32(16)+4+D=\\frac{68}{3}+D$, so $D=-12$."}]},{"id":"WMA11-01_2020_Jan_Q01","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":1,"marks":4,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q01_M04_13_Integration.png","downloadName":"WMA11-01_Y2020_Jan_Q01_M04_13_Integration.png","finalAnswer":"$\\dfrac{2}{3}x^4-\\sqrt{x}-5x+c$.","steps":[{"title":"Rewrite the integrand using powers","body":"$\\dfrac{8x^3}{3}-\\dfrac{1}{2\\sqrt{x}}-5=\\dfrac83x^3-\\dfrac12x^{-1/2}-5$."},{"title":"Integrate term by term","body":"$\\int\\dfrac83x^3\\,dx=\\dfrac23x^4$, $\\int-\\dfrac12x^{-1/2}\\,dx=-x^{1/2}$, and $\\int-5\\,dx=-5x$."},{"title":"Include the constant","body":"Therefore $\\int\\left(\\dfrac{8x^3}{3}-\\dfrac{1}{2\\sqrt{x}}-5\\right)dx=\\dfrac23x^4-\\sqrt{x}-5x+c$."}]},{"id":"WMA11-01_2020_Jan_Q11","year":2020,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2020","qNo":11,"marks":11,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2020_Jan_Q11_M11_13_Integration.png","downloadName":"WMA11-01_Y2020_Jan_Q11_M11_13_Integration.png","finalAnswer":"$(a)\\ y=\\dfrac14x-51.\\quad (b)\\ f(x)=-24\\sqrt{x}+\\dfrac{x^3}{6}-6x+\\dfrac{34}{3}$.","steps":[{"title":"Find the normal gradient","body":"At $P$, $f'(4)=-4$, so the tangent gradient is $-4$. The normal gradient is therefore $\\frac14$."},{"title":"Find the normal equation","body":"Using $P(4,-50)$: $y+50=\\frac14(x-4)$, so $y=\\frac14x-51$."},{"title":"Integrate f'' to find f'","body":"$f''(x)=6x^{-3/2}+x$. Therefore $f'(x)=-12x^{-1/2}+\\frac12x^2+k$."},{"title":"Use f'(4) = -4","body":"$-4=-\\frac{12}{2}+\\frac12(16)+k=-6+8+k=2+k$, so $k=-6$."},{"title":"Integrate again","body":"$f(x)=-24x^{1/2}+\\frac{x^3}{6}-6x+d$."},{"title":"Use the point on the curve","body":"Substitute $P(4,-50)$: $-50=-24(2)+\\frac{64}{6}-24+d=-72+\\frac{32}{3}+d=-\\frac{184}{3}+d$. Hence $d=\\frac{34}{3}$."}]},{"id":"WMA11-01_2021_Jan_Q09","year":2021,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2021","qNo":9,"marks":11,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2021_Jan_Q09_M11_13_Integration.png","downloadName":"WMA11-01_Y2021_Jan_Q09_M11_13_Integration.png","finalAnswer":"$(i)\\ \\dfrac{\\sqrt{x}(9x^2+20x+20)}{10}+c.\\quad (ii)\\ f(x)=\\dfrac{x^3}{3}-2x^2+5x-8$.","steps":[{"title":"Expand and simplify the integrand","body":"$\\dfrac{(3x+2)^2}{4\\sqrt{x}}=\\dfrac{9x^2+12x+4}{4x^{1/2}}=\\dfrac94x^{3/2}+3x^{1/2}+x^{-1/2}$."},{"title":"Integrate term by term","body":"$\\int\\left(\\dfrac94x^{3/2}+3x^{1/2}+x^{-1/2}\\right)dx=\\dfrac9{10}x^{5/2}+2x^{3/2}+2x^{1/2}+c$."},{"title":"Write in simplest form","body":"Factoring out $\\sqrt{x}$ gives $\\dfrac{\\sqrt{x}(9x^2+20x+20)}{10}+c$."},{"title":"Use the gradient condition at P","body":"Since $f'(x)=x^2+ax+b$ and the gradient at $P(3,-2)$ is $2$, $f'(3)=2$. Hence $9+3a+b=2$, so $3a+b=-7$."},{"title":"Integrate f'(x)","body":"$f(x)=\\dfrac{x^3}{3}+\\dfrac{a}{2}x^2+bx+c$. The y-intercept is $-8$, so $c=-8$."},{"title":"Use P(3,-2)","body":"$-2=\\dfrac{27}{3}+\\dfrac{9a}{2}+3b-8$, so $\\dfrac{9a}{2}+3b=-3$."},{"title":"Solve for a and b","body":"From $3a+b=-7$, $b=-7-3a$. Substitute into $\\dfrac{9a}{2}+3b=-3$ to get $a=-4$, and then $b=5$."},{"title":"Write f(x)","body":"Therefore $f(x)=\\dfrac{x^3}{3}-2x^2+5x-8$."}]},{"id":"WMA11-01_2021_MayJune_Q04","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":4,"marks":6,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q04_M06_13_Integration.png","downloadName":"WMA11-01_Y2021_MayJune_Q04_M06_13_Integration.png","finalAnswer":"$\\dfrac{3x^2}{8}-\\dfrac{15x}{4}+\\dfrac{x\\sqrt{x}}{3}-5\\sqrt{x}+c$.","steps":[{"title":"Expand the numerator","body":"$(3\\sqrt{x}+2)(x-5)=3x\\sqrt{x}-15\\sqrt{x}+2x-10$."},{"title":"Divide by 4sqrt(x)","body":"$\\dfrac{(3\\sqrt{x}+2)(x-5)}{4\\sqrt{x}}=\\dfrac{3x}{4}-\\dfrac{15}{4}+\\dfrac12x^{1/2}-\\dfrac52x^{-1/2}$."},{"title":"Integrate term by term","body":"$\\int\\left(\\dfrac{3x}{4}-\\dfrac{15}{4}+\\dfrac12x^{1/2}-\\dfrac52x^{-1/2}\\right)dx=\\dfrac{3x^2}{8}-\\dfrac{15x}{4}+\\dfrac13x^{3/2}-5x^{1/2}+c$."},{"title":"Write each term simply","body":"So the integral is $\\dfrac{3x^2}{8}-\\dfrac{15x}{4}+\\dfrac{x\\sqrt{x}}{3}-5\\sqrt{x}+c$."}]},{"id":"WMA11-01_2021_MayJune_Q06","year":2021,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2021","qNo":6,"marks":8,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2021_MayJune_Q06_M08_12_Differentiation.png","downloadName":"WMA11-01_Y2021_MayJune_Q06_M08_12_Differentiation.png","finalAnswer":"$(a)\\ y=-\\dfrac56x+\\dfrac{26}{3}.\\quad (b)\\ f(x)=-\\dfrac{32}{3x}+3x-\\dfrac32x^{4/3}+\\dfrac{10}{3}$.","steps":[{"title":"Find the gradient at P","body":"$f'(x)=\\dfrac{32}{3x^2}+3-2\\sqrt[3]{x}$. At $x=8$, $f'(8)=\\dfrac{32}{3(64)}+3-2(2)=\\dfrac16-1=-\\dfrac56$."},{"title":"Write the tangent equation","body":"Using $P(8,2)$, $y-2=-\\dfrac56(x-8)$, hence $y=-\\dfrac56x+\\dfrac{26}{3}$."},{"title":"Integrate f'(x)","body":"$f'(x)=\\dfrac{32}{3}x^{-2}+3-2x^{1/3}$, so $f(x)=-\\dfrac{32}{3x}+3x-\\dfrac32x^{4/3}+c$."},{"title":"Use P(8,2) to find c","body":"$2=-\\dfrac{32}{24}+24-\\dfrac32(16)+c=-\\dfrac43+c$, so $c=\\dfrac{10}{3}$."},{"title":"Write f(x)","body":"$f(x)=-\\dfrac{32}{3x}+3x-\\dfrac32x^{4/3}+\\dfrac{10}{3}$."}]},{"id":"WMA11-01_2021_Oct_Q01","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":1,"marks":5,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q01_M05_13_Integration.png","downloadName":"WMA11-01_Y2021_Oct_Q01_M05_13_Integration.png","finalAnswer":"$3x^4+\\dfrac{\\sqrt{x}}{3}+\\dfrac{1}{2x^3}+c$.","steps":[{"title":"Rewrite with powers","body":"$12x^3+\\dfrac{1}{6\\sqrt{x}}-\\dfrac{3}{2x^4}=12x^3+\\dfrac16x^{-1/2}-\\dfrac32x^{-4}$."},{"title":"Integrate term by term","body":"$\\int 12x^3dx=3x^4$, $\\int\\dfrac16x^{-1/2}dx=\\dfrac13x^{1/2}$, and $\\int-\\dfrac32x^{-4}dx=\\dfrac12x^{-3}$."},{"title":"Write in simplest form","body":"Therefore the integral is $3x^4+\\dfrac{\\sqrt{x}}{3}+\\dfrac{1}{2x^3}+c$."}]},{"id":"WMA11-01_2021_Oct_Q10","year":2021,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2021","qNo":10,"marks":7,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2021_Oct_Q10_M07_13_Integration.png","downloadName":"WMA11-01_Y2021_Oct_Q10_M07_13_Integration.png","finalAnswer":"$(a)\\ a=\\dfrac49.\\quad (b)\\ f(x)=\\dfrac{2}{9}x^2-9x^{4/3}+\\dfrac79$.","steps":[{"title":"Differentiate f'(x)","body":"$f'(x)=ax-12x^{1/3}$, so $f''(x)=a-4x^{-2/3}$."},{"title":"Use f''(27) = 0","body":"Since $27^{2/3}=9$, $0=a-\\dfrac{4}{9}$, so $a=\\dfrac49$."},{"title":"Integrate f'(x)","body":"With $a=\\dfrac49$, $f'(x)=\\dfrac49x-12x^{1/3}$. Therefore $f(x)=\\dfrac29x^2-9x^{4/3}+c$."},{"title":"Use the point (1, -8)","body":"$-8=\\dfrac29-9+c$, so $c=-8+9-\\dfrac29=\\dfrac79$."},{"title":"Write f(x)","body":"$f(x)=\\dfrac29x^2-9x^{4/3}+\\dfrac79$."}]},{"id":"WMA11-01_2022_Jan_Q01","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":1,"marks":4,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q01_M04_13_Integration.png","downloadName":"WMA11-01_Y2022_Jan_Q01_M04_13_Integration.png","finalAnswer":"$\\dfrac{2x^4}{5}+\\dfrac{2}{9x^3}-x+c$.","steps":[{"title":"Rewrite using powers","body":"$\\dfrac{8x^3}{5}-\\dfrac{2}{3x^4}-1=\\dfrac85x^3-\\dfrac23x^{-4}-1$."},{"title":"Integrate term by term","body":"$\\int\\dfrac85x^3dx=\\dfrac25x^4$, $\\int-\\dfrac23x^{-4}dx=\\dfrac29x^{-3}$, and $\\int-1dx=-x$."},{"title":"Write in simplest form","body":"Therefore the integral is $\\dfrac{2x^4}{5}+\\dfrac{2}{9x^3}-x+c$."}]},{"id":"WMA11-01_2022_Jan_Q06","year":2022,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2022","qNo":6,"marks":11,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2022_Jan_Q06_M11_13_Integration.png","downloadName":"WMA11-01_Y2022_Jan_Q06_M11_13_Integration.png","finalAnswer":"$(a)(i)\\ \\dfrac{49}{8}.\\quad (a)(ii)\\ 49x-8y-36=0.\\quad (b)\\ f(x)=\\dfrac23x\\sqrt{x}+12\\sqrt{x}-\\dfrac{18}{\\sqrt{x}}-\\dfrac13$.","steps":[{"title":"Simplify f'(x)","body":"$f'(x)=\\dfrac{(x+3)^2}{x\\sqrt{x}}=\\dfrac{x^2+6x+9}{x^{3/2}}=x^{1/2}+6x^{-1/2}+9x^{-3/2}$."},{"title":"Find the gradient at P","body":"At $x=4$, $f'(4)=2+3+\\dfrac98=\\dfrac{49}{8}$."},{"title":"Find the tangent equation","body":"Using $P(4,20)$, $y-20=\\dfrac{49}{8}(x-4)$. Multiplying out gives $49x-8y-36=0$."},{"title":"Integrate f'(x)","body":"$f(x)=\\int\\left(x^{1/2}+6x^{-1/2}+9x^{-3/2}\\right)dx=\\dfrac23x^{3/2}+12x^{1/2}-18x^{-1/2}+c$."},{"title":"Use P(4,20)","body":"$20=\\dfrac23(8)+12(2)-\\dfrac{18}{2}+c=\\dfrac{61}{3}+c$, so $c=-\\dfrac13$."},{"title":"Write f(x)","body":"$f(x)=\\dfrac23x\\sqrt{x}+12\\sqrt{x}-\\dfrac{18}{\\sqrt{x}}-\\dfrac13$."}]},{"id":"WMA11-01_2022_MayJune_Q01","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":1,"marks":4,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q01_M04_13_Integration.png","downloadName":"WMA11-01_Y2022_MayJune_Q01_M04_13_Integration.png","finalAnswer":"$\\dfrac{5}{3}x^6+\\dfrac{3}{2}x^4+\\dfrac{3}{x}+c$.","steps":[{"title":"Rewrite the negative power","body":"$\\int\\left(10x^5+6x^3-\\dfrac{3}{x^2}\\right)dx=\\int(10x^5+6x^3-3x^{-2})dx$."},{"title":"Integrate term by term","body":"$\\int 10x^5dx=\\dfrac{10x^6}{6}=\\dfrac53x^6$, $\\int 6x^3dx=\\dfrac{6x^4}{4}=\\dfrac32x^4$, and $\\int -3x^{-2}dx=3x^{-1}$."},{"title":"Add the constant","body":"Therefore the integral is $\\dfrac53x^6+\\dfrac32x^4+\\dfrac3x+c$."}]},{"id":"WMA11-01_2022_MayJune_Q07","year":2022,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2022","qNo":7,"marks":9,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2022_MayJune_Q07_M09_13_Integration.png","downloadName":"WMA11-01_Y2022_MayJune_Q07_M09_13_Integration.png","finalAnswer":"$f(x)=4\\sqrt{x}+\\dfrac4x+3x-\\dfrac{109}{3}$.","steps":[{"title":"Differentiate f'(x)","body":"$f'(x)=2x^{-1/2}+Ax^{-2}+3$, so $f''(x)=-x^{-3/2}-2Ax^{-3}$."},{"title":"Use f''(4) = 0","body":"$-4^{-3/2}-2A(4^{-3})=0$, so $-\\dfrac18-\\dfrac{A}{32}=0$ and $A=-4$."},{"title":"Substitute A into f'(x)","body":"$f'(x)=\\dfrac2{\\sqrt{x}}-\\dfrac4{x^2}+3$."},{"title":"Integrate to find f(x)","body":"$f(x)=4\\sqrt{x}+\\dfrac4x+3x+c$."},{"title":"Use f(12) = 8sqrt3","body":"$f(12)=8\\sqrt3+\\dfrac13+36+c=8\\sqrt3$, so $c=-\\dfrac{109}{3}$."}]},{"id":"WMA11-01_2022_Oct_Q02","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":2,"marks":7,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q02_M07_13_Integration.png","downloadName":"WMA11-01_Y2022_Oct_Q02_M07_13_Integration.png","finalAnswer":"$(a)\\ a=2,\\ b=-3.\\quad (b)\\ \\dfrac{4}{35}x^{7/2}-\\dfrac{6}{25}x^{5/2}-\\dfrac{64}{15}x^{3/2}-6\\sqrt{x}+c$.","steps":[{"title":"Expand the identity","body":"$(2x+1)(x+3)=2x^2+7x+3$, so $(x-5)(2x^2+7x+3)=2x^3-3x^2-32x-15$."},{"title":"Read off a and b","body":"Comparing with $ax^3+bx^2-32x-15$ gives $a=2$ and $b=-3$."},{"title":"Rewrite the integrand","body":"$\\dfrac{(x-5)(2x+1)(x+3)}{5\\sqrt{x}}=\\dfrac15(2x^{5/2}-3x^{3/2}-32x^{1/2}-15x^{-1/2})$."},{"title":"Integrate term by term","body":"$\\int\\dfrac15(2x^{5/2})dx=\\dfrac{4}{35}x^{7/2}$ and $\\int\\dfrac15(-3x^{3/2})dx=-\\dfrac{6}{25}x^{5/2}$."},{"title":"Complete the integral","body":"$\\int\\dfrac15(-32x^{1/2})dx=-\\dfrac{64}{15}x^{3/2}$ and $\\int\\dfrac15(-15x^{-1/2})dx=-6x^{1/2}$, then add $c$."}]},{"id":"WMA11-01_2022_Oct_Q05","year":2022,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2022","qNo":5,"marks":9,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2022_Oct_Q05_M09_12_Differentiation.png","downloadName":"WMA11-01_Y2022_Oct_Q05_M09_12_Differentiation.png","finalAnswer":"$(a)\\ f(x)=24\\sqrt{x}+\\dfrac{x^2}{6}-4x-\\dfrac{83}{2}.\\quad (b)\\ (0,11)$.","steps":[{"title":"Integrate f'(x)","body":"$f'(x)=12x^{-1/2}+\\dfrac{x}{3}-4$, so $f(x)=24\\sqrt{x}+\\dfrac{x^2}{6}-4x+c$."},{"title":"Use P(9, 8)","body":"$8=24\\sqrt9+\\dfrac{9^2}{6}-4(9)+c=72+\\dfrac{81}{6}-36+c$."},{"title":"Find c","body":"$72+\\dfrac{81}{6}-36=\\dfrac{99}{2}$, so $c=8-\\dfrac{99}{2}=-\\dfrac{83}{2}$."},{"title":"Find the tangent gradient at P","body":"$f'(9)=\\dfrac{12}{3}+\\dfrac93-4=3$."},{"title":"Find the normal gradient","body":"The normal gradient is the negative reciprocal of 3, so it is $-\\dfrac13$."},{"title":"Find the y-intercept","body":"The normal through $(9,8)$ is $y-8=-\\dfrac13(x-9)$, so $y=-\\dfrac13x+11$. It crosses the y-axis at $(0,11)$."}]},{"id":"WMA11-01_2023_Jan_Q03","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":3,"marks":5,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q03_M05_13_Integration.png","downloadName":"WMA11-01_Y2023_Jan_Q03_M05_13_Integration.png","finalAnswer":"$\\dfrac{x^4}{2}-\\dfrac{3}{2x}+c$.","steps":[{"title":"Split the fraction","body":"$\\dfrac{4x^5+3}{2x^2}=2x^3+\\dfrac32x^{-2}$."},{"title":"Integrate the first term","body":"$\\int2x^3dx=\\dfrac{x^4}{2}$."},{"title":"Integrate the second term","body":"$\\int\\dfrac32x^{-2}dx=-\\dfrac32x^{-1}$."},{"title":"Write in simplest form","body":"The integral is $\\dfrac{x^4}{2}-\\dfrac{3}{2x}+c$."}]},{"id":"WMA11-01_2023_Jan_Q11","year":2023,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2023","qNo":11,"marks":8,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2023_Jan_Q11_M08_13_Integration.png","downloadName":"WMA11-01_Y2023_Jan_Q11_M08_13_Integration.png","finalAnswer":"$(a)\\ y-16=-\\dfrac13(x-4).\\quad (b)\\ f(x)=\\dfrac23x^3+\\dfrac43x^{3/2}-33x+\\dfrac{284}{3}$.","steps":[{"title":"Find point P","body":"Since $P$ has x-coordinate 4 and lies on the tangent $y=3x+4$, $P=(4,16)$."},{"title":"Find the normal","body":"The tangent gradient is 3, so the normal gradient is $-\\dfrac13$. Hence the normal is $y-16=-\\dfrac13(x-4)$."},{"title":"Integrate f''(x)","body":"$f''(x)=4x+x^{-1/2}$, so $f'(x)=2x^2+2\\sqrt{x}+A$."},{"title":"Use the tangent gradient","body":"At $x=4$, $f'(4)=3$. Thus $2(16)+2(2)+A=3$, so $A=-33$."},{"title":"Integrate again","body":"$f(x)=\\dfrac23x^3+\\dfrac43x^{3/2}-33x+B$."},{"title":"Use P(4, 16)","body":"$16=\\dfrac23(64)+\\dfrac43(8)-33(4)+B=\\dfrac{160}{3}-132+B$."},{"title":"Find B","body":"$B=\\dfrac{284}{3}$, so $f(x)=\\dfrac23x^3+\\dfrac43x^{3/2}-33x+\\dfrac{284}{3}$."}]},{"id":"WMA11-01_2023_MayJune_Q08","year":2023,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2023","qNo":8,"marks":10,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2023_MayJune_Q08_M10_13_Integration.png","downloadName":"WMA11-01_Y2023_MayJune_Q08_M10_13_Integration.png","finalAnswer":"$(a)\\ 25x-2y-76=0.\\quad (b)\\ f(x)=\\dfrac{x^4}{16}-16\\sqrt{x}+28$.","steps":[{"title":"Differentiate the curve","body":"For $y=\\dfrac14x^3-8x^{-1/2}$, $\\dfrac{dy}{dx}=\\dfrac34x^2+4x^{-3/2}$."},{"title":"Find the gradient at P","body":"At $x=4$, $\\dfrac{dy}{dx}=\\dfrac34(16)+4(4^{-3/2})=12+\\dfrac12=\\dfrac{25}{2}$."},{"title":"Find the tangent","body":"Using $P(4,12)$, $y-12=\\dfrac{25}{2}(x-4)$."},{"title":"Write in integer form","body":"Multiplying by 2 gives $2y-24=25x-100$, hence $25x-2y-76=0$."},{"title":"Integrate f'(x)","body":"$f'(x)=\\dfrac14x^3-8x^{-1/2}$ gives $f(x)=\\dfrac{x^4}{16}-16\\sqrt{x}+c$."},{"title":"Use P(4, 12)","body":"$12=\\dfrac{4^4}{16}-16\\sqrt4+c=16-32+c$, so $c=28$."}]},{"id":"WMA11-01_2023_Oct_Q07","year":2023,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2023","qNo":7,"marks":10,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2023_Oct_Q07_M10_13_Integration.png","downloadName":"WMA11-01_Y2023_Oct_Q07_M10_13_Integration.png","finalAnswer":"$(a)(i)\\ \\dfrac{15}{2}.\\quad (a)(ii)\\ 2x+15y+7=0.\\quad (b)\\ f(x)=\\dfrac25x^{5/2}+5x^{1/2}-\\dfrac74x-\\dfrac{84}{5}$.","steps":[{"title":"Simplify f prime","body":"$f'(x)=\\dfrac{4x^2+10-7x^{1/2}}{4x^{1/2}}=x^{3/2}+\\dfrac52x^{-1/2}-\\dfrac74$."},{"title":"Find the gradient at P","body":"At $x=4$, $f'(4)=4^{3/2}+\\dfrac52(4^{-1/2})-\\dfrac74=8+\\dfrac54-\\dfrac74=\\dfrac{15}{2}$."},{"title":"Find the normal gradient","body":"The normal gradient is the negative reciprocal, so $m_n=-\\dfrac{2}{15}$."},{"title":"Use point P","body":"Using $P(4,-1)$, $y+1=-\\dfrac{2}{15}(x-4)$."},{"title":"Write the normal in integer form","body":"$15y+15=-2x+8$, hence $2x+15y+7=0$."},{"title":"Integrate f prime","body":"$f(x)=\\int\\left(x^{3/2}+\\dfrac52x^{-1/2}-\\dfrac74\\right)dx=\\dfrac25x^{5/2}+5x^{1/2}-\\dfrac74x+c$."},{"title":"Use P to find c","body":"$-1=\\dfrac25(4^{5/2})+5(4^{1/2})-\\dfrac74(4)+c=\\dfrac{64}{5}+10-7+c$, so $c=-\\dfrac{84}{5}$."}]},{"id":"WMA11-01_2024_Jan_Q01","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":1,"marks":5,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q01_M05_13_Integration.png","downloadName":"WMA11-01_Y2024_Jan_Q01_M05_13_Integration.png","finalAnswer":"$3x^4+\\dfrac83x^3-\\dfrac{75}{2}x^2-50x+c$.","steps":[{"title":"Expand two brackets first","body":"$(2x-5)(3x+2)=6x^2-11x-10$."},{"title":"Multiply by the third bracket","body":"$(6x^2-11x-10)(2x+5)=12x^3+8x^2-75x-50$."},{"title":"Integrate term by term","body":"$\\int(12x^3+8x^2-75x-50)\\,dx=3x^4+\\dfrac83x^3-\\dfrac{75}{2}x^2-50x+c$."}]},{"id":"WMA11-01_2024_Jan_Q10","year":2024,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2024","qNo":10,"marks":8,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2024_Jan_Q10_M08_13_Integration.png","downloadName":"WMA11-01_Y2024_Jan_Q10_M08_13_Integration.png","finalAnswer":"$(a)\\ k=24\\sqrt2.\\quad (b)\\ f(x)=\\dfrac85x^{5/2}-\\dfrac{24\\sqrt2}{x}+\\dfrac{68\\sqrt2}{5}$.","steps":[{"title":"Differentiate f prime","body":"$f'(x)=4x^{3/2}+kx^{-2}$, so $f''(x)=6x^{1/2}-2kx^{-3}$."},{"title":"Use f double prime equals zero at P","body":"At $P$, $x=2$ and $f''(2)=0$, so $6\\sqrt2-2k(2^{-3})=0$."},{"title":"Find k","body":"$6\\sqrt2-\\dfrac{k}{4}=0$, hence $k=24\\sqrt2$."},{"title":"Integrate f prime","body":"$f(x)=\\int\\left(4x^{3/2}+24\\sqrt2x^{-2}\\right)dx=\\dfrac85x^{5/2}-24\\sqrt2x^{-1}+c$."},{"title":"Use the point P","body":"$P(2,8\\sqrt2)$ lies on $C$, so $8\\sqrt2=\\dfrac85(2^{5/2})-\\dfrac{24\\sqrt2}{2}+c$."},{"title":"Find c","body":"$8\\sqrt2=\\dfrac{32\\sqrt2}{5}-12\\sqrt2+c$, so $c=\\dfrac{68\\sqrt2}{5}$."}]},{"id":"WMA11-01_2024_MayJune_Q01","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":1,"marks":3,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q01_M03_13_Integration.png","downloadName":"WMA11-01_Y2024_MayJune_Q01_M03_13_Integration.png","finalAnswer":"$2x^5+\\dfrac{3}{4x^2}-7x+c$.","steps":[{"title":"Rewrite the fraction","body":"$10x^4-\\dfrac{3}{2x^3}-7=10x^4-\\dfrac32x^{-3}-7$."},{"title":"Integrate term by term","body":"$\\int10x^4\\,dx=2x^5$, $\\int-\\dfrac32x^{-3}\\,dx=\\dfrac34x^{-2}$, and $\\int-7\\,dx=-7x$."},{"title":"Write in simplest form","body":"$2x^5+\\dfrac{3}{4x^2}-7x+c$."}]},{"id":"WMA11-01_2024_MayJune_Q10","year":2024,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2024","qNo":10,"marks":10,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2024_MayJune_Q10_M10_13_Integration.png","downloadName":"WMA11-01_Y2024_MayJune_Q10_M10_13_Integration.png","finalAnswer":"$(a)\\ y=2x+4.\\quad (b)\\ f(x)=3x^2-\\dfrac65x^{5/2}-\\dfrac13x^{3/2}+2x^{1/2}+\\dfrac{16}{15}$.","steps":[{"title":"Expand the numerator","body":"$(2x-1)(3x+2)=6x^2+x-2$."},{"title":"Simplify f prime","body":"$f'(x)=6x-\\dfrac{6x^2+x-2}{2\\sqrt{x}}=6x-3x^{3/2}-\\dfrac12x^{1/2}+x^{-1/2}$."},{"title":"Find the tangent gradient at P","body":"$f'(4)=24-3(8)-\\dfrac12(2)+\\dfrac12=-\\dfrac12$."},{"title":"Use the normal gradient","body":"The normal gradient is the negative reciprocal of $-\\dfrac12$, so it is $2$."},{"title":"Find the normal equation","body":"Through $P(4,12)$, $y-12=2(x-4)$, hence $y=2x+4$."},{"title":"Integrate f prime","body":"$f(x)=3x^2-\\dfrac65x^{5/2}-\\dfrac13x^{3/2}+2x^{1/2}+c$."},{"title":"Use P to find c","body":"$12=3(4)^2-\\dfrac65(4^{5/2})-\\dfrac13(4^{3/2})+2(4^{1/2})+c$."},{"title":"Simplify c","body":"$12=48-\\dfrac{192}{5}-\\dfrac83+4+c=\\dfrac{164}{15}+c$, so $c=\\dfrac{16}{15}$."}]},{"id":"WMA11-01_2024_Oct_Q03","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":3,"marks":9,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q03_M09_13_Integration.png","downloadName":"WMA11-01_Y2024_Oct_Q03_M09_13_Integration.png","finalAnswer":"$(a)\\ \\dfrac25x^{5/2}+\\dfrac{20}{3}x^{3/2}+50x^{1/2}+c.\\quad (b)\\ x=\\dfrac53$.","steps":[{"title":"Rewrite f(x)","body":"$f(x)=\\dfrac{(x+5)^2}{\\sqrt{x}}=\\dfrac{x^2+10x+25}{x^{1/2}}=x^{3/2}+10x^{1/2}+25x^{-1/2}$."},{"title":"Integrate","body":"$\\int f(x)\\,dx=\\dfrac25x^{5/2}+\\dfrac{20}{3}x^{3/2}+50x^{1/2}+c$."},{"title":"Differentiate f(x)","body":"$f'(x)=\\dfrac32x^{1/2}+5x^{-1/2}-\\dfrac{25}{2}x^{-3/2}$."},{"title":"Set f prime equal to zero","body":"$\\dfrac32x^{1/2}+5x^{-1/2}-\\dfrac{25}{2}x^{-3/2}=0$."},{"title":"Clear powers of x","body":"Multiplying by $2x^{3/2}$ gives $3x^2+10x-25=0$."},{"title":"Use x greater than zero","body":"$3x^2+10x-25=(3x-5)(x+5)$, so $x=\\dfrac53$ or $x=-5$. Since $x>0$, $x=\\dfrac53$."}]},{"id":"WMA11-01_2024_Oct_Q08","year":2024,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2024","qNo":8,"marks":7,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2024_Oct_Q08_M07_13_Integration.png","downloadName":"WMA11-01_Y2024_Oct_Q08_M07_13_Integration.png","finalAnswer":"$k=-5$ and $f(x)=\\dfrac43x^3-\\dfrac52x^2+3x-\\dfrac{141}{8}$.","steps":[{"title":"Find the y-coordinate of P","body":"The normal is $y=-\\dfrac1{24}x+5$. At $x=3$, $y=-\\dfrac3{24}+5=\\dfrac{39}{8}$."},{"title":"Use the normal gradient","body":"The normal gradient is $-\\dfrac1{24}$, so the tangent gradient is $24$."},{"title":"Use f prime at x equals 3","body":"$f'(3)=4(3)^2+3k+3=39+3k$."},{"title":"Find k","body":"$39+3k=24$, so $k=-5$."},{"title":"Integrate f prime","body":"With $k=-5$, $f'(x)=4x^2-5x+3$, so $f(x)=\\dfrac43x^3-\\dfrac52x^2+3x+c$."},{"title":"Use point P","body":"$\\dfrac{39}{8}=\\dfrac43(27)-\\dfrac52(9)+3(3)+c=\\dfrac{45}{2}+c$."},{"title":"Find c","body":"$c=\\dfrac{39}{8}-\\dfrac{45}{2}=-\\dfrac{141}{8}$."}]},{"id":"WMA11-01_2025_Jan_Q01","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":1,"marks":4,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q01_M04_13_Integration.png","downloadName":"WMA11-01_Y2025_Jan_Q01_M04_13_Integration.png","finalAnswer":"$2x^4-4x^{3/2}+\\dfrac{1}{5x^2}+c$.","steps":[{"title":"Rewrite with powers","body":"$8x^3-6\\sqrt{x}-\\dfrac{2}{5x^3}=8x^3-6x^{1/2}-\\dfrac25x^{-3}$."},{"title":"Integrate term by term","body":"$\\int8x^3\\,dx=2x^4$, $\\int-6x^{1/2}\\,dx=-4x^{3/2}$, and $\\int-\\dfrac25x^{-3}\\,dx=\\dfrac15x^{-2}$."},{"title":"Write in simplest form","body":"$2x^4-4x^{3/2}+\\dfrac{1}{5x^2}+c$."}]},{"id":"WMA11-01_2025_Jan_Q06","year":2025,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2025","qNo":6,"marks":10,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2025_Jan_Q06_M10_12_Differentiation.png","downloadName":"WMA11-01_Y2025_Jan_Q06_M10_12_Differentiation.png","finalAnswer":"$(b)\\ f(x)=\\dfrac15x^{5/2}+\\dfrac{11}{6}x^{3/2}-10x^{1/2}-\\dfrac{91}{15}.\\quad (c)\\ Q=(7,-5)$.","steps":[{"title":"Use the gradient at P","body":"At $x=4$, $f'(4)=7$. Since $f'(x)=\\dfrac{2x^2+ax+b}{4\\sqrt{x}}$, we get $\\dfrac{32+4a+b}{8}=7$."},{"title":"Show the required equation","body":"$32+4a+b=56$, so $4a+b=24$."},{"title":"Solve for a and b","body":"Together with $a+b=-9$, subtracting gives $3a=33$, so $a=11$ and $b=-20$."},{"title":"Rewrite f prime","body":"$f'(x)=\\dfrac{2x^2+11x-20}{4\\sqrt{x}}=\\dfrac12x^{3/2}+\\dfrac{11}{4}x^{1/2}-5x^{-1/2}$."},{"title":"Integrate","body":"$f(x)=\\dfrac15x^{5/2}+\\dfrac{11}{6}x^{3/2}-10x^{1/2}+c$."},{"title":"Use P to find c","body":"$-5=\\dfrac15(4^{5/2})+\\dfrac{11}{6}(4^{3/2})-10(4^{1/2})+c=\\dfrac{16}{15}+c$."},{"title":"State f(x)","body":"$c=-\\dfrac{91}{15}$, so $f(x)=\\dfrac15x^{5/2}+\\dfrac{11}{6}x^{3/2}-10x^{1/2}-\\dfrac{91}{15}$."},{"title":"Transform P","body":"$y=f(x-3)$ translates the curve 3 units to the right, so $P(4,-5)$ becomes $Q(7,-5)$."}]},{"id":"WMA11-01_2025_MayJune_Q03","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":3,"marks":5,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q03_M05_01_Indices_Surds.png","downloadName":"WMA11-01_Y2025_MayJune_Q03_M05_01_Indices_Surds.png","finalAnswer":"$\\dfrac{2}{15}x^{5/2}+\\dfrac43x^{3/2}+6x^{1/2}+c$.","steps":[{"title":"Expand the numerator","body":"$(x+3)^2=x^2+6x+9$."},{"title":"Divide by the denominator","body":"$\\dfrac{(x+3)^2}{3\\sqrt{x}}=\\dfrac{x^2+6x+9}{3x^{1/2}}=\\dfrac13x^{3/2}+2x^{1/2}+3x^{-1/2}$."},{"title":"Integrate term by term","body":"$\\int\\left(\\dfrac13x^{3/2}+2x^{1/2}+3x^{-1/2}\\right)dx=\\dfrac13\\cdot\\dfrac25x^{5/2}+2\\cdot\\dfrac23x^{3/2}+3\\cdot2x^{1/2}+c$."},{"title":"Simplify","body":"$\\dfrac{2}{15}x^{5/2}+\\dfrac43x^{3/2}+6x^{1/2}+c$."}]},{"id":"WMA11-01_2025_MayJune_Q08","year":2025,"session":"MayJune","paperCode":"WMA11-01","paper":"WMA11/01 May/June 2025","qNo":8,"marks":11,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2025_MayJune_Q08_M11_13_Integration.png","downloadName":"WMA11-01_Y2025_MayJune_Q08_M11_13_Integration.png","finalAnswer":"$(a)(i)\\ k=\\dfrac14.\\quad (a)(ii)\\ c=-28.\\quad (b)\\ f''(P)=\\dfrac{11}{4}.\\quad (c)\\ f(x)=2x^{3/2}+\\dfrac1{12}x^3-\\dfrac{28}{3}$.","steps":[{"title":"Use the tangent gradient","body":"The tangent at $P$ has equation $y=10x+c$, so the gradient at $P$ is $10$."},{"title":"Show k","body":"$f'(4)=3\\sqrt4+k(4)^2=6+16k=10$, so $16k=4$ and $k=\\dfrac14$."},{"title":"Find c","body":"Substitute $P(4,12)$ into $y=10x+c$: $12=40+c$, so $c=-28$."},{"title":"Differentiate f prime","body":"With $k=\\dfrac14$, $f'(x)=3x^{1/2}+\\dfrac14x^2$."},{"title":"Find f double prime","body":"$f''(x)=\\dfrac32x^{-1/2}+\\dfrac12x$."},{"title":"Evaluate at P","body":"$f''(4)=\\dfrac32\\cdot\\dfrac12+2=\\dfrac34+2=\\dfrac{11}{4}$."},{"title":"Integrate f prime","body":"$f(x)=\\int\\left(3x^{1/2}+\\dfrac14x^2\\right)dx=2x^{3/2}+\\dfrac1{12}x^3+d$."},{"title":"Use P to find d","body":"$12=2(4^{3/2})+\\dfrac1{12}(4^3)+d=16+\\dfrac{16}{3}+d$."},{"title":"State f(x)","body":"$d=-\\dfrac{28}{3}$, so $f(x)=2x^{3/2}+\\dfrac1{12}x^3-\\dfrac{28}{3}$."}]},{"id":"WMA11-01_2025_Oct_Q02","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":2,"marks":5,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q02_M05_13_Integration.png","downloadName":"WMA11-01_Y2025_Oct_Q02_M05_13_Integration.png","finalAnswer":"$\\dfrac12x^4-\\dfrac73x^3-6x^2+45x+c$.","steps":[{"title":"Expand the square","body":"$(x-3)^2=x^2-6x+9$."},{"title":"Multiply out","body":"$(x^2-6x+9)(2x+5)=2x^3+5x^2-12x^2-30x+18x+45$."},{"title":"Collect terms","body":"$(x-3)^2(2x+5)=2x^3-7x^2-12x+45$."},{"title":"Integrate term by term","body":"$\\int(2x^3-7x^2-12x+45)dx=\\dfrac12x^4-\\dfrac73x^3-6x^2+45x+c$."}]},{"id":"WMA11-01_2025_Oct_Q08","year":2025,"session":"Oct","paperCode":"WMA11-01","paper":"WMA11/01 October 2025","qNo":8,"marks":8,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2025_Oct_Q08_M08_12_Differentiation.png","downloadName":"WMA11-01_Y2025_Oct_Q08_M08_12_Differentiation.png","finalAnswer":"$(a)\\ k=1-2\\sqrt2.\\quad (b)\\ y=-\\dfrac15x+\\dfrac{11\\sqrt2}{5}.\\quad (c)\\ f(x)=x^2-\\dfrac8x+(1-2\\sqrt2)x+2+5\\sqrt2$.","steps":[{"title":"Use tangent gradient","body":"The tangent has equation $y=5x-3\\sqrt2$, so the gradient at $x=\\sqrt2$ is $5$."},{"title":"Find k","body":"$f'(\\sqrt2)=2\\sqrt2+\\dfrac8{(\\sqrt2)^2}+k=2\\sqrt2+4+k=5$, so $k=1-2\\sqrt2$."},{"title":"Find the point on the curve","body":"At $x=\\sqrt2$, the tangent gives $y=5\\sqrt2-3\\sqrt2=2\\sqrt2$."},{"title":"Normal gradient","body":"The tangent gradient is $5$, so the normal gradient is $-\\dfrac15$."},{"title":"Equation of the normal","body":"$y-2\\sqrt2=-\\dfrac15(x-\\sqrt2)$, hence $y=-\\dfrac15x+\\dfrac{11\\sqrt2}{5}$."},{"title":"Integrate f prime","body":"$f(x)=\\int\\left(2x+\\dfrac8{x^2}+k\\right)dx=x^2-\\dfrac8x+kx+c$."},{"title":"Substitute k","body":"$f(x)=x^2-\\dfrac8x+(1-2\\sqrt2)x+c$."},{"title":"Use the point","body":"$2\\sqrt2=2-\\dfrac8{\\sqrt2}+(1-2\\sqrt2)\\sqrt2+c=-2-3\\sqrt2+c$."},{"title":"Find c","body":"$c=2+5\\sqrt2$, so $f(x)=x^2-\\dfrac8x+(1-2\\sqrt2)x+2+5\\sqrt2$."}]},{"id":"WMA11-01_2026_Jan_Q01","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":1,"marks":6,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q01_M06_13_Integration.png","downloadName":"WMA11-01_Y2026_Jan_Q01_M06_13_Integration.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=12x^2-\\dfrac{3}{4x^{3/2}}.\\quad (b)\\ \\int y\\,dx=x^4+3\\sqrt{x}-8x+c$.","steps":[{"title":"Rewrite with powers","body":"$y=4x^3+\\dfrac{3}{2}x^{-1/2}-8$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=12x^2+\\dfrac32\\left(-\\dfrac12\\right)x^{-3/2}$."},{"title":"Simplify derivative","body":"$\\dfrac{dy}{dx}=12x^2-\\dfrac34x^{-3/2}=12x^2-\\dfrac{3}{4x^{3/2}}$."},{"title":"Integrate","body":"$\\int y\\,dx=\\int\\left(4x^3+\\dfrac32x^{-1/2}-8\\right)dx$."},{"title":"Simplify integral","body":"$\\int y\\,dx=x^4+3x^{1/2}-8x+c=x^4+3\\sqrt{x}-8x+c$."}]},{"id":"WMA11-01_2026_Jan_Q08","year":2026,"session":"Jan","paperCode":"WMA11-01","paper":"WMA11/01 January 2026","qNo":8,"marks":12,"topic":"13_Integration","topicName":"Integration","image":"ial/wma11/questions/WMA11-01_Y2026_Jan_Q08_M12_13_Integration.png","downloadName":"WMA11-01_Y2026_Jan_Q08_M12_13_Integration.png","finalAnswer":"$(a)(i)$ verified. $(a)(ii)\\ x=\\dfrac{\\sqrt2}{2}.\\quad (b)\\ y-4\\sqrt3=-\\dfrac1{10}(x-\\sqrt3).\\quad (c)\\ f(x)=\\dfrac43x^3-\\dfrac6x-4x+6\\sqrt3$.","steps":[{"title":"Verify x equals root 3","body":"$f'(\\sqrt3)=4(\\sqrt3)^2+\\dfrac6{(\\sqrt3)^2}-4=12+2-4=10$, which matches the tangent gradient."},{"title":"Find all possible x-coordinates","body":"Set $4x^2+\\dfrac6{x^2}-4=10$."},{"title":"Form a quadratic in x squared","body":"Multiplying by $x^2$ gives $4x^4-14x^2+6=0$, so $2x^4-7x^2+3=0$."},{"title":"Factor","body":"$2x^4-7x^2+3=(2x^2-1)(x^2-3)=0$."},{"title":"Use x greater than zero","body":"$x=\\sqrt3$ or $x=\\dfrac1{\\sqrt2}=\\dfrac{\\sqrt2}{2}$. The other possible x-coordinate is $\\dfrac{\\sqrt2}{2}$."},{"title":"Find the point P","body":"Given $x_P=\\sqrt3$, the tangent gives $y_P=10\\sqrt3-6\\sqrt3=4\\sqrt3$."},{"title":"Normal equation","body":"The normal gradient is $-\\dfrac1{10}$, so $y-4\\sqrt3=-\\dfrac1{10}(x-\\sqrt3)$."},{"title":"Integrate f prime","body":"$f(x)=\\int\\left(4x^2+\\dfrac6{x^2}-4\\right)dx=\\dfrac43x^3-\\dfrac6x-4x+c$."},{"title":"Use P to find c","body":"$4\\sqrt3=\\dfrac43(\\sqrt3)^3-\\dfrac6{\\sqrt3}-4\\sqrt3+c=4\\sqrt3-2\\sqrt3-4\\sqrt3+c$."},{"title":"State f(x)","body":"$c=6\\sqrt3$, so $f(x)=\\dfrac43x^3-\\dfrac6x-4x+6\\sqrt3$."}]}];
